INSERT INTO feature VALUES('abi-realizability','runtime','Layouts as realizability predicates','foreign-calls','partial','uncommon','mainstream languages','A type''s realisers are a predicate on a word and a heap written as data, the separating conjunction a sigma over a disjoint split and points-to a singleton, so the normaliser computes every assertion and the kernel replays it (Wagner, Eisbach and Ahmed, OOPSLA 2024): `Option<&T>`''s null niche is equivalent at every heap to the two-word tagged layout, its marshallers meet their triples, and a C `deref_or` specified by hand is met by it, its `_Nonnull` neighbour refused. A Rust extern''s function row, `std.boundary`, reads each argument''s and the result''s witness record off its code by Rust''s default layout and is admitted against the signature rustc printed by a run, a differing signature unrealised by the clause it breaks: size, alignment, niche, drop or arity. An `extern "rust"` block naming its members'' rows is admitted where it is declared, by a run of `admitBlock` over the codes of its fixed-width atoms. `deref_or` runs on the word a Rust caller passes for an `Option<&u32>`, the null word answering its default and any other the `u32` the caller''s host reads there, as Rust''s own does. The logic is not yet a theory, and the C side''s specification is assumed until a foreign declaration lowers.',NULL,'library/std/src/boundary.gandr corpus/model/specification/niche-realizability.gandr corpus/pathological/specification/niche-realizability.gandr corpus/model/interop/boundary/function-row.gandr corpus/pathological/interop/boundary/function-row.gandr corpus/model/interop/boundary/round-trip.gandr corpus/model/interop/boundary/by-layout.gandr','corpus/ledger/features/abi-realizability.gandr','#2835 #327','#2838 #3033 #3099 #3118 #3154');
INSERT INTO feature VALUES('abstract-closures','machine','Abstract closures in the sequent IL','sequent-machine','partial','notable',NULL,'A closure former of the focused IL carries an environment of values its code reads by index, and entering it binds the environment and the frame''s arguments together; conversion moves each intuitionistic context variable the code names into the environment, one at a time and the greatest first, and a converted program runs to what it ran to as written, on every tier for generated programs and on the portable executor for every `runs` item of the corpus. A closure''s type records no summary of its environment, a linear capture stays captured by support, and environment sharing, lambda sets and a run path that converts are owed.','core-sequent surface-dispatcher','corpus/ledger/features/abstract-closures.gandr crates/core-sequent/tests/closures.rs crates/surface-dispatcher/src/evaluate.rs','corpus/ledger/features/abstract-closures.gandr','#3077 #2770','#3094');
INSERT INTO feature VALUES('access-modes','effects','Access modes (shared and exclusive)','temporary-access','implemented','uncommon','mainstream languages','An access lends its held value shared or exclusive: shared beside shared, nothing beside exclusive; a shared view is read-only, ends with its body, and is the held cell itself, with no allocation.','core-term core-checker runtime-emitter surface-lowering','corpus/model/control/accessor-shared.gandr corpus/pathological/control/accessor-shared.gandr corpus/pathological/self-reference/written-while-kept.gandr','corpus/model/control/accessor-shared.gandr',NULL,'#1180 #1438');
INSERT INTO feature VALUES('accessibility','recursion','Accessibility under the stage order','structural-recursion','implemented','notable',NULL,'The occurrence walk as accessibility under the stage order in both checkers: a family under a function''s domain makes its block stratified and sits at the stage a case opens, Curry''s consumer refused StageNotBelow at its call; nesting through a strictly positive parameter declares (the rose tree over List directly).','core-checker kernel-core','corpus/model/data/stratified.gandr corpus/pathological/data/curry.gandr corpus/model/data/rose.gandr','corpus/model/data/stratified.gandr','#392 #517','#618');
INSERT INTO feature VALUES('acset-store','storage','C-set stores with checked equations',NULL,'implemented','uncommon','mainstream languages','A schema of objects, arrows, attributes and path equations, its store checked against the equations on every edit and proved against one root.','storage-schema','crates/storage-schema/tests/equations.rs crates/storage-schema/tests/proofs.rs',NULL,'#317','#348');
INSERT INTO feature VALUES('answer-totality','tooling','Answer totality as lints','hover','implemented','uncommon','mainstream editors','The static half of the hover and printer guarantee as three dylints in the wall: a dishonest answer (?) is constructible only under an expect with its reason; every former has a presenter arm; the printer''s productions and the grammar''s rules are one set, the unproduced table reasoned. The residue enumerated: 44 expects over 68 builds, 87 unproduced rules with reasons.','surface-pretty surface-lsp surface-lowering','',NULL,'quenchant#52 #2637','#632');
INSERT INTO feature VALUES('apartness','identity','Apartness of distinct normal forms','identity-types','implemented','notable',NULL,'A path between two terms whose normal forms first differ at distinct constructors is eliminated by a case of no arms, the kernel re-deriving the apartness: closed terms of a presented type, and terms of a free type whatever variables they hold.','core-checker kernel-core kernel-term','corpus/model/identity/circle-apart.gandr corpus/model/data/empty.gandr corpus/model/data/open-apart.gandr corpus/pathological/data/open-apart.gandr','corpus/model/identity/circle-apart.gandr',NULL,'#384 #1964');
INSERT INTO feature VALUES('artifact-store','storage','Kernel artifacts on the record and value planes',NULL,'implemented','uncommon','mainstream languages','A kernel artifact is stored one record per declaration under a BLAKE3 manifest identity, or commits through the value plane as one value whose declaration segments each hold the one before, so an edit to a declaration shares every chunk before it; either is read back through the kernel''s decoder.','storage-artifact','crates/storage-artifact/tests/artifact_contract.rs',NULL,'#3225','#8 #3274');
INSERT INTO feature VALUES('ascription','calculus','Type ascription','call-by-push-value','implemented','ordinary',NULL,'A term ascribed a type synthesises it and checks the term against it: `(e : T)` ascribes the value it encloses wherever a value is read, an application''s head included, a computation is ascribed by `run d : T <- e`, which binds at a written type, a name or a tuple pattern alike, and the kernel replays each stated type where it synthesises.','core-term core-checker kernel-core surface-lowering','corpus/surface/typed-bind.gandr corpus/surface/typed-bind-parameters.gandr corpus/pathological/basics/ill-typed-ascription.gandr corpus/model/basics/annotations.gandr corpus/pathological/basics/annotations.gandr','corpus/surface/typed-bind.gandr',NULL,'#432 #1543 #2177');
INSERT INTO feature VALUES('atom-identity','identity','Identity at a sealed type','identity-by-recursion','partial','unique','dependent provers','A sealed type''s type member names its identity, @[ identity((relation, reflexivity, law)) ]: a reflexive relation whose singletons contract onto reflexivity is the type''s identity, so the relation''s evidence is a path at the atom and based path induction runs over it, computing along that evidence in a family reading neither entry, and in a family of identities at the atom, or of identities of them, whose relation returns the code of the unit type or of an identity of it outright, returning the unit; a relation returning the paths between its points is lawful by the same law; an interface naming no law refuses that evidence as AtomTransport.','surface-lowering core-checker core-nbe kernel-core','corpus/model/identity/atom-identity.gandr corpus/pathological/identity/atom-identity.gandr','corpus/ledger/features/atom-identity.gandr','#2053','#1872 #1909 #1974 #2068 #2722');
INSERT INTO feature VALUES('atom-sorts','descriptions','Atom sorts','levitated-descriptions','partial','notable',NULL,'A theory block declares an atom sort, `sort Name : Atom;`, whose elements have equality and swapping as their only structure; the Theory value keeps it under its own tag, a binder over it is refused by name, and an operation''s port abstracts its atoms with `bind (a : Name) .` beside `pi+`, a model of such an operation refused by name. A rule term abstracts an atom at such a port, `bind a . t`, and only there: at a `pi+` port the same spelling is the port''s binding field (`second-order-rules`). Matching, the critical pairs and the kernel read an abstraction up to the atom it names. Inside its abstraction a rule term names the atom, an occurrence counted by the abstractions between it and its binder, and an inspected call reads one alike. Where a port takes an atom, a rule stating a freshness condition or moving a variable across an abstraction fires only where its instance names no atom it may not, counting a moved instance''s atoms to their abstractions'' new places, and its overlaps are decided under the condition they compose (`rule-conditions`); a variable split across an abstraction on a left side is refused as undecided.','theory-levitation surface-lowering theory-computads kernel-term','corpus/model/desc/atom-sorts.gandr corpus/pathological/desc/atom-sorts.gandr corpus/model/desc/bind-port.gandr corpus/pathological/desc/bind-port.gandr corpus/model/desc/bind-term.gandr corpus/pathological/desc/bind-term.gandr corpus/model/desc/atom-occurrence.gandr corpus/pathological/desc/atom-occurrence.gandr','corpus/ledger/features/atom-sorts.gandr','#1430 #1561 #1934','#1570 #1616 #1696 #1943 #1956 #2350 #2481 #2722');
INSERT INTO feature VALUES('attested-verdict-cache','kernel','The attested kernel verdict cache','kernel-readmission','partial','uncommon','dependent provers','`gandr check` keeps each declaration its kernel checked as a record keyed by BLAKE3 over the kernel''s whole input — its build, then each declaration admitted before it, segment by segment — under a receipt this installation''s Ed25519 key signs, and a later `check` admits a declaration on a recorded verdict only under a receipt a key its policy trusts signed: its own and each `kernel.trusted` lists. `--recheck`, `kernel.policy = "recheck"`, `gandr test`, the language server and the corpus gate check every declaration. Owed: a key narrowed to what the declaration reads (#2797), and the store on the workspace''s record plane (#3157).','kernel-term kernel-core core-checker core-incremental surface-dispatcher surface-driver','crates/kernel-core/tests/verdicts.rs crates/core-checker/src/bridge/tests.rs crates/core-incremental/src/verdicts/tests.rs crates/surface-driver/tests/cli.rs',NULL,'#2797 #3157','#2799');
INSERT INTO feature VALUES('attributes','attributes','Attributes',NULL,'implemented','ordinary',NULL,'`@[ … ]` attaches registered attributes to a declaration, an unknown name or an ill-typed payload refused by name; a payload may be named, `decomposes(primes = 2)`, where the attribute reads one.','surface-lowering surface-grammar','corpus/model/attributes/long-attribute-blocks.gandr corpus/pathological/attributes/unknown-attribute.gandr corpus/model/sessions/dialogue-web.gandr crates/surface-lowering/src/lower.rs::a_named_payload_is_spelled_with_its_name_2077','corpus/model/attributes/long-attribute-blocks.gandr',NULL,'338fee9 #2156');
INSERT INTO feature VALUES('axiom-audit','kernel','Axiom and assumption audit','kernel-admission','implemented','notable',NULL,'Admission reports every declaration resting on an unchecked bypass, an owed hole or a native runtime assumption.','kernel-core core-checker','crates/kernel-core/src/env.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('bicontextual-core','checking','The bicontextual core',NULL,'partial','notable',NULL,'One judgement with a supplied environment flowing in and a demanded support flowing out, polarity routing each binding: every core node carries its exact support as a compact word code, which the check memo keys its judgements by (#673, #705, #732, #750, #785, #866).','core-term core-sequent core-incremental kernel-core','crates/core-term/src/support/tests.rs crates/core-term/src/arena/tests.rs crates/core-sequent/src/il/tests.rs crates/core-incremental/tests/supports.rs crates/core-incremental/src/content/tests.rs crates/core-incremental/src/codec/tests.rs crates/kernel-core/tests/acceptance.rs','crate-tests','#340','#673 #785 #866 #1032');
INSERT INTO feature VALUES('bicontextual-kernel-key','kernel','The kernel memo key on carried supports','bicontextual-core','partial','notable',NULL,'Every kernel node carries the free de Bruijn indices it mentions from its mint, and the kernel''s check memo keys a goal by the binders that support names, so one goal under two contexts that differ only where it does not read is one entry; the judgement returning the support it read is owed (#3123).','kernel-term kernel-core','corpus/ledger/features/bicontextual-kernel-key.gandr crates/kernel-term/src/support.rs crates/kernel-core/src/support.rs','corpus/ledger/features/bicontextual-kernel-key.gandr','#3123','#753 #2519');
INSERT INTO feature VALUES('bidirectional-checking','checking','Bidirectional checking',NULL,'implemented','notable',NULL,'Four directed faces check or synthesise values and computations, formation itself a judgement; a return synthesises its value''s pure returner.','core-checker','corpus/fragment/non-synthesisable-head.gandr corpus/model/control/held-read.gandr corpus/model/control/statement-block.gandr','corpus/model/control/held-read.gandr',NULL,'b87a65d #1392 #1397');
INSERT INTO feature VALUES('binary-naturals','types','Binary natural numbers','nominal-data','implemented','ordinary',NULL,'The prelude declares the naturals in binary: `Nat`, `Zero` or `Positive` over a `Pos`, whose `One`, `Bit0` and `Bit1` put the lowest digit outermost, as Isabelle/HOL''s `num` does. A numeral annotated `(n : Nat)` is the constructor term its binary digits spell, `(5 : Nat)` being `Positive(Bit1(Bit0(One)))`, so an order or a sum over the naturals is decided by conversion and replayed by the kernel, where a native `Integer` stays an opaque constant; the printer spells the term back as its numeral. A name a source writes shadows the prelude''s: its own `Nat` keeps its numerals integers, its own type `One` reads as itself, and a code''s leaf naming `Nat` reads the source''s.','surface-lowering surface-pretty','corpus/ledger/features/binary-naturals.gandr corpus/model/effects/grade-algebra.gandr corpus/model/metaprograms/derive-eq-over-codes.gandr corpus/pathological/identity/univalence.gandr crates/surface-lowering/src/lower/natural/tests.rs::a_numeral_at_nat_is_its_binary_constructor_term_3287 crates/surface-lowering/src/lower/natural/tests.rs::a_numeral_at_a_source_s_own_nat_stays_an_integer_3287 crates/surface-lowering/src/lower/generic/tests.rs::a_leaf_reads_a_source_s_family_before_the_prelude_s_3287 crates/surface-lowering/tests/namespace.rs::a_source_s_type_shadows_the_prelude_s_constructor_3287 crates/surface-pretty/tests/goldens.rs::an_ascribed_binary_natural_spells_as_its_numeral_3287','corpus/ledger/features/binary-naturals.gandr',NULL,'#3452');
INSERT INTO feature VALUES('binders-in-scope','editor','Binders in scope at an offset','language-server','implemented','ordinary',NULL,'The lowering records each node''s reading frame as it resolves and keeps the frames of a declaration it refused, so the binders in scope at any offset are read off the narrowest reading holding it.','surface-lowering surface-dispatcher','crates/surface-lowering/tests/scopes.rs',NULL,NULL,'#834');
INSERT INTO feature VALUES('bootstrap','runtime','The runtime bootstrapped in gandr',NULL,'planned','notable',NULL,'Each workspace crate rewritten in gandr in the order a census ranks: its twin written to the crate''s specifications, held to the Rust crate as oracle across a stated boundary, and switched in for it once it proves.',NULL,NULL,NULL,'#2895',NULL);
INSERT INTO feature VALUES('boundary-classification','storage','Alias and boundary classification','value-plane','implemented','notable',NULL,'A value''s constructors are classified as aliases or boundaries on the chunk DAG: the manifest carries the classification into the identity, a boundary exit is a cut candidate, an alias recursing through aliases alone and an alias seam at a chunk boundary are refused by name.','storage-values','crates/storage-values/tests/classification.rs crates/storage-values/tests/manifest.rs',NULL,'#317','#1049');
