INSERT INTO feature VALUES('bridge-types','identity','Bridge types by the identity recursion',NULL,'partial','unique','dependent provers','The bridge relation by the identity recursion in bridge mode, interval-free: Unit, Base, sums, products, a function code as the family over argument bridges, the value universe at any level as a relation, the List lifting; persisted as the Bridge node (tag 0x36) and replayed; a sealed atom supplies its element relation and reflexivity as fields of its declaration, read at its bridges, and an atom without them is refused by name; transport, coherence and J not granted; the surface former and the model laws owed.','kernel-core kernel-term','crates/kernel-core/tests/bridge_readmission.rs crates/kernel-core/src/identity_recursion.rs crates/kernel-core/src/element_identity/bridge_tests.rs crates/kernel-core/src/element_identity/bridge_tests.rs::the_lawful_atom','crate-tests','#642','#725 #936 #1120');
INSERT INTO feature VALUES('buffer-tokens','sessions','Buffer tokens','session-types','partial','notable',NULL,'A linear buffer token, placed live by a receive or by `Ring.alloc` and returned exactly once, by every arm of a case or by none; reading the area at a buffer is the next rung.','core-checker','corpus/model/completion/buffer-returned.gandr','corpus/ledger/features/buffer-tokens.gandr','#1263 #1184','#1330 #1841 #2722');
INSERT INTO feature VALUES('build-stage','metaprograms','A package''s build stage','project-manifest','planned','notable',NULL,'A package''s `gandr.toml` is written by its own build stage, an operation of its `Package` model the checker runs at the model''s fields and the tree''s modules, memoized by its inputs'' content; today the default stage is spelled as a gandr function whose runs are the bodies the tree commits, and the checker''s fixed rule writes the file.',NULL,'corpus/model/package/build-stage.gandr',NULL,'#2998',NULL);
