INSERT INTO feature VALUES('candidate-fills','editor','Checked candidate fills','engine-hub','implemented','uncommon','mainstream editors','Candidate edits are judged without being applied and ranked, and a model''s fill that checks is shown as ghost text, a code lens and a code action.','surface-lsp surface-mcp','crates/surface-lsp/src/proposal.rs crates/surface-lsp/src/server.rs crates/surface-mcp/src/tools.rs',NULL,'#124 #125','#162');
INSERT INTO feature VALUES('capabilities','effects','Capabilities with authority, grade, region and footprint',NULL,'implemented','uncommon','mainstream languages','A capability names the effects it authorises and the scope it lives in, and forging, amplifying, dropping or escaping one is refused by name. An operation the host answers stands beside an open end, and one a scope answers captures what the scope opened. The two halves of a fork share a capability''s interface only to read through it.','core-checker core-sequent','corpus/model/control/capability-region.gandr corpus/model/control/capability-attenuate.gandr corpus/pathological/control/capability-forge.gandr corpus/model/tasks/authority.gandr corpus/model/cancellation/resumed.gandr','corpus/model/control/capability-region.gandr',NULL,'#281 #1351 #1376 #2916');
INSERT INTO feature VALUES('cell-occurrence-count','quantities','Each hole''s occurrence count','cell-rewriting','implemented','notable',NULL,'`gandr cells` reports every cell a source''s declarations elaborate to, each hole with how many times the cell''s right side writes it, its Lipschitz constant under the step: zero for a dropped hole, more than one for a copied one; a cell''s growth carries its largest count. The count is reported, never refused: a copy on the left side is refused at admission.','theory-cell-complexes surface-dispatcher surface-driver','corpus/model/desc/occurrence-count.gandr corpus/pathological/desc/occurrence-count.gandr crates/surface-dispatcher/src/cells.rs crates/surface-driver/tests/cli.rs','corpus/model/desc/occurrence-count.gandr','#2788','#2853');
