INSERT INTO feature VALUES('change-coalescing','editor','A burst of changes judged once','language-server','implemented','ordinary',NULL,'Every `didChange` already in the inbox for a document is applied in order before the judgement, which runs once at the last version; a request a drained change overtakes is answered `ContentModified`, and a judgement a newer change overtakes is retired at its next poll, before each declaration it checks.','surface-lsp surface-session','crates/surface-lsp/src/server.rs crates/surface-session/tests/session.rs',NULL,'#1547','#1562 #1636 #1732');
INSERT INTO feature VALUES('check-memo','kernel','Check memoization',NULL,'implemented','notable',NULL,'A checker skips a question already answered in the run, on both machines by default, keyed by the content table''s name for the goal: exactly the binders it reads, each with its type, as goal, cover and pair records built once and shared — the hereditarily finite set reading of a support (#866: a judgement served wherever its dependency set recurs in the run; the fixture −3.4 % instructions, recalls 5 629 → 5 994); the cross-session name is #864. Placement reads dense per-family columns, and interning, the memo, the reach caches and the rewrite memo probe one open-addressing hash index (#2513). A key reads a plain definition''s reference by its content rather than its admission position (`content-addressed-references`).','kernel-check-memo kernel-core','crates/kernel-check-memo/tests/differential.rs crates/kernel-check-memo/src/table.rs crates/kernel-core/tests/acceptance.rs crates/kernel-core/src/encoding.rs crates/kernel-core/src/support.rs',NULL,'#864','b87a65d #866');
