INSERT INTO feature VALUES('claim-order','workflow','The claim order a seat walks between units',NULL,'implemented','ordinary',NULL,'`claim:next` claims an unowned defect in the area, then a `kind:refactor` in the area, then performance, gaps cheapest first and the lane''s planned units, priority first within each bucket and a blocked issue passed over. The pick is by order alone, sectioned or not: each section it lacks is printed as due, the claiming seat writes them first and pages for the coordinator''s `shape:signed`, and `pr:open` refuses a landing on an issue unsectioned or unsigned.',NULL,'.config/claims/next.json .config/claims/signed.json',NULL,NULL,'#2533 #2902 #3031 #3140');
INSERT INTO feature VALUES('closure-axes','sessions','A closure crosses by its image','open-judgement','implemented','uncommon','mainstream languages','A thunk has no crossing of its own: one a migration returns crosses when every hypothesis it captures and every declaration homed at its world that it names is mobile and open, the image recorded where the thunk is formed. A capture that stays is refused `Immobile.Capture`, or `NotOpen.Capture` under a handle, and a homed declaration `Immobile.Homed` or `NotOpen.Homed`. The image''s three axes are the capture rules: the region by `KeptEscaped`, the grade and access mode by `HeldCaptured`, the world by `Elsewhere`. A thunk reached through a variable or a call carries no image and stays. A thunk it lets cross runs at the caller, forced or applied there, as it runs in place (world-migration).','core-checker core-incremental surface-corpus surface-diagnostics','corpus/model/worlds/closure-axes.gandr corpus/pathological/worlds/closure-axes.gandr corpus/model/worlds/open.gandr corpus/pathological/worlds/open.gandr corpus/pathological/worlds/immobile-crossing.gandr','corpus/model/worlds/closure-axes.gandr',NULL,'#3200 #3256 #3282');
INSERT INTO feature VALUES('closure-named-paths','modules','The paths a closure names','sibling-imports','implemented','ordinary',NULL,'A laid-out closure lists every path an import of any of its sources names, sorted, resolved or not, and a file is named the same way whether or not its path is canonical, so a dependant of a change on disk is found by a binary search.','surface-dispatcher','crates/surface-dispatcher/src/component.rs','crate-tests',NULL,'#848');
INSERT INTO feature VALUES('codata','types','Codata and copatterns',NULL,'implemented','notable',NULL,'Codata declared by its observations as a negative greatest-fixpoint former, read by those observations in the kernel and the core checker, its answers in the incremental log; the surface declaration, copatterns and the corpus owed.','kernel-core kernel-term core-term core-nbe core-checker core-incremental surface-lowering','crates/kernel-core/tests/codata.rs crates/core-checker/tests/codata.rs crates/core-incremental/tests/native_formers.rs corpus/model/codata/streams.gandr corpus/pathological/codata/streams.gandr','corpus/model/codata/streams.gandr','#644','#982 #994 #1025 #1117 #2199');
