INSERT INTO feature VALUES('conditionals','effects','Conditionals',NULL,'implemented','ordinary',NULL,'`if c { t } else { e }` lowers to the case of its condition over the two booleans, the condition bound as a computation; `-> T` states the answer each branch is read at and the case is ascribed, so the conditional synthesises it where nothing states its type, `else if` nests a second test in the false branch, and an exit in a branch leaves the function.','surface-lowering surface-pretty','corpus/model/control/conditional.gandr corpus/model/control/eliminator-answers.gandr corpus/pathological/control/eliminator-answer-type-mismatch.gandr corpus/pathological/control/eliminator-answer-type-tail-rung-only.gandr corpus/ledger/syntax/if-expression.gandr','corpus/model/control/conditional.gandr',NULL,'#2293');
INSERT INTO feature VALUES('confluence-certificate','rules','Confluence as a certificate',NULL,'partial','notable',NULL,'The overlap enumeration as a convex pre-critical-pair criterion and the coincidence verdict as a replayable certificate; the diagram side enumerates the connected gluings of two left-hand sides, and on the corpus the term critical pairs are exactly the gluings at a redex (a command''s cut, any node of a term). A certificate is a path from a critical pair''s peak to its join in the presented type: two certificates of one boundary are one path by `here` where the rules relate their points, two that no rule relates stay apart, and the certificate types of two converting boundaries are one along `ua`.','theory-circuit-algebras','crates/surface-dispatcher/tests/coincide.rs corpus/model/desc/rules-overlap-joinable.gandr corpus/model/identity/certificate-transport.gandr corpus/pathological/identity/certificate-transport.gandr','corpus/ledger/features/confluence-certificate.gandr','#314 #525','#1495 #1849 #2722');
INSERT INTO feature VALUES('cong-fusion','conversion','Congruence fusion','normalization-by-evaluation','implemented','notable',NULL,'A chain of congruences whose composite reads as the identity converts to the path beneath it, in the engine and the kernel alike.','core-nbe kernel-core','corpus/model/identity/circle.gandr','corpus/model/identity/circle.gandr','#370','#375');
INSERT INTO feature VALUES('constructor-namespacing','modules','Constructor names namespaced by family',NULL,'partial','ordinary',NULL,'A constructor is named through its family, `Family.Constructor`, in a pattern and in a value, and bare where its name resolves to it; the printer writes a constructor of `Theory` qualified where the source''s own constructor takes its bare name. Two data families sharing a constructor name in one source, and a bare name resolved by uniqueness among imports, are owed.','surface-grammar surface-lowering surface-diagnostics','corpus/model/desc/theory-constructor-qualified.gandr corpus/pathological/desc/theory-constructor-qualified.gandr','corpus/ledger/features/constructor-namespacing.gandr','#354 #2713','#2450 #2722');
INSERT INTO feature VALUES('content-addressed-references','kernel','Content-addressed kernel references','check-memo','partial','notable',NULL,'A memo key names a reference to a plain definition — checked, alone, outside every atom''s minting admission, monomorphic and carrying no laws, relations, rules, stages, presentation or provenance — by its declared type, its body and its rank among the earlier definitions of that content, so two environments that admitted the same declarations in another order build one key; every other constant is still named by its position (#3001).','kernel-core','crates/kernel-core/src/encoding.rs',NULL,'#3001','#2796');
INSERT INTO feature VALUES('content-checkpoints','incremental','Content-addressed checkpoints','incremental-checking','implemented','notable',NULL,'Checked answers persist as checkpoints addressed by content and are restored only when validated; a session over a store that keeps nothing, as each language-server document''s is, neither encodes its checkpoints nor commits its kernel checkpoint, and resumes alike.','core-incremental surface-session','crates/core-incremental/tests/incremental.rs crates/surface-session/tests/checkpoint.rs',NULL,NULL,'b87a65d #1297');
