INSERT INTO feature VALUES('corpus-by-subject','tooling','The corpus organised by subject, one base per subject','corpus-expectations','implemented','uncommon','mainstream languages','One subject per directory with one base source the others import; every lemma written once; one claim per file in the order the argument runs; the instruments re-pinned per subject; a gate refuses a subject declaring a name twice; the fold landed in eleven PRs, net free on the model root (−1.3 M instructions).','surface-corpus surface-dispatcher','corpus/model/',NULL,'#436','#623');
INSERT INTO feature VALUES('corpus-comments','corpus','Every corpus item and block member commented, in one shape','corpus-expectations','implemented','ordinary',NULL,'A gate refuses a corpus item without a comment before its attribute block, and a member of a theory, module, data or codata block without a comment before it; a source''s head is four paragraphs (what, why, how, references) and an item comment at most two short sentences, each finding a ledger line of its kind.','surface-corpus','crates/surface-corpus/tests/comments.rs',NULL,'#355','#381 #2957 #2981 #3021');
INSERT INTO feature VALUES('corpus-expectations','corpus','Corpus expectations',NULL,'implemented','notable',NULL,'A source states each declaration''s expected verdict as `checks`, `owes`, `refuses`, `runs`, `normalizes` or `decomposes`, and the runner settles every one with the obligations it owes; an attribute before a functor application or a module states the expectation of each name its application or header binds and refuses, and one before a data family''s member that of the declaration the member is held apart as.','surface-corpus','corpus/fragment/addressable-obligation.gandr corpus/model/desc/rules-overlap-joinable.gandr corpus/pathological/modules/functor-unexported.gandr corpus/pathological/modules/functor-mistyped.gandr corpus/pathological/desc/member-attribute.gandr corpus/pathological/desc/member-attribute-stray.gandr','corpus/model/desc/rules-overlap-joinable.gandr',NULL,'0dd5b3d #1989 #2014 #2142');
