INSERT INTO feature VALUES('cut-schedules','machine','Concurrent schedules of a cut','sequent-machine','partial','notable',NULL,'Two cuts run by hand as two runs on two threads, each holding its own heap, answer as the sequential schedule does: the two halves of a tree sum at depth 18 finish 2.41 times faster on the executor and 2.23 times natively, on a 16-core Ryzen 9 9950X3D at load 39 on 32 hardware threads. A writer runs closed over a store''s values, apart from its reader''s heap: a suspended sum moved out of its run with the tree it captured has the tree laid out on another run''s heap, sharing kept, and answers on another thread as forcing it in place does. A pool running each writer on a thread of its own, its read''s reply carrying the answer back (#2953), and the rule that spawns a writer at each independent cut with an await before the binder''s first read (#2954) are owed.','surface-dispatcher runtime-emitter','corpus/ledger/features/cut-schedules.gandr crates/surface-dispatcher/src/evaluate.rs crates/runtime-emitter/tests/closed.rs','corpus/ledger/features/cut-schedules.gandr','#2953 #2954','#2951 #3199');
INSERT INTO feature VALUES('data-parameters','types','Parameterised data families','nominal-data','implemented','ordinary',NULL,'A data family takes parameters; a constructor written as a family argument is typed by the family''s place, and one written as a call''s argument by the parameter it is passed to, the parameters before it that type names replaced by the arguments written for them, a refused declaration''s parameters typing none; one ending a body whose result is a definition''s application is typed through the definition''s body; at a place the family declares a universe, a name is the type''s, even where a constructor shares it; and a family applied where a value is read, passed for a type parameter or defined as a `Type`, is the family''s type over its arguments.','core-checker kernel-core surface-lowering','corpus/model/data/family-argument.gandr corpus/model/data/data-maybe.gandr corpus/model/data/argument-classifier.gandr corpus/pathological/data/argument-classifier.gandr corpus/model/data/answered-definition.gandr corpus/pathological/data/answered-definition.gandr corpus/pathological/data/refused-callee.gandr corpus/model/data/applied-type-argument.gandr','corpus/model/data/family-argument.gandr',NULL,'b87a65d #1876 #2112 #2126 #2512');
