INSERT INTO feature VALUES('dependent-transport','identity','Transport in path-dependent motives','transport','partial','notable',NULL,'A motive may depend on the identification itself, and path induction is derived in the singleton. Along a closed path that is no reflexivity, native evidence at the unit type or at a sealed atom, the transport computes in a motive reading neither entry; into an identity at a carrier whose identities are the unit type, the unit type itself, an identity of such a carrier, or a lawful atom whose relation returns the code of such a type outright, it returns the unit along any path.','core-nbe core-checker kernel-core','corpus/model/identity/transport-dependent.gandr corpus/model/identity/transport-dependent-element.gandr corpus/model/identity/atom-identity.gandr','corpus/ledger/features/dependent-transport.gandr','#312 #2053','#266 #1909 #1957 #1974 #2068 #2722');
INSERT INTO feature VALUES('deployment-file','runtime','A deployment''s site and manifold, read as the flags they desugar to','migrate-wire','partial','notable',NULL,'A deployment is two gandr files of `std.manifold`. A site, `module Site : Model(Site)`, names the key its place proves and the sockets a dialer reaches it at, and `gandr host --site` binds them under the secret `GANDR_NET_SECRET` holds, refusing a secret that proves another key, and prints its peer spelling on standard error once bound; a host given no world bindings hosts every world its entry may migrate to. A manifold, `module Manifold : Model(Manifold)` beside `pub def placements : List(Placement)`, names the program it deploys by its path and places each world at a site, `At` for one process and `Instances` refused at any other count, and `gandr run --manifold` and `gandr host --manifold` take its world bindings, refusing a program it does not deploy. A flag given beside the file it desugars from is refused, naming both; the program named by address is owed (#3381).','surface-dispatcher surface-driver runtime-net','corpus/ledger/features/deployment-file.gandr corpus/model/worlds/two-processes.site.gandr corpus/model/worlds/two-processes.manifold.gandr crates/surface-dispatcher/src/manifold/tests.rs crates/surface-driver/tests/net.rs','corpus/ledger/features/deployment-file.gandr','#3381','#3458');
INSERT INTO feature VALUES('deprecation','attributes','Deprecated declarations','attributes','implemented','ordinary',NULL,'`@[ deprecated ]`, or `@[ deprecated(#{ since = "…", note = "…" }) ]` with either field left out, marks a declaration that still checks; each use of it is a `deprecated` warning naming the version and the note, struck through in the editor, the declaration''s symbol tagged and its hover stating both.','surface-lowering surface-diagnostics surface-dispatcher surface-lsp','corpus/model/attributes/doc-and-deprecated.gandr corpus/pathological/attributes/ill-typed-deprecation.gandr','corpus/model/attributes/doc-and-deprecated.gandr',NULL,'#1814');
INSERT INTO feature VALUES('derivation-identity','rewriting','Derivation identity up to reordering',NULL,'implemented','notable',NULL,'Two derivations firing the same cells in independent orders are one, decided by shift equivalence with a causal order and a certified normal form.','theory-deep-inference','crates/theory-deep-inference/tests/shift.rs crates/theory-deep-inference/tests/causal_web.rs',NULL,NULL,'86a6a2e');
INSERT INTO feature VALUES('derive-over-codes','metaprograms','Derivations over levitated codes',NULL,'partial','notable',NULL,'A definition written `Eq.generic(T)` reads the data declaration `T`''s levitated code — its constructor table, each constructor''s product spine, a `var` as the recursion and each leaf at the type it names — and derives closed core the checker judges as written and the kernel replays, so the derivation is never trusted. A code with a parameter and a `rec` pair read as two codes of one sort are refused (#2345); the derivation is not yet a gandr function over a code value (#2343).','surface-lowering core-term','corpus/model/metaprograms/derive-eq-over-codes.gandr corpus/pathological/metaprograms/derive-eq-over-codes.gandr','corpus/ledger/features/derive-over-codes.gandr','#2345 #2343','#2779');
INSERT INTO feature VALUES('derived-rules','identity','Derived rules at a model (derive r : l <=> r in T)','univalence-theorem','partial','unique','dependent provers','`derive r : l <=> r in T` states an equation a theory''s completed rules prove, both sides rewritten to one normal form, and is proved for every model: a path over the model''s fields, each step the law or the lemma it fires carried up its context as `cong` is, each rule completion derived on the way proved first from its certificate''s two paths. A model reads it as the theory''s member `T.r`; sides the completion keeps apart are refused by name. A theory with an indexed sort or a nested model is not read yet.','surface-lowering surface-grammar','corpus/model/identity/derived-rule.gandr corpus/pathological/identity/derived-rule.gandr crates/surface-lowering/tests/modules/models.rs','corpus/ledger/features/derived-rules.gandr','#1301','#1905 #2722');
INSERT INTO feature VALUES('descent-any-parameter','recursion','Descent on any parameter','structural-recursion','implemented','ordinary',NULL,'The lowering reads the staged position off the body: the parameter the claims'' cases take apart is the fixpoint''s first binder with StructuralDescent, the parameters before it outside and uniform, the ones after it free under the staged lambda; claims on two parameters refused DescentOnSeveralParameters; an unapplied f[<] is the self binder; a parameter before the recursed-on one may vary between calls. A claim under a match on the staged parameter descends on it whatever matches on other parameters stand between, and the staged parameter is the innermost matched one the first call does not pass back unchanged, so a walk consumes a second list alongside the one it descends on. A constructor written as a descent''s argument takes its type from the parameter it fills, as an ordinary call''s does, a uniform parameter that type names standing for itself.','surface-lowering','corpus/model/data/descent.gandr corpus/pathological/data/descent.gandr corpus/model/identity/int-accumulated.gandr crates/surface-lowering/src/lower/native/tests.rs::a_descent_call_s_constructor_argument_takes_its_parameter_s_type_2127 crates/surface-lowering/src/lower/native/tests.rs::a_claim_under_a_match_on_another_parameter_descends_on_the_staged_one_2135','corpus/model/data/descent.gandr','#392 #518','#629 #999 #2151 #2160');
INSERT INTO feature VALUES('diagnostic-verbosity','diagnostics','Verbosity levels','rich-reports','implemented','ordinary',NULL,'A report renders at a chosen verbosity, in the terminal and the editor alike.','surface-diagnostics surface-lsp','crates/surface-diagnostics/src/verbosity.rs',NULL,'#116','#167');
INSERT INTO feature VALUES('diagnostics-ledger','workflow','Diagnostics exemplars','syntax-ledger','partial','ordinary',NULL,'One focused source per refusal name no form qualifies, and per reserved or unadmitted boundary, under `corpus/ledger/diagnostics/`, each refused with its subject and settled by `check:exemplars`; a name without one is a row of the gate''s owed table, with the reason no source reaches it or the issue writing it. A recovery sweep, `gandr ledger recovery`, writes each literal tile of each syntax exemplar as its near miss and deletes it, and reports each mutant whose first error marks other bytes than the mutation; the nightly run files each cause, a first error and mutation kind, on one issue.','surface-dispatcher surface-corpus','corpus/ledger/diagnostics',NULL,'#1782 #1788 #1789','#1793 #1798');
