INSERT INTO feature VALUES('directed-paths','directed','Directed paths (Flow)',NULL,'partial','uncommon','mainstream languages','`Flow(A, a, b)` is a directed identification with `stay`, `then` and covariant transport `ride`, certified on readmission; `forward(f)` decides a closed translator at its finitely many patterns, a list code read as the empty list and one cell over a rigid tail, whose image may also bind the translator''s own image of the tail, replayed as the translator at the tail bound before the cell''s return; a data code with no index and no presentation, every field a closed type of the vocabulary, is read constructor by constructor, each applied to its fields'' patterns. A ⇝ B (A ~~> B) abbreviates Flow(Type, A, B) at the type level (#571).','core-checker kernel-core kernel-term','corpus/model/identity/flow-then.gandr corpus/pathological/identity/flow-forward-unsupported.gandr corpus/model/identity/flow-universe.gandr corpus/pathological/identity/flow-universe.gandr corpus/model/identity/flow-list-field.gandr corpus/model/identity/flow-list-each.gandr corpus/model/identity/flow-large.gandr corpus/model/identity/flow-data.gandr corpus/pathological/identity/flow-data.gandr','corpus/ledger/features/directed-paths.gandr','#1835','#296 #1769 #1771 #1838 #1842 #1927 #2722');
INSERT INTO feature VALUES('directed-univalence','directed','Directed univalence',NULL,'planned','unique','dependent provers','A flow in the universe from a directed map of presentations, the directed twin of `ua`.',NULL,NULL,NULL,'#312',NULL);
INSERT INTO feature VALUES('divergence-row','effects','Divergence as a row entry','effect-rows','implemented','uncommon','mainstream languages','A partial fixpoint checks only where every returner its type ends in holds `Div`, the host interface with no operation, which no handler or scope eliminates, so the empty row is the row of a computation that returns; a fixpoint that never names itself and a ruled operation''s need no entry. In a reflexivity''s endpoints, an unread call of a variable whose type ends in the empty row alone is the computation that follows it; the kernel refuses a partial fixpoint at a returner other than a ruled operation''s and replays the drop.','core-term core-checker core-nbe kernel-core kernel-term kernel-conversion-trace','corpus/model/control/divergence.gandr corpus/pathological/control/divergence.gandr','corpus/model/control/divergence.gandr','#1481','#1526 #1542 #2722');
INSERT INTO feature VALUES('documentation-comments','attributes','Documentation comments','attributes','implemented','ordinary',NULL,'`///` runs and `doc` attributes read as one documentation text with its links resolved, shown on hover; a module''s documentation, nested modules included, is filed under the module form and hovers on its name; a source''s `//!` run documents the file and hovers on its import.','surface-lowering surface-parser','corpus/model/attributes/doc-comments.gandr corpus/model/include/monoid.gandr','corpus/model/attributes/doc-comments.gandr',NULL,'#150 #1379 #1445');
INSERT INTO feature VALUES('domhringr-effect-space','effects','domhringr''s effect space as theories','effect-rows','implemented','notable',NULL,'What a domhringr stage performs besides its session''s moves, as nine theories: Store, Journal, Judge, Witness, Clock, Random, Trace, Fail and Cancel, each with its operations and first-order laws and stating what it commutes with. The laws that sequence one operation after another, a put''s and a lookup''s idempotence and each commutation past an operation answering a value, are written over continuations, the value an operation answers bound by `bind x . …` and named only at a port of its sort.',NULL,'corpus/model/effects/domhringr.gandr corpus/pathological/effects/domhringr.gandr','corpus/model/effects/domhringr.gandr',NULL,'#2274 #2321');
INSERT INTO feature VALUES('driver','tooling','The gandr driver',NULL,'implemented','ordinary',NULL,'One `gandr` binary runs `check`, `test`, `run`, `stage`, `fmt`, `lsp`, `serve`, `mcp`, `view`, `repl` and `tui`, a run''s verdict its exit code.','surface-driver surface-dispatcher','crates/surface-driver/tests/cli.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('dynamic-topological-orders','algorithms','Dynamic topological orders',NULL,'implemented','ordinary',NULL,'Topological orders and feasible valuations kept under edge insertion.','theory-dynamic-graphs','crates/theory-dynamic-graphs/tests/standing.rs',NULL,NULL,'#78');
