INSERT INTO feature VALUES('editor-session-trace','editor','Replayable editor session traces','language-server','planned','notable',NULL,'A server trace replayed against a fresh server so an editor''s report becomes a test, beside an end-to-end VS Code smoke.',NULL,NULL,NULL,'#394',NULL);
INSERT INTO feature VALUES('effect-handlers','effects','Effect handlers','effect-rows','implemented','uncommon','mainstream languages','A handler interprets the operations of a computation, each clause receiving the continuation; a handle is a reset whose clauses receive the captured stack, and a return leaving a handler prints as written with its capability''s region. A clause whose continuation captured an obligation ends it exactly once, by resuming it or by `abandon(k)`, and an abandonment is refused inside an unwind. A deep handler crosses to the kernel as the fold of its effect''s free model, one case per operation, and the kernel replays it.','core-checker core-sequent surface-pretty','corpus/model/control/handler-exits.gandr corpus/model/control/capability-region.gandr corpus/pathological/control/capability-escape.gandr corpus/model/cancellation/abandoned.gandr corpus/pathological/cancellation/dropped.gandr corpus/pathological/cancellation/shielded.gandr corpus/model/drop/in-flight.gandr corpus/model/effects/exit.gandr corpus/model/effects/state-handler.gandr','corpus/model/control/handler-exits.gandr',NULL,'#98 #1299 #1376 #1415 #2745 #2772');
INSERT INTO feature VALUES('effect-rows','effects','Effect rows','row-kind','implemented','uncommon','mainstream languages','A returner''s type carries the row of named interfaces it may perform, with typed payloads and replies, written `-F [I, …] A`: each interface named once whole, each instance of one by its label, `a : I`, and in no order of its own, so sequencing joins two rows, handling removes an interface, and a row is read where one holding more is asked. At a definition''s result the row is written before the value type, `-> [I, …] A`, the row of the returner the lowering inserts there; a row before a type anywhere else is refused. An entry names a host interface or a theory with its value sorts fixed, `-F [State with sort S = Integer] A`.','core-term core-checker core-incremental surface-grammar surface-lowering','corpus/model/control/handler-exits.gandr corpus/model/effects/hello.gandr corpus/pathological/effects/hello-unprovided.gandr corpus/model/control/effect-rows.gandr corpus/pathological/control/effect-rows.gandr corpus/ledger/syntax/f-type.result.gandr corpus/ledger/diagnostics/OutOfFragment.NotAtResult.gandr','corpus/model/control/handler-exits.gandr',NULL,'#98 #2297 #2305 #2329 #2336 #2381 #2915');
INSERT INTO feature VALUES('effect-theories','effects','Effects as theories with laws','effect-rows','implemented','notable',NULL,'An effect is a theory of its operations, each taking what runs after it, and its laws are rules the path order orients: State''s put-get descends by branch selection, its continuation instantiated at a value of a sort no operation returns, put-put by its subterm, and two laws overlapping through a pattern join in the second-order reading. A capability scope takes a theory as its interface, `handle st : State with sort S = Integer`, the manifest fixing each value sort and the carrier left to what the scope answers, and a member it cannot read as an operation is refused by name. The scope is checked as a model of the theory: each law, read through its clauses, converts with its metavariables rigid, and a handler failing one is refused at its scope naming the law. A scope may name a module that is a model of its theory in place of the clauses, `} with Passing`: each operation''s clause hands it to the module''s component of its name, the scope answers the module''s carrier, and it owes no law, which the module''s ascription states. A scope writing no `with` is answered by the one model of its theory in scope at the manifest''s sorts, as a call''s omitted model is, and answers that model''s carrier as naming it does; it is refused as unanswered or ambiguous naming the theory and `} with M`. Before it runs, a scope''s subject normalises by the theory''s laws as the path order orients them: a run of requests on the scope''s capability that instantiates a law''s left side is rewritten in place, each request its right side drops replaced by returning the value its reply stands for, its payload still checked and run once, so two reads under get-get normalise to one and the kernel replays the normal form. A returner''s row names the theory at the sorts it fixes, `-F [st : State with sort S = Integer] A`: the label''s instance is a capability over the theory''s operations at those sorts, and a scope over the theory at the same sorts discharges a call that needs it. A fixed type may name a parameter of the definition, `with sort S = a`, and each scope and exercise reads it where it stands. A fixed type naming an implicit a call omits is read at the implicit''s solution, and a scope at the sort may be what solves it.','theory-levitation kernel-term core-term core-checker surface-grammar surface-lowering','corpus/model/effects/state.gandr corpus/pathological/effects/state.gandr corpus/model/effects/state-handler.gandr corpus/pathological/effects/state-handler.gandr corpus/model/effects/state-laws.gandr corpus/pathological/effects/state-laws.gandr corpus/ledger/diagnostics/UninterfacedMember.gandr corpus/ledger/diagnostics/HandlerUnlawful.gandr crates/core-term/src/handler/subject/tests.rs crates/surface-lowering/src/lower/capability/tests.rs','corpus/ledger/features/effect-theories.gandr',NULL,'#2324 #2367 #2377 #2396 #2445 #2474 #2722 #2836 #2868 #2915 #2989 #3129');
INSERT INTO feature VALUES('effects-as-data','effects','Effects as data, replayed by the kernel','effect-rows','partial','notable',NULL,'A program over a row of operations is written as a tree, the free model of its operations, its row a sum of operation types and each handler a fold, so every declaration is pure and the kernel replays it whole: an operation outside a program''s row is refused by the checker and, forged past it, by the kernel at that program. A native deep handler crosses by this translation, its effect''s free model, one constructor per operation, admitted ahead of it and its clauses the fold, whether a capability scope writes them, names a model or leaves them to the one model in scope (`exit.gandr` and `state-handler.gandr`, written by hand in `tree-exit.gandr` and `tree-state.gandr`), so a resumption at another type than the reply is the kernel''s refusal; the forms past it cross next (#2742).','core-checker kernel-core','corpus/model/effects/tree.gandr corpus/model/effects/tree-state.gandr corpus/model/effects/tree-rows.gandr corpus/pathological/effects/tree-rows.gandr corpus/model/effects/exit.gandr corpus/model/effects/tree-exit.gandr corpus/model/effects/state-handler.gandr crates/surface-corpus/src/kernel_export.rs','corpus/ledger/features/effects-as-data.gandr','#2742','#2548 #2722 #2745 #2772 #2836');
INSERT INTO feature VALUES('elaboration-suspension','checking','Elaboration suspends on owed holes',NULL,'implemented','uncommon','dependent provers','A judgement blocked on an owed hole suspends with its blockers and resumes on a validated fill; resumptions commute, a checked success is never re-judged, a refused subterm refuses its declaration, the kernel readmits every output — the seven route guarantees as witnesses in both modes; Typing::Suspended persisted (codec tag 5).','core-checker','corpus/model/holes','corpus/model/holes/suspended-decode.gandr','#703','#713');
INSERT INTO feature VALUES('empty-type','types','The empty type',NULL,'implemented','ordinary',NULL,'`Empty` is user data with no constructor, so a case of no arms over it answers any type and negation is `A -> Empty`; a lambda''s binder matched with no arm is typed by the arrow its position answers, a signature''s or the parameter of the call it is passed to.','core-checker kernel-core surface-lowering','corpus/model/data/empty.gandr','corpus/model/data/empty.gandr',NULL,'#384 #1973 #1977');
INSERT INTO feature VALUES('enforced-test-lanes','workflow','Plain and enforcing test lanes','executable-specifications','implemented','notable',NULL,'Every pull request runs each test plainly and with specifications enforced, each held to 30 s.','workflow-test-timing','crates/workflow-test-timing/tests/cli.rs',NULL,NULL,'#416');
INSERT INTO feature VALUES('engine-hub','editor','One engine hub per workspace','language-server','implemented','notable',NULL,'Every editor and tool of a workspace shares one hub that holds each client''s copy of a document and judges it incrementally; sibling readings, import-closure lowerings and readmissions are keyed by content and shared across connections, and a judged closure''s arena is shared with each revision laid after it, which copies only its own nodes.','surface-lsp','crates/surface-lsp/src/hub.rs crates/surface-dispatcher/src/component.rs',NULL,'#122','#164 #801 #1060 #1644');
INSERT INTO feature VALUES('engine-sharing','conversion','Sharing in the conversion engine','normalization-by-evaluation','implemented','notable',NULL,'Terms carry explicit sharing through an overlay with a named duplication policy, outside the trusted base and with no wire-format change; every check runs the copying stance.','core-nbe','crates/core-nbe/tests/duplication.rs',NULL,NULL,'b87a65d #2942');
INSERT INTO feature VALUES('epics-workflow','workflow','An epic closes itself once its units close',NULL,'implemented','ordinary',NULL,'An epic is blocked by its units: `issue:file --epic` and a body line `Advances #n`, `Part of #n` or `from: #n` naming an open epic set it blocked by the new issue, `unit:check` refuses a unit naming an epic not blocked by it, and `epics:link` backfills the relation from body references. When an issue closes, the epics workflow closes each open epic it blocked that is blocked by at least one issue and none open, commenting `<!-- epic-closed -->` with them; an epic blocked by nothing is never closed, and `report:deps` lists a ledger row owing on a closed issue, or only on an open epic.',NULL,'.config/epics/cases.json .config/epics/link.json .config/claims/report.json',NULL,NULL,'#2536 #3007 #3398');
INSERT INTO feature VALUES('equivalence-record','identity','Equivalences as a record type','univalence-theorem','partial','notable',NULL,'A ≃ B (A <~> B) is the bi-invertible record #{to, linv : #{g, sect}, rinv : #{h, retr}} and A ≅ B (Iso(A, B)) the quasi-inverse #{to, back, sect, retr}, both type formers lowered to the record they abbreviate with no kernel node, the printer and hover answering the former; isoToEquiv and equivToIso are corpus defs; the circle states winding : Path(Circle, Base, Base) ≃ Int. ua computing its certificate from the record is owed (#312).','surface-lowering','corpus/model/identity/equivalence.gandr corpus/model/identity/circle.gandr corpus/pathological/identity/iso-endpoint.gandr corpus/pathological/identity/equiv-fibres.gandr','corpus/ledger/features/equivalence-record.gandr','#312','#571 #2722');
INSERT INTO feature VALUES('equivalences','identity','Equivalences decided by computation (equiv)',NULL,'implemented','notable',NULL,'`equiv(f, g)` certifies two maps mutually inverse by computation, between codes built from units, base atoms, sums, products, lists and data types that do not hold themselves, a data type read constructor by constructor, and a value moves along the equivalence. A function moves along it by its maps, its argument back and its result forward, in the normalizer and the kernel alike, so a structure with operations relates along its carrier''s equivalence, between one type or two.','core-checker core-nbe kernel-core surface-diagnostics','corpus/model/identity/transport-list.gandr corpus/pathological/identity/equiv-list-tail.gandr corpus/model/identity/structure-operations.gandr corpus/model/identity/equiv-data.gandr corpus/pathological/identity/equiv-data.gandr','corpus/model/identity/transport-list.gandr',NULL,'#259 #1075 #1099 #1344 #1760 #1958');
INSERT INTO feature VALUES('executable-specifications','workflow','Executable specifications',NULL,'implemented','notable',NULL,'Every crate states its items'' contracts as specification clauses, checked at runtime by an enforcing test lane.','workflow-spec-cost','crates/core-nbe/src/arena.rs',NULL,NULL,'#51');
INSERT INTO feature VALUES('exits-across-handlers','effects','Exits across a handler frame','explicit-exits','implemented','notable',NULL,'A `return` inside a handled computation unwinds the handlers to the body''s reset, and a `become` across one is refused by name.','core-checker core-sequent','corpus/model/control/handler-exits.gandr corpus/pathological/control/handler-become.gandr','corpus/model/control/handler-exits.gandr','#216','#303');
