INSERT INTO feature VALUES('extension-types','identity','Extension types as face-theory signatures','glf-face-theory','partial','uncommon','dependent provers','An extension type is stated as a face-theory signature over its base type, face and partial element; the zero-fibre case checks and the rest is refused by name.','theory-computads surface-grammar surface-lowering','corpus/model/extension/zero-fiber.gandr corpus/pathological/extension/zero-fiber.gandr corpus/model/extension/generated.gandr corpus/pathological/extension/generated.gandr','corpus/ledger/features/extension-types.gandr','#641','#934 #1113 #2722');
INSERT INTO feature VALUES('features-exemplars','workflow','Feature exemplars','syntax-ledger','implemented','ordinary',NULL,'One focused exemplar per feature of the features ledger under `corpus/ledger/features/`, settled by `check:exemplars` (`gandr test`) and held by `check:syntax-exemplars` to what holds: `ledger/` is a fixture root, but a features exemplar states no `owes` or `refuses`.','surface-corpus','corpus/ledger/features',NULL,NULL,'#773 #1749');
INSERT INTO feature VALUES('features-guide','workflow','The features ledger as a guide','features-ledger','implemented','ordinary',NULL,'`gandr ledger list` prints one line per feature, narrowed to an area and a status, and `gandr ledger show <id>` a feature''s row, its exemplars'' sources whole and its corpus paths: what an author reads before writing a form. The Model Context Protocol server answers the same as `ledger_list` and `ledger_show`.','surface-dispatcher surface-driver surface-mcp','crates/surface-driver/tests/cli.rs::the_features_ledger_lists_and_shows_1827 crates/surface-mcp/src/connection.rs::the_ledger_tools_read_the_committed_ledger_1827',NULL,NULL,'#1867');
INSERT INTO feature VALUES('features-ledger','workflow','The features ledger',NULL,'implemented','notable',NULL,'What gandr implements, partly implements, plans and declines, one table in the tree whose rows carry their evidence, every path a row names checked by a gate, and every implemented language feature shown by an exemplar that settles or the crate tests that are its evidence.',NULL,'ledger/features.sql',NULL,NULL,'#1690');
INSERT INTO feature VALUES('first-class-environments','checking','First-class environments','bicontextual-core','planned','notable',NULL,'Environments as values with dependent merges, which the module layer can merge and seal.',NULL,NULL,NULL,'#340',NULL);
INSERT INTO feature VALUES('first-class-stacks','effects','First-class continuations (Stack)','effect-handlers','implemented','uncommon','mainstream languages','A continuation has the type `Stack(C, D)`, the computation it resumes from and the one it ends as; one that captured an obligation is one-shot, resumed or abandoned exactly once, never dropped and never captured by a thunk. An abandoned stack runs the unwind of each access it captured, innermost first, and never its other frames.; a function stating `Stack(C, D)` resumes the continuation it is handed, as the clause that bound it would','core-term core-checker core-sequent runtime-emitter','corpus/model/control/handler-exits.gandr corpus/model/cancellation/resumed.gandr corpus/pathological/cancellation/leaked.gandr corpus/model/drop/unwritten.gandr corpus/model/drop/unwound.gandr corpus/model/self-reference/suspended.gandr corpus/model/self-reference/relocated.gandr corpus/pathological/cancellation/handed.gandr','corpus/model/control/handler-exits.gandr',NULL,'#98 #1376 #1415 #1438 #1671');
INSERT INTO feature VALUES('floating-point','types','Binary64 floating-point numbers','native-primitives','partial','ordinary',NULL,'A number written with the `f64` suffix or annotated `(n : f64)` is an IEEE 754 binary64 float, the nearest double to its decimal text; `float64.add`, `sub`, `mul`, `div`, `neg` and `exp`, the six comparisons, `from_integer` and `round` run on the machine, `exp` the same double on every host. A fraction written bare states no type and is refused by name, with no default chosen; `f32` and exact reals are still to come.','kernel-term core-term core-checker surface-lowering runtime-emitter','corpus/model/basics/floats.gandr corpus/pathological/basics/fractions.gandr','corpus/ledger/features/floating-point.gandr','#1109 #2563','#1830 #2722');
INSERT INTO feature VALUES('footprint-separation','effects','Separate footprints at a fork','capabilities','partial','uncommon','mainstream languages','A fork''s two halves run as peers, so they share a host interface only when every operation either half may perform on it only reads: each half''s footprint is read off the types of the names it mentions, a held capability at its authority, a returner''s row at each interface it names, whole, and an operation performed by name, and a fork whose halves share an interface one of them may change is refused FootprintsOverlap.','core-term core-checker','corpus/ledger/features/footprint-separation.gandr corpus/ledger/diagnostics/FootprintsOverlap.gandr','corpus/ledger/features/footprint-separation.gandr','#2878 #2879','#2916');
INSERT INTO feature VALUES('for-loops','effects','For loops over lists','loops','implemented','ordinary',NULL,'`for` over a native list lowers to the list case former applied through the tail-recursive fixpoint, its termination the list''s own structure.','surface-lowering','corpus/surface/control-flow.gandr','corpus/surface/control-flow.gandr',NULL,'#1019');
INSERT INTO feature VALUES('forall-types','checking','The quantifier type forall a . T','implicit-arguments','declined','ordinary',NULL,'Declined by #1055: implicitness is a property of a declaration, never of its type, so there is no implicit Pi. A function quantifies over types in its prefix block, `@[a : Type]`, which the checker supplies at each call; the `forall_type` rule is deleted.',NULL,NULL,NULL,'#1055',NULL);
INSERT INTO feature VALUES('foreign-calls','runtime','Foreign calls as checked effects',NULL,'planned','notable',NULL,'A foreign call is an effect at the host seam, its boundary of signatures, layouts and ownership checked and certified, and a Rust callee''s behaviour checked against its specification at THIR (`rust-semantics-thir`).',NULL,'corpus/model/ffi/native-call.gandr',NULL,'#327',NULL);
INSERT INTO feature VALUES('formatter','printing','The source formatter',NULL,'implemented','ordinary',NULL,'`gandr fmt` lays a source out at a page width, keeping every token and comment and checking its meaning unchanged; each comment attached to the node it describes; `--form` and `@[ form(...) ]` rewrite between the sugared and the explicit spellings through a named rewrite table under the meaning check, a rewrite withdrawn visibly when it would change the meaning; the sugared form leaves a thunk type''s default grade `[ω]`, a tail return and the returner the lowering inserts at a definition''s result (`-> B` for `-> -F B`, an effect row kept) unwritten and writes a value-function alias at its shortest and a block''s linear runs at their reads, a match branch''s among them, a block left with no statement written as its one computation, checker-backed: a run is written away only where both spellings elaborate alike; a signature at a suspended returner or function and the thunk defining it, or the lambda the checker thunks, are written as one function form in either form, each binder of the lambda a parameter at its domain; any other signature and the definition directly after it, nothing but whitespace between them, are joined as `def x : T = e ;` in the sugared form and written apart in the explicit form; both one forms reach a module''s members, a nested module''s among them, as they reach top-level forms; the whole corpus is held to the sugared form.','surface-format surface-dispatcher','crates/surface-format/tests/format.rs crates/surface-format/tests/rewrite.rs corpus/model/basics/joined-definitions.gandr',NULL,NULL,'#158 #783 #793 #807 #828 #1339 #1349 #1373 #1423 #1532 #1914 #1972 #1975 #2258 #2264 #2294');
INSERT INTO feature VALUES('formatter-corpus-gate','printing','The formatter over the corpus','formatter','implemented','ordinary',NULL,'Every corpus source held to `gandr fmt --check`, an explicit-spelling subset kept as written.','surface-driver','.config/mise/tasks/mise-tasks-check.toml',NULL,'#491','#1050');
INSERT INTO feature VALUES('function-extensionality','identity','Function extensionality by computation',NULL,'partial','notable',NULL,'`funext(f, g)` is decided by evaluating both functions over their finite inputs, a data type covered as its constructors over their fields, and replayed by the kernel, open functions and a type holding itself refused by name; at the empty row it is also derived from `ua` for functions, a returned call read as the call it holds.','core-checker core-nbe kernel-core surface-diagnostics','corpus/model/identity/funext.gandr corpus/model/identity/funext-higher.gandr corpus/model/identity/funext-from-ua.gandr corpus/model/identity/funext-data.gandr corpus/pathological/identity/open-function-funext.gandr corpus/pathological/identity/funext-data.gandr','corpus/ledger/features/function-extensionality.gandr','#312','#254 #1546 #1555 #1962 #2722');
INSERT INTO feature VALUES('fusion-pass','runtime','Fusion as a certified pass',NULL,'partial','notable',NULL,'Derived rewrite cells applied to the command IL before code generation, deforestation among them.','runtime-emitter runtime-stencils','crates/runtime-emitter/src/fuse.rs crates/runtime-emitter/tests/agreement.rs crates/runtime-stencils/tests/agreement.rs',NULL,'#339','#1066');
INSERT INTO feature VALUES('gate-slots','workflow','The gate graph takes a host-wide slot',NULL,'implemented','ordinary',NULL,'`mise run check` holds one of the host''s `GANDR_GATE_SLOTS` (default two) gate slots for its whole run, a `flock` on `gate.<n>.lock` in the user''s runtime directory that a killed gate releases; a third gate prints `check: waiting on <holders>` and waits, or with `--no-wait` refuses at once. Each of its two test suites takes the host''s cores divided by the slots and by the suites, never more than a smaller `NEXTEST_TEST_THREADS` the caller set. A `check:*` task run alone takes no slot.',NULL,'.config/mise/gate.bash',NULL,NULL,'#3103');
INSERT INTO feature VALUES('generated-programs','corpus','Generated test programs',NULL,'planned','notable',NULL,'Type-directed generation of well-typed sources and free generation of ill-typed ones for testing the checker.',NULL,NULL,NULL,'#386',NULL);
INSERT INTO feature VALUES('generative-functors','modules','Generative functors','modules','implemented','notable',NULL,'A module parameterised by modules, each application minting fresh abstract types; a parameter is signed by a record signature or by Model(T), its components the ones the theory derives, each law stated at the parameter''s own operations; an argument names a module its source declares or one an unqualified import brings.','surface-lowering','corpus/model/modules/functor-pair.gandr corpus/pathological/modules/generative-distinctness.gandr corpus/model/modules/model-functor.gandr corpus/model/modules/model-functor-imported.gandr corpus/pathological/modules/functor-unexported.gandr corpus/pathological/modules/functor-mistyped.gandr','corpus/model/modules/functor-pair.gandr',NULL,'#280 #1283 #1989 #2023 #2024 #2189');
INSERT INTO feature VALUES('generic-programs','descriptions','Generic programs over descriptions','signatures-as-values','implemented','uncommon','mainstream languages','An ordinary function reads any presentation by case, and a function returning type codes is read as a type. A definition written `Eq.generic(T)` is structural equality over the data declaration `T`''s constructors, derived from its levitated code and checked as any declaration, so a model of `Eq` puts `T` under `==`; a field with no equality is refused by name, and a declaration with parameters, a nested or mutual recursion, or a dependent field is not yet covered (#2345).','surface-lowering core-term core-checker','corpus/model/desc/generic-arity.gandr corpus/model/desc/derive-eq-serialize.gandr corpus/model/desc/generic-arity-behind.gandr corpus/model/data/data-generic-eq.gandr corpus/pathological/data/generic-eq-refused.gandr','corpus/model/desc/generic-arity.gandr',NULL,'#350 #1095 #2302 #2779');
INSERT INTO feature VALUES('glf-face-theory','descriptions','GLF: the finite shape theory','glf-two-views','implemented','uncommon','dependent provers','Finite shapes as a FaceTT shape parameter with no interval: decidable subshapes with complements, meets, unions and the outer pushout (UnionSquare::mediator); atomic and conjunctive entailment (decide) with a Derivation or a Countermodel, each validated independently of the search; a conclusion''s column disjunctions admitted, as membership in a union, a disjunction across variables or in a premise refused at admission; evidence by meets, not case trees.','theory-shapes','crates/theory-shapes/tests/finite.rs crates/theory-shapes/tests/faces.rs','crate-tests','#640','#709 #885');
INSERT INTO feature VALUES('glf-lc-syntax-model','descriptions','The λ-calculus syntax model with its six substitution laws','glf-model-in-source','implemented','uncommon','dependent provers','The pure λ-calculus''s single-substitution calculus as `theory LC` (Con, Sub, Tm; nine operations; the six substitution laws) and its syntax model `module LCSyntax : Model(LC)` over de Bruijn terms, renamings and substitutions: laws 1, 2, 5 and 6 by computation, 3 and 4 by induction on the term through four fusion lemmas; every law a `Path` field discharged by `become` of a top-level lemma; the module packed into the record of LC''s models and a β-step run through it; 94 declarations, kernel-sealed. Lifting is a constructor (a definition refuses by #761, the pathological twin); `theory LC` is hand-written as `Lambda`''s first-order translation (#2422); the theory''s own declaration refuses `OutOfFragment` (#522) while `Model(LC)` derives from its presentation.','surface-corpus','corpus/model/desc/lc/ corpus/model/desc/lc/lift-as-definition.gandr','corpus/model/desc/lc/lift-as-definition.gandr','#640','#788');
INSERT INTO feature VALUES('glf-model-in-source','theory','A model of a signature written in source; the shape parameter','glf-two-views','partial','unique','dependent provers','A first-order model of a signature is written as a record type in source — Model(Nat) as #{nat : Type, zero : () => nat, succ : (n : nat) => nat}, its syntax model inhabiting it, the module packed into it — and a theory block states the finite shape its cells are over (shape Square : 4 { left = {0, 2}; … }), a face refused outside the shape or repeated; the λ-calculus single-substitution model as a record waits on gandr #721, its syntax model (two laws by induction on a neutral) the next unit.','theory-levitation','corpus/model/desc/model-in-source.gandr','corpus/ledger/features/glf-model-in-source.gandr','#640','#734 #2722');
INSERT INTO feature VALUES('glf-two-views','descriptions','GLF: the two views of a signature','levitated-descriptions','implemented','uncommon','dependent provers','The first-order model generated from a signature code by the single-substitution fold, each source equation read in it: a binding field as its body in the context its port extends, its variable as `$q` under `$p`, and a metavariable''s instantiation `t(u)` as the substitution operator, `$sub(t, $single(u))`; one generic evaluation and readback for every simply-sorted signature, identified with the first-order view on three signatures; the identity-return model''s judgements admitted by the kernel. A source cannot yet name the model it generates (#2422).','theory-levitation','crates/theory-levitation/tests/glf.rs','crate-tests','#640 #2422','#704 #2357');
INSERT INTO feature VALUES('grade-algebra','effects','Grade algebras',NULL,'partial','uncommon','mainstream languages','`std.grade` states `Grade`, an ordered semiring''s operations, and two models: `Usage`, the grades the tree writes, zero and one apart and each under many, and `Count`, the prelude''s binary naturals under sum and product. Each order is a function over closed data, so a path from it to `true` checks exactly when the order holds and the kernel replays it; an algebra over the native `Integer` decides nothing. A `Hom` names a map between two algebras, `collapse` counting''s to usage, and `covers` tests a grade of one against a need of another through it. The core''s grade positions do not read an algebra, and `Grade` states no law.',NULL,'library/std/src/grade.gandr corpus/ledger/features/grade-algebra.gandr corpus/model/effects/grade-algebra.gandr corpus/pathological/effects/grade-algebra.gandr','corpus/ledger/features/grade-algebra.gandr','#3392','#3452');
INSERT INTO feature VALUES('grades','effects','Grades on a hold','temporary-access','partial','uncommon','mainstream languages','A hold written hold[1] s = e holds its value at grade one: the entry is a value made in place, the held value is never copied while held (a copying read refused by name), and exclusive accesses lend it; a string held at grade one is written in place, a copy refused by name. The bracket is a numeral; the default grade is unwritten. The emitter does not yet read the grade to drop the holder count on a write-back.','core-term core-checker surface-grammar surface-lowering','corpus/model/control/held-unique.gandr corpus/pathological/control/held-unique.gandr corpus/model/strings/unique-write.gandr corpus/pathological/strings/unique-write.gandr','corpus/ledger/features/grades.gandr','#1219 #1175','#1212 #1618 #2722');
INSERT INTO feature VALUES('guarded-template-traces','rewriting','Guarded-template conversion traces','derivation-identity','planned','notable',NULL,'Conversion traces folded into guarded templates by anti-unification, checked once and replayed per member.',NULL,NULL,NULL,'#316',NULL);
INSERT INTO feature VALUES('guarded-templates','staging','Guarded families of staging equations','certified-staging','implemented','notable',NULL,'A family of staging equations is drafted from its last template and admitted under ordinary replay.','core-checker kernel-core','crates/core-checker/src/template/tests.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('hard-examples','corpus','A hard-examples corpus',NULL,'planned','notable',NULL,'Constructions with a settled verdict in the literature, each a corpus source admitted or refused by name.',NULL,NULL,NULL,'#446',NULL);
INSERT INTO feature VALUES('higher-order-fields','descriptions','Function fields in described families','levitated-descriptions','partial','notable',NULL,'A constructor field written `A => T` is the description code''s function former over its domains, decoded to the thunked arrow the native reading gives it, so a presented type holds a continuation: programs over a state, quotiented by put-put, check, and their state-passing handler folds through a read''s continuation while a store count is refused by the rule. An observation taking an argument has no code yet (#2859), and a rule applying a continuation is refused (#2861).','theory-levitation core-term surface-lowering','corpus/model/desc/function-field.gandr corpus/pathological/desc/function-field.gandr corpus/ledger/features/higher-order-fields.gandr','corpus/ledger/features/higher-order-fields.gandr','#2859','#2897');
INSERT INTO feature VALUES('host-effects','effects','Host effects','effect-rows','implemented','notable',NULL,'An interface the host declares, `Console` with `print : String ↠ Unit` among them, is performed by its name, `Console.print(s)`, under a row naming it; the entry''s handler is the host''s, `gandr run` writing each printed line to standard output and a `runs` expectation keeping them, two models of one interface. A row naming an interface no host declares is refused by its name.','core-term surface-lowering surface-dispatcher surface-driver','corpus/model/effects/hello.gandr corpus/pathological/effects/hello-unprovided.gandr crates/surface-driver/tests/cli.rs','corpus/model/effects/hello.gandr',NULL,'#2297');
INSERT INTO feature VALUES('hover','editor','Hover types everywhere','language-server','implemented','notable',NULL,'Every node hovers its type in its node kind''s shape, coloured by role, settled and refused declarations alike.','surface-lsp surface-pretty surface-dispatcher','crates/surface-lsp/src/hover.rs crates/surface-lsp/tests/editor/shapes.rs crates/surface-lsp/src/signature.rs crates/surface-lsp/src/server.rs crates/surface-lsp/src/recheck.rs crates/surface-dispatcher/tests/corpus.rs crates/surface-dispatcher/src/typed.rs crates/surface-dispatcher/tests/census.rs',NULL,'#232','#154 #1530 #1537 #1554 #2438 #2492');
INSERT INTO feature VALUES('hover-stubs','editor','A hover at every tile','hover','implemented','uncommon','mainstream editors','Every corpus position answers a hover: a settled node its type, a gap a stub naming the syntax kind and the tracking issue that owes it; the sweep over fixture/ and strict/ refuses a silent tile.','surface-lsp','corpus/model/basics/arithmetic.gandr corpus/model/completion/buffer-moved.gandr corpus/fragment/exits.gandr corpus/fragment/undefined-term-name.gandr strict/trailing-delimiters.gandr corpus/pathological/data/nested-call-tells-apart.gandr corpus/pathological/module-duplicate-member.gandr',NULL,NULL,'#1230 #1272 #1281');
INSERT INTO feature VALUES('identity-by-recursion','identity','Identity computed by the type''s structure','identity-types','implemented','notable',NULL,'The identity type of a structured type is computed from its formers, a path of pairs a pair of paths.','kernel-core core-checker','corpus/model/data/sigma-pair.gandr','corpus/model/data/sigma-pair.gandr',NULL,'#204');
INSERT INTO feature VALUES('identity-types','identity','Identity types (Path)',NULL,'implemented','uncommon','mainstream languages','`Path(A, a, b)` is the type of identifications between two elements, checked by the core and persisted by the kernel.','core-checker kernel-core kernel-term','corpus/model/identity/here-formation.gandr','corpus/ledger/features/identity-types.gandr',NULL,'#204');
INSERT INTO feature VALUES('implicit-arguments','checking','Implicit arguments',NULL,'partial','ordinary',NULL,'Arguments the checker supplies through a prefix telescope, contextual metavariables and a spine pass. Rung A landed: implicits declared in one @[...] prefix block, the core telescope interleaved by dependency, supply by name through the slot (f[i = e]), a standing supply. Rung B landed: the solver (#1213) binds a contextual metavariable only where an equation forces a most general solution, postponing every other equation in one store by reason and blockers and refuting only a clash of introduction forms or a strongly rigid occurrence; the spine pass (#1216) makes each implicit a call omits a hole the call nominates, declared at the call''s binders, bound by the comparison that decodes it, and supplied in the body the checker emits, so the kernel never meets a metavariable. An implicit nothing forces is refused ImplicitUnsolved with the solver''s reason, and two arguments disagreeing on one are a type mismatch. Rung C remains.','core-term surface-lowering core-unify core-checker surface-pretty surface-diagnostics','corpus/classifier/implicit-telescope.gandr corpus/pathological/classifier/implicit-telescope.gandr crates/core-unify/tests/solve.rs crates/core-checker/src/bridge/tests.rs::an_omitted_implicit_is_supplied_before_the_kernel_1216','corpus/ledger/features/implicit-arguments.gandr','#315','#1186 #1213 #1924 #2722');
INSERT INTO feature VALUES('imports','modules','Imports',NULL,'implemented','ordinary',NULL,'An import brings another module''s names into scope through the namespace engine.','surface-lowering','corpus/surface/module-import.gandr corpus/pathological/modules/import-unresolved.gandr corpus/pathological/modules/import-shadows.gandr','corpus/ledger/features/imports.gandr',NULL,'aced9bb');
INSERT INTO feature VALUES('incremental-checking','incremental','Incremental checking',NULL,'implemented','notable',NULL,'An edit rejudges only the items whose consulted answers changed, matching a batch check; the language server''s recheck resumes the import closure instead of readmitting it, and lowers the document''s own source alone over the closure''s lowering, held once per process, sharing the closure''s plans rather than copying them; the closure''s origins are carried once per judgement, and each source''s node tables are forgotten once it is lowered, so the suspended lowering holds none of the closure''s; the closure''s scope tables are finished once when it is suspended, and the document''s finish extends them with its own. The closure is judged once and the document on a copy of its context, the program, settle report and spellings joined at the boundary. The incremental pass''s state after the closure''s items is led once per closure and root, and each revision is submitted after it, encoding and judging only its own items; the hover table types the document on the closure''s context. An adopted item''s checked or synthesised type is seated as its judgement formed it, with no formation walk. A copy''s first judgement resumes from what an earlier copy of its document recorded — another connection''s copy, else the last one let go — whatever its text. The kernel readmission resumes the leading declarations a revision shares with the one admitted before it, a session holding its own runs past the closure, so a revision that changes no declaration offers the kernel none; the record it resumes freezes the kernel environment it keeps, so each resume shares the record''s arena and copies only the nodes it mints. The program a judged closure''s documents continue is frozen once, so each revision copies only the IL rows it focuses itself. A revision whose lowering moves no node of the one judged before it, as a comment''s does, takes that judgement''s verdicts rather than judging again, and settles and spells again at its own spans. A keystroke lays its document out over the path imports its last judgement''s parse read rather than parsing it again; a judgement whose parse reads others is laid out again, and stands when that lay-out closes it over the same closure, else is judged again.','core-incremental','crates/core-incremental/tests/incremental.rs crates/core-incremental/src/session/tests.rs crates/surface-session/tests/session.rs crates/surface-session/tests/checkpoint.rs crates/surface-session/tests/incremental.rs crates/surface-lsp/tests/session.rs crates/surface-lsp/src/server.rs crates/core-checker/src/bridge/tests.rs crates/surface-lowering/tests/namespace.rs crates/surface-lowering/src/table.rs crates/surface-dispatcher/src/compose.rs crates/core-checker/tests/recursive_data.rs crates/surface-dispatcher/src/component.rs crates/kernel-term/src/arena.rs crates/kernel-core/src/env.rs crates/core-sequent/src/il/tests.rs',NULL,NULL,'#101 #801 #1060 #1137 #1151 #1156 #1159 #1162 #1276 #1279 #1290 #1297 #1302 #1325 #2214 #2226 #2249 #2431 #2453 #2475 #2485');
INSERT INTO feature VALUES('incremental-parsing','syntax','Incremental re-parsing','total-parsing','implemented','notable',NULL,'An edit relabels around itself and re-molds only the top-level forms it touched.','surface-parser surface-session','crates/surface-session/tests/edit.rs',NULL,NULL,'#101');
INSERT INTO feature VALUES('indexed-data','types','Indexed data families','nominal-data','partial','notable',NULL,'Data families indexed by values, admitted at their stated indices with the header''s kind and the index binders typed; a case on one checks each arm at its own constructor''s fields and binds past them one equation per index, from the index its constructor states to the scrutinee''s, and at a family of one index an arm whose constructor stands apart from the scrutinee''s index is left out; pruning at several indices and refinement by unification at a match owed.','kernel-core kernel-term core-term core-checker core-nbe core-sequent core-incremental surface-lowering surface-pretty','corpus/model/data/vectors.gandr corpus/pathological/data/vectors.gandr corpus/model/data/vector-cases.gandr corpus/model/data/vector-head.gandr corpus/pathological/data/vector-head.gandr','corpus/ledger/features/indexed-data.gandr','#1314','#961 #1963 #1969 #2722');
INSERT INTO feature VALUES('indexed-sorts','descriptions','Dependent sorts in signatures','signatures-as-values','partial','notable',NULL,'Sorts indexed by other sorts, or by the host''s types, in a `theory` block and in `Model(S)`, the shape a category-with-families signature needs. `Model(S)` states an indexed sort as a function from its indices into the universe its classifier names, the computation types for a `Type[-]` sort, an index over the host''s types a binder at `Type` and one at a builtin type a binder at that type, a later field reading it applied and an applied index term run first; a member answering a sort in the other ground sort is refused at its name. Rules over indexed sorts are owed (#522), and ports at a computation sort (#2899).','surface-lowering theory-levitation','corpus/model/higher-cells/cat-shape.gandr corpus/model/desc/lc/model-record.gandr corpus/pathological/desc/relative-monad.gandr','corpus/ledger/features/indexed-sorts.gandr','#522 #2899','#1358 #2722 #3075 #3081 #3150 #3271');
INSERT INTO feature VALUES('induction-recursion','universes','Inductive-recursive definitions','tarski-universes','implemented','notable',NULL,'A mutual block whose data''s constructor types mention the functions defined with it.','core-term core-checker kernel-core','corpus/model/universe/inductive-recursive.gandr corpus/pathological/universe/inductive-recursive.gandr','corpus/model/universe/inductive-recursive.gandr','','#580');
INSERT INTO feature VALUES('inert-fields','modules','A theory''s inert operations','packages','implemented','ordinary',NULL,'A theory''s operation marked `@[ inert ]` is a field the manifest step reads, a package''s name or version: a model''s component for it is inert, an `include` carries the mark, and a declaration that is no inert component and reads one, by its path, by its name inside the model or off a model binder, is refused `InertRead`; the mark stands only on an operation, and a theory''s member takes no other attribute. A package''s address leaves every inert component out, so an edit to one moves no address.','surface-grammar surface-lowering surface-dispatcher','corpus/model/modules/inert-field.gandr corpus/pathological/modules/inert-field.gandr crates/surface-lowering/tests/modules/models.rs::an_inert_field_is_read_only_by_another_3029 crates/surface-dispatcher/tests/package.rs::every_corpus_package_s_address_ignores_its_inert_fields_3030','corpus/ledger/features/inert-fields.gandr',NULL,'#3029 #3047 #3069');
INSERT INTO feature VALUES('inferred-exits','effects','Exits and runs inferred by polarity','explicit-exits','implemented','notable',NULL,'A tail''s exit and a nested computation''s run are inferred from polarity, the keywords kept as assertions a lint asks for.','surface-lowering surface-diagnostics','corpus/fragment/missing-exit.gandr','corpus/fragment/missing-exit.gandr','#256','#267');
