INSERT INTO feature VALUES('input-method','editor','Unicode input method','vscode-extension','implemented','ordinary',NULL,'A backslash command offers its Unicode glyphs through the suggest widget, a fork continuing one step at a time, on for gandr and per language for others; the table is generated from Agda''s input method and the W3C and LaTeX names, each pinned by digest.','contrib/gandr-vscode','contrib/gandr-vscode/src/input/trie.test.ts',NULL,NULL,'#1757');
INSERT INTO feature VALUES('instantiation-by-staging','staging','Instantiation by staging',NULL,'planned','notable',NULL,'A static code specialises by staging into a certified instance memoized by content, a dynamic one passed with its layout witness.',NULL,NULL,NULL,'#342',NULL);
INSERT INTO feature VALUES('interactive-session','tooling','Interactive sessions',NULL,'implemented','notable',NULL,'Each revision of a source is lowered, judged as `gandr check` judges it, resumed through the incremental checker and checkpointed.','surface-session','crates/surface-session/tests/session.rs',NULL,NULL,'411c19c');
INSERT INTO feature VALUES('interop-boundary','runtime','The boundary with Rust, called both ways','foreign-calls','partial','uncommon','mainstream languages','A Rust caller holding a composed program calls one of its definitions by name on values it builds and reads the answer back into its own arena, the arguments applied in order, an answered function left unforced and a refused definition unrunnable before a run. An `extern "rust"` block of fixed-width members declares an interface its source''s definitions perform and the Rust caller''s host answers; a member beyond the form is refused by name. A block carrying `boundary` is admitted where it is declared: each member''s declared types, printed by Rust''s default layout, realise the row the attribute names for it, or the block is refused `BoundaryUnrealised` by the clause a member breaks. A value crosses by its layout as words: the Rust caller lends its memory and passes a word, and gandr reads the memory behind it only through a block''s reads, which the host answers at the addresses it lent. A list Rust holds tagged or packed decodes into its layout''s data type, and the `length` transported along that layout''s path answers what Rust counts; `Option<&u32>`''s null word reads as `None`. A source importing a block does not yet see its interface.','surface-corpus surface-dispatcher surface-lowering','crates/surface-dispatcher/tests/boundary.rs crates/surface-lowering/src/lower/capability/tests.rs crates/surface-lowering/src/lower/boundary/tests.rs corpus/model/interop/boundary/round-trip.gandr corpus/model/interop/boundary/by-layout.gandr corpus/pathological/interop/boundary/extern-form.gandr','corpus/ledger/features/interop-boundary.gandr','#3138','#3056 #3081 #3118 #3154');
