INSERT INTO feature VALUES('issue-dependencies','workflow','Issue dependencies and labels set by the tools',NULL,'implemented','ordinary',NULL,'Every unit issue states what it waits on in `## After`, and the tools set it as the GitHub `blocked by` dependency: `unit:check` refuses a missing or malformed section and an unset dependency, `--fix` sets it, `issue:file` sets it as it files and links the issue under its epic, an epic is blocked by each open sub-issue, `epic:order --chain` sets a ladder''s chain, `claim:next` passes over a blocked issue and ranks by priority within each bucket, and the nightly `report:deps` lists each dependency stated in prose and not set. `issue:file` refuses an issue short of one `kind:`, `area:`, `priority:` and `effort:` label, a missing priority or effort taking its kind''s default from one table.',NULL,'.config/claims/deps.json .config/claims/next.json .config/claims/report.json .config/issues/cases.json',NULL,NULL,'#2902');
INSERT INTO feature VALUES('joined-definitions','syntax','A signature joined with its value',NULL,'implemented','ordinary',NULL,'`def x : T = e ;` declares a name''s type and its value in one item, filed as the two halves a signature and a definition written apart file, so hover, outline and definition answer on it and a second signature or definition of the name is refused as a duplicate.','surface-grammar surface-lowering','corpus/model/basics/joined-definitions.gandr corpus/model/basics/joined-definitions-explicit.gandr','corpus/model/basics/joined-definitions.gandr',NULL,'#2258');
INSERT INTO feature VALUES('kernel-admission','kernel','The kernel admission choke point',NULL,'implemented','notable',NULL,'Every declaration enters the trusted environment by staging and admission, an abandoned one truncating its content.','kernel-core','crates/kernel-core/tests/acceptance.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('kernel-readmission','kernel','Independent kernel readmission','kernel-admission','implemented','notable',NULL,'Each declaration the checker accepts is re-derived by the kernel in a fresh environment before it is exported. A deep handler is re-derived as the fold of its effect''s free model, a data declaration of one constructor per operation admitted ahead of its first handler. A capability scope the one model in scope answers crosses with that model''s components filled in, the same definition as the scope naming it.','core-checker kernel-core','crates/core-checker/tests/recursive_data.rs crates/surface-corpus/src/kernel_export.rs corpus/model/effects/state-handler.gandr','corpus/model/effects/state-handler.gandr',NULL,'b87a65d #2745 #2772 #2836');
