INSERT INTO feature VALUES('language-server','editor','The language server',NULL,'implemented','notable',NULL,'`gandr lsp` serves diagnostics, semantic tokens, outline, folding, formatting, hover, inline completion, definition, type definition, completion, signature help, watched files, workspace symbols, document highlight and references over the Language Server Protocol; the rest of the surface is #764''s list.','surface-lsp','crates/surface-lsp/tests/session.rs',NULL,'#764','e834493');
INSERT INTO feature VALUES('layout-engine','printing','The layout engine',NULL,'implemented','notable',NULL,'Documents are resolved to a page width by Pareto resolution over candidate layouts and rendered by a first-order machine.','surface-layout','crates/surface-layout/tests/algebra.rs',NULL,NULL,'#4 #1597');
INSERT INTO feature VALUES('lazy-records','types','Lazy records (negative products)',NULL,'implemented','notable',NULL,'A computation record of components evaluated on projection, with its η rule, persisted by the kernel; an entry is observed by its position, `m.i`, against a stated lazy record, lazy product chain or codata family, and a parameter''s observation prints as `a.i`. The bundle `co { l = c, … }` is the same record written over bare labels.','core-checker core-incremental core-nbe core-sequent core-term kernel-core kernel-term runtime-stencils surface-format surface-lowering surface-pretty','corpus/surface/arity/lazy-record.gandr corpus/pathological/codata/lazy-record-projection.gandr corpus/pathological/type-associativity.gandr corpus/model/codata/codata-observations.gandr','corpus/model/codata/codata-observations.gandr',NULL,'#237 #1053 #1117 #1305 #1313');
INSERT INTO feature VALUES('level-evidence','universes','Level constraints with checkable evidence','universes','implemented','notable',NULL,'Level order, constraint admission and entailment each answer with evidence in both directions that a separate validator checks.','kernel-strata','crates/kernel-strata/tests/level_oracle.rs crates/kernel-strata/tests/entailment_oracle.rs','crate-tests',NULL,'b87a65d');
INSERT INTO feature VALUES('levitated-descriptions','descriptions','Levitated descriptions','signatures-as-values','implemented','notable',NULL,'A code universe of descriptions, first-order but for one function former over value types (higher-order-fields), populated by declarations, drives generic programs, rule faces and multi-output arities. Sort descriptions carry a representability bit and the restricted binder π⁺ (a binder over a representable sort), refused by check_desc otherwise. A theory block lowers to its description and the rendering reparses to the same description (#724); Theory carries representability and π⁺ (the port rule), its identity bytes moved once with their cause; TheoryDesc is read off the Theory value by theory-levitation''s TheoryValue::description, which the reader calls (#1384).','theory-levitation','corpus/model/desc/desc-inspect.gandr','corpus/model/desc/desc-inspect.gandr',NULL,'812c4c0 #1384 #1442 #2897');
INSERT INTO feature VALUES('lints','diagnostics','Lints with fixes','diagnostics-model','implemented','ordinary',NULL,'A lint finding carries the edit that settles it, as the `explicit-exits` and `explicit-runs` lints do.','surface-diagnostics','crates/surface-diagnostics/src/lint.rs',NULL,NULL,'#267');
INSERT INTO feature VALUES('list-case','types','Case over native lists','native-lists','implemented','ordinary',NULL,'A case former on the native list — nil and cons arms — in the core and the kernel, with its applied-fixpoint check rule; the ground `for` reads through it.','core-term kernel-term kernel-core core-checker core-nbe core-sequent core-incremental surface-pretty','corpus/surface/control-flow.gandr','corpus/surface/control-flow.gandr',NULL,'#1019');
INSERT INTO feature VALUES('live-evaluation','checking','Evaluation through holes',NULL,'implemented','notable',NULL,'A program with holes evaluates as far as it can, holes standing as neutrals, and resumes after a fill.','core-nbe core-incremental','crates/core-nbe/src/live.rs','crate-tests',NULL,'#99');
INSERT INTO feature VALUES('located-judgements','sessions','Located judgements over declared worlds','session-types','implemented','unique','mainstream languages','A source declares its worlds (world w ;); typing stands at one; A at w is a handle to a value at w; hold, leta and migrate [w] { t } make, open and cross; a migration spends the consumable capability cap_w its entry holds (@[ entry(home, w, …) ] bounded by the host''s --entry); only what is mobile (mobile type T at sealing) and open comes back.','core-term core-checker','corpus/model/worlds/seat-and-operator.gandr corpus/pathological/worlds/immobile-crossing.gandr corpus/pathological/worlds/capability-accounting.gandr corpus/pathological/worlds/located-reads.gandr','corpus/model/worlds/seat-and-operator.gandr','#521','#624');
INSERT INTO feature VALUES('loop-carried-state','effects','Loop-carried state through held slots','loops','implemented','notable',NULL,'A slot held outside a loop and accessed inside it is threaded as an accumulator argument of the loop''s tail-recursive fold, so a loop mutates only the state its recursive call shows and the measure reads the accumulator; a nested loop over the same slot is refused by name until it is threaded in turn.','surface-lowering','corpus/model/control/accessor-loop.gandr corpus/pathological/control/accessor-loop-nested.gandr','corpus/model/control/accessor-loop.gandr','#1143','#1148');
INSERT INTO feature VALUES('loop-obligations','identity','Loop obligations in circle elimination','presented-circle','implemented','notable',NULL,'A dependent case over the circle owes its loop, by conversion or by a `loop` arm, through maps of any arity.','core-checker kernel-core','corpus/model/identity/circle-elim.gandr corpus/model/identity/circle-maps.gandr','corpus/model/identity/circle-elim.gandr',NULL,'#388');
INSERT INTO feature VALUES('loops','effects','Loops with break and continue',NULL,'implemented','ordinary',NULL,'`loop` and `while` lower into the partial fixpoint, `break` and `continue` as direct cuts; a function holding one states `Div` in its row.','surface-lowering core-sequent','corpus/surface/control-flow.gandr','corpus/surface/control-flow.gandr',NULL,'#284');
INSERT INTO feature VALUES('lossless-syntax','syntax','Lossless syntax with attached comments','total-parsing','implemented','ordinary',NULL,'Every byte survives in the tree, each comment owned by the node it describes and read by no digest.','surface-parser surface-syntax','crates/surface-syntax/src/tree.rs',NULL,NULL,'#146');
INSERT INTO feature VALUES('lsp-call-hierarchy','editor','Call hierarchy','language-server','implemented','ordinary',NULL,'The incoming and outgoing calls of a declared value, read from the referent index over the document''s closure.','surface-lsp','corpus/model/data/following.gandr crates/surface-lsp/src/server.rs',NULL,'#764','#1595');
INSERT INTO feature VALUES('lsp-code-lens','editor','Code lens','language-server','partial','ordinary',NULL,'A lens over each declared name counts its references across the open documents, from the reverse use index, and resolves to the references command; a lens whose document is closed resolves to no command.','surface-lsp','corpus/model/identity/circle-base.gandr',NULL,'#1116','#1394');
INSERT INTO feature VALUES('lsp-completion','editor','Completion','language-server','implemented','ordinary',NULL,'The names and keywords the word at the cursor may complete to, chosen by the slot the parser''s continuations name: binders in scope innermost first, declared names from a sorted list per text cut by prefix, keywords in grammar order, a completed keyword inserting its form as a snippet with its tab stops, a completed call its parameters as stops; after them, the names a source under the opened folders declares that no import reaches, each with its import line as detail and the import as an additional edit, from the workspace-symbol index; `isIncomplete: false`.','surface-lsp surface-dispatcher surface-lowering','crates/surface-lsp/src/complete.rs crates/surface-lsp/tests/session.rs crates/surface-lsp/src/server.rs',NULL,'#764','#834 #1412 #1431 #1779');
INSERT INTO feature VALUES('lsp-document-highlight','editor','Document highlight','language-server','implemented','ordinary',NULL,'The declaration of the name at the cursor and every use referring to it in the document, from the reverse referent index.','surface-lsp surface-dispatcher','crates/surface-lsp/src/uses.rs',NULL,'#764','#856');
INSERT INTO feature VALUES('lsp-ghost-text','editor','Ghost texts','language-server','implemented','ordinary',NULL,'A one-line ghost text at the cursor: the continuation the parser expects to close an open form — a line comment left open, an open call — offered as inline text, withdrawn at the next change.','surface-lsp','crates/surface-lsp/src/server.rs',NULL,'#764','#1573');
INSERT INTO feature VALUES('lsp-inlay-hints','editor','Inlay hints','language-server','implemented','ordinary',NULL,'Every binder that writes no type is hinted with the type the judgement gave it, read from the recheck''s table; a hint resolves to the declaration it names.','surface-lsp','corpus/surface/control-flow.gandr crates/surface-lsp/src/inlay.rs',NULL,'#764','#1573 #1607');
INSERT INTO feature VALUES('lsp-missing-imports','editor','Missing imports offered','language-server','implemented','ordinary',NULL,'A name refused as naming nothing is offered a quick fix importing each source under the opened folders, not yet imported, that declares it where it is written, a type finding a family and a value a value or a constructor; preferred when only one source does.','surface-lsp','crates/surface-lsp/src/missing.rs crates/surface-lsp/src/server.rs',NULL,'#1116','#1806');
INSERT INTO feature VALUES('lsp-paste-imports','editor','Paste with imports','language-server','implemented','uncommon','mainstream editors','A copy carries the sources its names are declared in; a paste into another document adds the imports those names need.','surface-lsp','corpus/model/data/following.gandr crates/surface-lsp/src/server.rs',NULL,'#764','#1573');
INSERT INTO feature VALUES('lsp-pull-diagnostics','editor','Pulled diagnostics','language-server','implemented','ordinary',NULL,'A client that pulls a document''s diagnostics is answered what its copy last published, named by the BLAKE3 digest of their JSON text, and answered unchanged when it names that digest; a pull waits for the copy''s judgement, a change before it is judged cancelling the pull for the client to ask again, nothing is published to it, and a publication no pull waited for asks it to pull again when it refreshes. Diagnostics of sources no editor holds are not answered.','surface-lsp','crates/surface-lsp/src/server.rs',NULL,'#764','#1809');
INSERT INTO feature VALUES('lsp-references','editor','References','language-server','implemented','ordinary',NULL,'Every use of the name at the cursor across the open documents, each asked of its own reverse use index at the index its closure gave the source — no text search, no resolution per request; the declaration included when the client asks.','surface-lsp surface-dispatcher','crates/surface-lsp/src/uses.rs crates/surface-lsp/src/server.rs',NULL,'#764','#865');
INSERT INTO feature VALUES('lsp-unused-binders','editor','Unused binders hinted','language-server','implemented','ordinary',NULL,'A lambda''s or a bind''s binder that no use reads is hinted unnecessary in every declaration the checker judged, refused or not, but one refused for a consumable capability; a name starting with `_` is not.','surface-dispatcher surface-lsp','corpus/pathological/completion/buffer-misused.gandr corpus/pathological/control/capability-drop.gandr',NULL,NULL,'#1660');
INSERT INTO feature VALUES('lsp-unused-imports','editor','Unused imports faded and removable','language-server','implemented','ordinary',NULL,'An import no lookup reaches is published as an unnecessary hint, and a code action offers its removal.','surface-lsp surface-lowering','corpus/model/cancellation/answered.gandr crates/surface-lsp/src/server.rs',NULL,'#1116','#1619 #1637');
INSERT INTO feature VALUES('lsp-watched-files','editor','Watched files','language-server','implemented','ordinary',NULL,'A client with dynamic registration is asked at `initialized` to watch `**/*.gandr`; a change on disk rechecks and republishes only the held copies whose last closure named that path, a missing import''s path included, so writing the file heals its importer; the editor''s own copy of a changed file is never replaced from disk. A closure''s read of a file a watcher reports stands without a look at the disk until the watcher reports it; every other file is confirmed at each lay-out.','surface-lsp surface-dispatcher','crates/surface-lsp/src/server.rs crates/surface-dispatcher/src/component.rs',NULL,'#764','#848 #1523');
INSERT INTO feature VALUES('lsp-workspace-symbol','editor','Workspace symbols','language-server','implemented','ordinary',NULL,'A query finds every name the open documents'' import closures declare, constructors included, and every name a source under the opened folders declares that no editor holds, by subsequence match on the lowercased name, at most 128 sorted by name; a closure''s names come from a per-copy index read off the type table, a source''s from its outline, read from one parse and kept under its file''s length and modification time, built on the first request.','surface-lsp surface-dispatcher','crates/surface-lsp/src/search.rs crates/surface-lsp/src/files.rs',NULL,'#764','#851 #1772');
INSERT INTO feature VALUES('mcp-server','editor','The Model Context Protocol server','engine-hub','implemented','uncommon','mainstream editors','`gandr mcp` serves the hub''s open documents, diagnostics, types, outline and candidate fills to models as tools and resources.','surface-mcp','crates/surface-mcp/src/lib.rs',NULL,'#123','#166');
INSERT INTO feature VALUES('meta-cells','descriptions','Coherence cells in signatures','signatures-as-values','planned','unique','dependent provers','A declared coherence between two rules discharged by the completion certificate rather than carried.',NULL,NULL,NULL,'#314',NULL);
INSERT INTO feature VALUES('method-calls','effects','Method calls','temporary-access','implemented','uncommon','mainstream languages','A module member whose first parameter is `self` is a method, and a call `s.f(a)` on a held receiver is the access its mode lends: `self : shared T` a shared view, `self : T` an exclusive view the body writes through and hands back, `self : consumed T` the hold taken; a receiver that is no held slot is passed as a value, and a method two modules in scope declare is refused naming both. A receiver taken in one arm of a match leaves each other arm the hold the match found, and the hold is spent after the match.','core-term core-checker core-nbe runtime-emitter surface-lowering','corpus/model/strings/methods.gandr corpus/pathological/strings/methods.gandr corpus/pathological/strings/method-ambiguity.gandr corpus/model/control/accessor-method.gandr corpus/pathological/control/accessor-method.gandr','corpus/model/strings/methods.gandr',NULL,'#1519 #1584 #1697');
INSERT INTO feature VALUES('migrate-wire','runtime','A migration shipped to the process its world is bound to','world-migration','partial','unique','mainstream languages','A host''s world bindings, `--world <world>=<key>@<ip:port>` or the manifold they desugar from, bind each declared world to the key of the process it runs at: `gandr run` ships a migration to a world bound to another key over the world wire — its code named by the program''s digest and its place, each capture by its manifest — and `gandr host` of the same source runs it, fetching over the migration''s connection only the captures it does not hold whole, and the answer crosses back by content. A migration to a world bound to this host runs here, and an entry that may migrate to a world no binding names is refused `UnboundWorld` before it runs. Both processes hold the program as source; a far host loading it by content key is owed (#3293).','runtime-net runtime-emitter surface-dispatcher surface-driver','corpus/ledger/features/migrate-wire.gandr corpus/model/worlds/two-processes.gandr corpus/model/worlds/two-processes.manifold.gandr crates/runtime-net/tests/worlds.rs crates/runtime-emitter/tests/world.rs crates/surface-dispatcher/tests/run.rs crates/surface-driver/tests/net.rs','corpus/ledger/features/migrate-wire.gandr','#3293','#3315 #3458');
INSERT INTO feature VALUES('model-include','modules','Model includes','modules','implemented','notable',NULL,'A module body''s `include M ;` takes the module `M`''s members as its own when the module closes, its exports when `M` is ascribed, so a model of a theory including another builds on a model of the included one rather than restating it, and its reduct at the included theory is that model, member for member; a name the body also writes is refused as a second definition, and a name no module answers is refused by that name.','surface-grammar surface-lowering core-checker','corpus/model/modules/model-include.gandr corpus/pathological/modules/model-include.gandr','corpus/model/modules/model-include.gandr',NULL,'#2333');
INSERT INTO feature VALUES('modular-implicits','checking','Modular implicits: a model resolved for an implicit','implicit-arguments','implemented','notable',NULL,'A function quantifies over a model in its prefix block, `@[s : Model(S)]`, which binds one implicit parameter per component of `S` (a sort a manifest model type fixes binds none) and no record of the model; the body reads each as `s.x`. A call supplies a module by its name, `f[s = M]`, passing its members, a module of a theory including `S` passing its reduct, or passes a model implicit of its own on, `f[s = t]`; a model implicit named alone or supplied a value is refused; a call omitting the slot resolves it to the one module in scope, local or imported, whose ascription is `Model(S)` or a model of a theory including `S`, at the types its explicit arguments force and, at a manifest model type, at the sorts the type fixes, counting modules whose components convert, as a module including another does at that model, as one elaboration, and refuses a slot no module answers or two elaborations do, naming every module left. Path endpoints compared while a slot they call through is unresolved, `here(x == y)` at `Path(Bool, x == y, x == y)` among them, wait for the resolution, and are judged with the body and the declared type both filled. The printer and the hover write it as the source does: a definition''s slot whole with its fixed sorts, each component by its path, and a call''s supply by the module or the implicit it names.','surface-lowering core-checker surface-pretty surface-diagnostics surface-dispatcher','corpus/model/modules/model-implicit.gandr corpus/model/modules/model-implicit-manifest.gandr corpus/model/modules/model-resolution.gandr corpus/model/modules/model-resolution-swapped.gandr corpus/model/modules/model-resolution-manifest.gandr corpus/model/modules/model-include.gandr corpus/model/identity/here-congruence.gandr corpus/pathological/modules/model-implicit-supply.gandr corpus/pathological/modules/model-implicit-resolution.gandr corpus/pathological/modules/model-include.gandr','corpus/model/modules/model-implicit.gandr',NULL,'#2370 #2417');
INSERT INTO feature VALUES('module-nesting','modules','Nested modules and paths','modules','implemented','ordinary',NULL,'Modules declared inside modules and reached by dotted paths, with signature matching across them. A dotted declaration name, `theory Kit.Labelled` or `module Kit.Tools`, declares in the modules its prefix names, each opened where the source declares no module of that name and exported once a declaration made through it is; `Model(Kit.Labelled)` reads a theory by its path, and the prelude declares `Gandr.Package` so. A prefix may run any depth, `Deep.Mid.Low.Shape`, and a module block may sit in a dotted module and read into it and back out; a dotted name is read at a top-level form alone, so one inside a module block is refused.','surface-lowering surface-grammar surface-format surface-lsp','corpus/model/modules/module-nesting-and-paths.gandr corpus/model/modules/dotted-names.gandr corpus/pathological/modules/dotted-prefix-clash.gandr corpus/model/modules/dotted-deep.gandr corpus/model/modules/dotted-nested.gandr corpus/pending/pathological/modules/dotted-in-nested.gandr','corpus/model/modules/module-nesting-and-paths.gandr',NULL,'#2828');
INSERT INTO feature VALUES('module-sealing','modules','Opaque ascription (sealing)','modules','implemented','notable',NULL,'A module ascribed a signature hides each abstract component behind a kernel-sealed atom.','surface-lowering kernel-core','corpus/model/modules/sealed-counter.gandr corpus/pathological/modules/sealed-abstraction-leak.gandr','corpus/ledger/features/module-sealing.gandr',NULL,'#260');
INSERT INTO feature VALUES('modules','modules','Modules',NULL,'implemented','ordinary',NULL,'A module groups member declarations, each reached through the module''s name.','surface-lowering','corpus/model/modules/nullary-member.gandr corpus/model/modules/nat-add.gandr','corpus/ledger/features/modules.gandr',NULL,'#5');
INSERT INTO feature VALUES('monadic-blocks','effects','Monadic blocks','relative-monads','planned','notable',NULL,'A block naming a relative monad''s model reads its sequencing as that model''s extension, translated by the algebra translation when it is checked, so a known model leaves no extension call to dispatch and a model parameter specialises by its lambda set.',NULL,NULL,NULL,'#1951',NULL);
INSERT INTO feature VALUES('mutation-testing','workflow','Mutation testing',NULL,'partial','notable',NULL,'A mutation campaign maps each crate''s surviving mutants, and each survivor becomes a witness or an equivalence with its probe; a run tests each mutant under the witnesses that name its item, only over a change, never twice, in a scope capped at 16 GB with no swap, one run a host.','kernel-core core-checker surface-dispatcher surface-driver surface-lsp storage-records surface-layout',NULL,NULL,'#512 #510 #3207','#496 #1535 #1548 #1563 #1566 #1593 #1598 #1609 #1610 #1622 #1639 #3221');
INSERT INTO feature VALUES('mutual-recursion','recursion','Mutual recursion blocks',NULL,'implemented','ordinary',NULL,'A rec { … } block whose members see each other, lowered to one fixpoint over the sum of the members'' domains, admitted once.','core-term core-checker kernel-core','corpus/model/data/rose.gandr','corpus/model/data/rose.gandr','','#580');
INSERT INTO feature VALUES('named-instances','effects','Named effect instances','effect-rows','implemented','uncommon','mainstream languages','A row names an instance of an interface by a label, `-> [a : I] B`, apart from the interface''s default and from every other instance, so one row holds two instances of one interface. A label of a definition''s result row binds a capability of the whole interface at a region binder of its own, after every parameter the definition writes; a call supplies it by name, `f[a = c]`, or omits it and passes the one instance of the interface handled where the call stands, a capability scope''s or a label of the caller''s row, refused as unanswered where none stands and as ambiguous where several do. A label naming a region binder of the telescope, `@[r : Region] (c : Cap {…} at r) -> [r : I] B`, is that binder''s instance, the spelling the printer writes. A label may name a theory''s instance, `-> [st : State with sort S = Integer] B`: its capability is over the theory''s operations at the sorts the entry fixes.','core-term core-checker core-incremental surface-grammar surface-lowering surface-pretty surface-format surface-diagnostics','corpus/model/control/named-instances.gandr corpus/pathological/control/named-instances.gandr corpus/ledger/syntax/f-type.row.labelled.gandr corpus/ledger/syntax/f-type.result.labelled.gandr corpus/ledger/diagnostics/InstanceAmbiguous.gandr corpus/ledger/diagnostics/InstanceUnanswered.gandr','corpus/model/control/named-instances.gandr',NULL,'#2381 #2915');
INSERT INTO feature VALUES('native-emitter','runtime','A native emitter by copy-and-patch',NULL,'implemented','uncommon','dependent provers','One definition of the L machine''s transitions generates the copy-and-patch stencils and the portable executor; every runs item of the corpus executes as patched native code by default under a content-hash cache (GANDR_NATIVE=always|never|cached), native and executor agreeing item for item; macOS arm64 and Linux x86-64 patchers; the hand-written machine retired, the executor the reference; each thread holds its own regions, so two runs on two threads answer as they do on one.','runtime-stencils runtime-emitter','crates/runtime-stencils/tests/agreement.rs crates/runtime-emitter/tests/agreement.rs crates/core-sequent/tests/differential.rs corpus/model crates/surface-dispatcher/src/evaluate.rs',NULL,'#536','#569 #575 #591 #2951');
INSERT INTO feature VALUES('native-lists','types','Native lists and their fold',NULL,'implemented','ordinary',NULL,'A kernel `List` former with nil, cons and a pure annotated fold.','core-term core-checker kernel-core core-sequent','corpus/model/identity/transport-list.gandr','corpus/model/identity/transport-list.gandr',NULL,'b87a65d #1615');
INSERT INTO feature VALUES('native-primitives','types','Native integers, booleans and strings',NULL,'implemented','ordinary',NULL,'Arbitrary-precision integers, booleans and strings with a table of native primitives and a prelude; the normaliser runs none of them, holding a call as a neutral on its operation, so two calls convert exactly when their operations and arguments do.','core-sequent core-nbe core-checker','corpus/model/identity/here-congruence.gandr corpus/model/basics/booleans.gandr corpus/pathological/basics/booleans.gandr','corpus/model/identity/here-congruence.gandr',NULL,'#71 #1885 #2402');
INSERT INTO feature VALUES('nested-operation-laws','rules','Operations nested in a law or a call','rule-coincidence','partial','notable',NULL,'A theory''s call nesting an operation where the cell layer reads a value normalizes over terms under the block''s oriented rules, each operation over an indexed sort carrying the indices its sorting fixes: `orBot(cut, fail)` reaches `cut`, and a call asking one index at two sorts is refused ill sorted. A law nesting an operation over an indexed sort is read with those indices, and the kernel decides the block over the indices it re-derives, so a category''s unit laws join at `comp(id(a), id(a))`. A family''s rule nesting an operation (#1510), and a law whose sides sort only modulo the block''s rules (#522), are still refused `UndescribedMember.NestedOperation`.','kernel-term surface-lowering theory-computads theory-levitation','corpus/model/desc/graded-cut.gandr corpus/model/higher-cells/cat-shape.gandr corpus/surface/higher-cells/cat-shape.gandr corpus/ledger/diagnostics/UndescribedMember.NestedOperation.gandr crates/surface-lowering/src/coincide/tests.rs crates/kernel-term/src/theory_rules/tests.rs','corpus/ledger/features/nested-operation-laws.gandr','#1510','#3012');
INSERT INTO feature VALUES('nested-recursion','recursion','Nested recursion',NULL,'implemented','notable',NULL,'A family inside another family''s arguments, the rose tree: the mutual form through the explicit block, the direct form through a strictly positive parameter (Bush over List) since #618, and a size and a map over the tree through map at the children''s stage check and readmit since #648; both run, a call passing `map` the children''s type as a code.','core-term core-checker kernel-core core-sequent runtime-emitter','corpus/model/data/rose.gandr corpus/pathological/data/rose.gandr','corpus/model/data/rose.gandr',NULL,'#580 #618 #629 #648 #1022 #2722');
INSERT INTO feature VALUES('nested-runs','calculus','Computations where values are read','call-by-push-value','implemented','notable',NULL,'A computation written where a value is read runs there, elaborated to an explicit bind; one its region only returns is elaborated to the computation itself, the returner''s right unit, so a tail''s `return f(x)` and `f(x)` elaborate alike. A lambda written there is suspended, and a type after it reads it as that thunk, so an equivalence''s components are written as bare lambdas. A call written where a function is read runs when it returns one.','core-checker core-nbe kernel-term core-term','corpus/fragment/nested-runs.gandr corpus/model/data/nested-call-sugar.gandr corpus/model/data/sigma-pair.gandr crates/core-nbe/src/eval/tests.rs::a_nested_lambda_forced_and_applied_reduces_2255','corpus/model/data/nested-call-sugar.gandr',NULL,'#276 #2309 #2310 #2335');
INSERT INTO feature VALUES('net-driver','runtime','Streams between processes over `Net`','host-effects','implemented','notable',NULL,'The host interface `Net` dials a peer by its key, accepts a dialer, and transmits, receives and disconnects a stream''s frames; `gandr run` serves it over QUIC through iroh, binding the endpoint on the run''s first network operation at the socket `--net-bind` names under the key `GANDR_NET_SECRET` holds, so two processes on one host exchange a ping, and a handler written in the language answers the same `ping` as a second model of `Net`. An operation the network refuses is declined, and the run is stuck at it.','core-term runtime-net surface-dispatcher surface-driver','corpus/model/distribution/ping.gandr crates/runtime-net/tests/endpoint.rs crates/runtime-net/tests/net.rs crates/surface-dispatcher/tests/run.rs crates/surface-driver/tests/net.rs','corpus/model/distribution/ping.gandr',NULL,'#3242');
INSERT INTO feature VALUES('nix-type-provider','metaprograms','The Nix type provider','tactics-over-goals','planned','notable',NULL,'A splice reads a Nix derivation, as `nix derivation show` prints it, or a `nixpkgs` attribute, as `nix eval --json` prints its `meta` and `outputs`, into a record type the checker admits and a value of it; today the records stand written by hand for `hello`, each beside the JSON its read printed.',NULL,'corpus/model/package/nix-derivation.gandr corpus/model/package/nix-attribute.gandr',NULL,'#2991',NULL);
INSERT INTO feature VALUES('nominal-automata','algorithms','Nominal automata',NULL,'implemented','notable',NULL,'Finite register presentations of nominal word and tree automata over caller-owned names.','theory-nominal-automata','crates/theory-nominal-automata/tests/lib.rs',NULL,NULL,'#69');
INSERT INTO feature VALUES('nominal-data','types','Data types',NULL,'implemented','ordinary',NULL,'Nominal data declarations with constructors and case analysis over them; a constructor field may state its grade, `1` or `ω`, which the family''s description code keeps. Two families of one shape stay distinct: a constructor keeps its own family wherever a type of another is written for it, through an ascription, an alias, a signature or a field, and is carried to the other only along the path an equivalence makes.','core-checker kernel-core surface-lowering','corpus/model/data/data-enum.gandr corpus/model/data/data-maybe.gandr corpus/model/data/data-matched-arms.gandr corpus/surface/data-field-decorations.gandr corpus/ledger/syntax/data-declaration.gandr corpus/pathological/data/field-grade.gandr corpus/model/data/one-shape-families.gandr corpus/pathological/data/nominal-distinctness.gandr corpus/pathological/data/nested-nominal-mismatch.gandr','corpus/model/data/data-enum.gandr',NULL,'b87a65d #2039 #2086');
INSERT INTO feature VALUES('normalization-by-evaluation','conversion','Normalization by evaluation',NULL,'implemented','notable',NULL,'Terms evaluate into a glued semantic domain and read back to normal forms, under a fuel budget that declines rather than refutes.','core-nbe','crates/core-nbe/tests/static_normalization.rs crates/surface-dispatcher/tests/differential.rs',NULL,NULL,'b87a65d #1699');
INSERT INTO feature VALUES('obligation-ledger','checking','The obligation ledger','typed-holes','implemented','notable',NULL,'Every acceptance reports what it owes, so a run that signed for a hole is told from one that owes nothing.','core-checker surface-corpus','corpus/fragment/addressable-obligation.gandr corpus/fragment/blamed-run.gandr','corpus/fragment/addressable-obligation.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('obligation-report','workflow','How the pull request obligations are answered',NULL,'implemented','ordinary',NULL,'Each night `report:obligations` reads the month''s merged pull requests and the unit issues they close through the same section reader the checks use, and writes five tables on one `report: obligations, <month>` issue, the lane as the row and the ISO week as the column: the Concerns marked `no`, the Sources read dispositions, the Readings selected and answered at a site, the Refactoring verdicts and the Ledger rows moved. No figure is a gate; the previous month''s issue closes with its last full update.',NULL,'.config/claims/obligations.json',NULL,NULL,'#3128');
INSERT INTO feature VALUES('one-reader','tooling','One reader',NULL,'partial','ordinary',NULL,'One reader per invocation reads a source once per file identity, buffered below a measured crossover and mapped above it; the formatter reads and writes through it, a mapped source rewritten beside its mapping; the imports, the parse in place, the storage planes and the large-file path come onto it rung by rung.','surface-dispatcher','crates/surface-dispatcher/src/reader.rs',NULL,'#1252','#1346 #1395');
INSERT INTO feature VALUES('open-judgement','sessions','Openness at a world crossing','located-judgements','implemented','uncommon','mainstream languages','A crossing asks two judgements of its type: mobile, authority, and open, representation — the value names no location, so its bytes read the same at every world, in this process or another (migrate-wire). They agree on data and part at a handle `A at w`, mobile always and open exactly when `A` is; a migration''s result or a constant read at another world is refused `NotOpen` when what a handle holds is not open and `Immobile` when a former met directly is not mobile, the report spelling the failing former.','core-checker surface-corpus surface-diagnostics','corpus/model/worlds/open.gandr corpus/pathological/worlds/open.gandr corpus/pathological/worlds/immobile-crossing.gandr','corpus/model/worlds/open.gandr',NULL,'#624 #3200 #3256 #3315');
INSERT INTO feature VALUES('operations','rules','Operations','presented-types','implemented','notable',NULL,'`oper` declares a term former the rules compute, including operations with several outputs.','surface-lowering theory-computads','corpus/model/desc/many-out-op.gandr corpus/model/desc/desc-op-cells.gandr corpus/model/data/indexed-family-operation.gandr','corpus/model/desc/many-out-op.gandr',NULL,'#217 #2979');
INSERT INTO feature VALUES('oracle-modalities','checking','Oracle modalities',NULL,'partial','notable',NULL,'The certificate and elaborator regimes as two oracle disciplines over one substrate, with replay as evaluation. The property grade holds on both sides: a replayed verdict adds no data, so the bridge skips a certificate whose step and instance it has replayed, and a wildcard `_` is a problem the elaborator answers only where the equations force its term, emitting the body with that term written.','kernel-core theory-coherent-resolutions core-checker surface-lowering','crates/kernel-core/tests/replay_laws.rs crates/core-checker/src/bridge/tests.rs::a_skipped_repeat_records_what_its_own_replay_records_528 corpus/model/holes/wildcard.gandr','crate-tests','#313 #528','#1044 #1992');
INSERT INTO feature VALUES('order-maintenance','algorithms','Constant-time order maintenance',NULL,'implemented','ordinary',NULL,'A total order over payload-carrying elements in which any two compare in constant time and an insertion costs constant amortized time: two-level list labeling, consecutive elements sharing a group whose label is a point on a circle, a full group split and the groups after it spread.','theory-order-maintenance','crates/theory-order-maintenance/tests/oracle.rs',NULL,NULL,'b87a65d #2500');
INSERT INTO feature VALUES('ornaments','descriptions','Ornaments','levitated-descriptions','planned','notable',NULL,'Descriptions related by ornaments so a datatype''s structure and its functions transfer to its refinements.',NULL,NULL,NULL,'#312',NULL);
INSERT INTO feature VALUES('package-address','modules','A package''s address','packages','implemented','ordinary',NULL,'A package''s address is the BLAKE3 digest, over its library and then each module by its path, of each item the source itself declares in admission order, as its dotted path and its content key, every inert component of its models and the library''s `dependencies` left out, and then of each dependency''s address, read back through the store from the pointer its `gandr.lock` records, never their aliases or coordinates: an edit to an inert field leaves the address and every other item''s key, and an edit to a content item, its own or a dependency''s, or to what its model asks of the toolchain, moves it; a declaration the lowering refused, or an item whose content holds an unresolved node, leaves the package unaddressed, named by the item, and a pointer the store cannot read back, named by the dependency''s alias. `gandr check` prints it on each reconciled manifest''s line, `manifest: <path>: <what> (address <hex>)`, and `gandr.toml` does not carry it.','surface-dispatcher surface-driver','crates/surface-dispatcher/tests/package.rs::an_inert_edit_leaves_the_address_and_a_content_edit_moves_it_3030 crates/surface-dispatcher/tests/package.rs::every_corpus_package_s_address_ignores_its_inert_fields_3030 crates/surface-driver/tests/cli.rs::a_package_s_manifest_is_written_and_drift_refused_2687 crates/surface-dispatcher/tests/package.rs::a_lock_is_written_once_and_reads_alike_from_anywhere_3072 crates/surface-dispatcher/tests/package.rs::a_pointer_the_store_cannot_answer_leaves_the_dependent_unaddressed_3157','corpus/ledger/features/package-address.gandr',NULL,'#3030 #3069 #3072 #3095 #3175 #3157');
INSERT INTO feature VALUES('package-lock','modules','A package''s lock of its path dependencies','packages','implemented','ordinary',NULL,'A library lists its dependencies as `pub def dependencies : List(Dependency)`, each an alias and a `Coordinate`, a path from the package''s root to a directory rooting another package. `gandr check` resolves each to the package it roots, a dependency''s own dependencies first and its own lock checked against them, commits its identity, its address and its signature key, the digest of the paths its root exports, to the store under the XDG data home, and writes `gandr.lock` at the root when none stands: one line per alias with its path and the pointer the identity commits to, `<digest>:<offset>`. The lock is the same bytes resolved from any directory into any store, a second run and an inert edit to a dependency leave it, and any other difference, or a hand edit, is refused `LockDrift.<alias>` and left as it stands until `gandr lock` writes it again; a pointer the store cannot read back leaves the dependent unaddressed, naming the alias. `import <alias> ;` reads the dependency''s library through the lock, `import <alias>.<path> ;` a module of it; a module path naming no module of the package and no locked dependency refuses each use `UnlockedDependency` at the alias, so `dependencies` runs before the lock is written; two packages depending on each other are refused `DependencyCycle` by their roots.','storage-store surface-dispatcher surface-driver surface-lowering','corpus/model/projects/tools/lib.gandr corpus/model/projects/tools/gandr.lock corpus/ledger/diagnostics/UnlockedDependency.gandr crates/surface-dispatcher/tests/package.rs::a_lock_is_written_once_and_reads_alike_from_anywhere_3072 crates/surface-dispatcher/tests/package.rs::a_dependency_s_content_edit_drifts_the_lock_until_relocked_3072 crates/surface-dispatcher/tests/package.rs::a_dependency_cycle_is_refused_by_its_paths_3072 crates/surface-dispatcher/tests/package.rs::a_pointer_the_store_cannot_answer_leaves_the_dependent_unaddressed_3157 crates/surface-driver/tests/cli.rs::check_writes_a_lock_and_refuses_its_drift_3072 crates/surface-driver/tests/cli.rs::a_package_s_lock_points_into_the_store_the_run_opens_3157 crates/surface-lowering/tests/namespace.rs::a_name_read_through_an_unlocked_alias_is_refused_at_it_3072','corpus/model/projects/tools/lib.gandr',NULL,'#3072 #3095 #3157');
INSERT INTO feature VALUES('package-signature','modules','An import at a signature','packages','implemented','ordinary',NULL,'`import <address> : S ;` writes the theory an importer reads its source at. The source''s interface is its `pub` declarations, each at the type it is written at, inferred and never stated. Each operation and constant of `S`''s model signature names a `pub` declaration of the source whose written type is the member''s derived type: a signature naming fewer members than the source exports settles, and the import binds the signature''s members and no other, qualified or not. A member the source exports no `pub` declaration of is refused `SignatureMismatch.Missing`, one it exports at another type `SignatureMismatch.Sort`, and one the match reads no type for, a declaration with no signature or a sort, a law or a nested model of `S`, `SignatureMismatch.Unstated`; each refuses every declaration of the importing source at the signature, naming the member.','surface-grammar surface-lowering','corpus/ledger/features/package-signature.gandr corpus/model/projects/tools/lib.gandr corpus/ledger/diagnostics/SignatureMismatch.Missing.gandr corpus/ledger/diagnostics/SignatureMismatch.Sort.gandr corpus/ledger/diagnostics/SignatureMismatch.Unstated.gandr crates/surface-lowering/tests/namespace.rs::an_import_at_a_narrower_signature_settles_3098 crates/surface-lowering/tests/namespace.rs::an_import_at_a_wider_signature_refuses_its_source_3098','corpus/ledger/features/package-signature.gandr',NULL,'#3098');
INSERT INTO feature VALUES('package-toolchain','modules','A package''s toolchain constraints','packages','implemented','ordinary',NULL,'A package''s model states what it asks of the toolchain through `std.package`''s `Toolchain`: `gandr`, the least language version as `>= 0.3` or `>= 0.3.1`, `features`, keys of gandr''s features ledger, and `systems`, each `<architecture>-<os>` as `x86_64-linux`, an empty one asking nothing. `gandr check` holds each against the running toolchain, its version, the features ledger the binary was built with, implemented whole or in part, and the host''s system, and refuses one it leaves unmet as `ToolchainUnmet.gandr`, `ToolchainUnmet.feature.<key>` or `ToolchainUnmet.system`, naming the field and both sides, writing no manifest; a `gandr` it cannot read refuses the manifest. A met model is the manifest''s `[toolchain]` table, and a constraint is content, so an edit to it moves the address. `features` and `systems` are each one `,`-separated string until an operation''s port can be a list (#2993).','surface-dispatcher surface-driver','corpus/ledger/features/package-toolchain.gandr corpus/model/projects/workspace.gandr corpus/model/projects/tools/lib.gandr crates/surface-dispatcher/src/package/toolchain.rs::package::toolchain::tests::each_unmet_constraint_is_refused_by_its_clause_3135 crates/surface-dispatcher/tests/package.rs::a_manifest_renders_the_toolchain_its_model_asks_for_3135 crates/surface-dispatcher/tests/package.rs::an_inert_edit_leaves_the_address_and_a_content_edit_moves_it_3030 crates/surface-driver/tests/cli.rs::a_package_s_toolchain_is_met_or_refused_by_its_clause_3135','corpus/ledger/features/package-toolchain.gandr','#2993','#3175');
INSERT INTO feature VALUES('packages','modules','Packages',NULL,'planned','notable',NULL,'A first-class package former, waiting on its first consumer.',NULL,'corpus/model/packages/packages.gandr',NULL,'#533',NULL);
