INSERT INTO feature VALUES('path-operations','identity','Path operations: cong, back and then','identity-types','implemented','notable',NULL,'Congruence, inversion and composition are derived operations whose path types are synthesised from their operands.','core-checker kernel-core','corpus/model/identity/cong-value.gandr corpus/model/identity/back.gandr corpus/model/identity/then.gandr corpus/model/identity/path-operand.gandr','corpus/model/identity/cong-value.gandr',NULL,'#225');
INSERT INTO feature VALUES('paths-in-products','identity','Paths in products and dependent pairs','identity-types','implemented','notable',NULL,'An identification of pairs is a pair of identifications, fibrewise at a dependent pair. A tuple of paths relates two tuples at a product''s identity in both checkers, so two structures are one along their carrier''s path once each component is carried along it.','core-checker kernel-core','corpus/model/data/sigma-pair.gandr corpus/model/identity/structure-identity.gandr','corpus/model/data/sigma-pair.gandr',NULL,'#302 #1338');
INSERT INTO feature VALUES('pattern-matching','types','Nested pattern matching','nominal-data','implemented','ordinary',NULL,'A match''s arms nest constructor and literal patterns, compiled into a decision tree of native eliminations; a match that writes its answer, `case e -> C { … }`, has its tree''s root ascribed it, so it synthesises where nothing states its type.','surface-lowering surface-pretty','corpus/model/data/data-matched-arms.gandr corpus/model/control/eliminator-answers.gandr','corpus/ledger/features/pattern-matching.gandr',NULL,'#2293');
INSERT INTO feature VALUES('perceus-insertion','runtime','Perceus dup, drop and reuse insertion','compiled-runtime','partial','uncommon','mainstream languages','Where a precisely counted runtime duplicates, drops and reuses a value, read off the command IL''s carried supports in one visit per node: contraction dups, weakening drops, arms drop what a sibling uses, many-run bodies dup their captures on entry, and a branch rebuilding its dying scrutinee reuses its cell; a linear resident is never counted. At the emitter a closure captures exactly its support, in support order, the body''s window holding the captures in its first slots; every heap object carries a count word and frees through size lists, dup and drop stencils and the host release worklist in place; every command counts, stacks and handlers, views and folds among them: a waiting frame owns what its block consumes, a capture moves those owners and a replay copies them, a fold''s walk owns its list and an access''s frame its unwind''s names; a held cell is never freed and a view is freed when its access ends; an arm or a nominal branch that rebuilds its dying scrutinee, with nothing between that may capture the window, builds into the scrutinee''s cell when its count is one, a nominal branch of its constructor''s arity running where its match stands; windows live in a region of their own that a body''s return, or its last call, gives its window back to.','core-sequent runtime-emitter runtime-stencils','crates/core-sequent/src/ownership/tests.rs crates/runtime-emitter/src/lower.rs crates/runtime-stencils/tests/count.rs crates/runtime-stencils/tests/support.rs',NULL,'#1175','#1191 #1405 #1413 #1433 #1673 #1701');
INSERT INTO feature VALUES('phase-distinction','modules','The static/dynamic phase distinction','signature-models','implemented','uncommon','mainstream languages','A module signature''s type members sit at the static stage of the two-point order static < dynamic, and a type that depends on a value member is refused by name as a phase dependence — the member and the dynamic member it reached — so a functor is applicative exactly when its static part is a function of its argument''s static part.','surface-lowering','corpus/model/modules/phase.gandr corpus/pathological/modules/phase.gandr','corpus/model/modules/phase.gandr',NULL,'#1097 #2003');
INSERT INTO feature VALUES('places','effects','Access at a place','temporary-access','partial','uncommon','mainstream languages','An access lends one element of a held list at an index read where it stands, the view at the list''s element type; an exclusive view writes the element back at its index and leaves the rest of the list as it was; a held value that is no list is refused by name, and an index naming no element stops the run at the access. The lend stays per held slot until a linear token names its place.','core-term core-checker runtime-emitter surface-lowering','corpus/model/control/accessor-place.gandr corpus/pathological/control/accessor-place.gandr','corpus/ledger/features/places.gandr','#1184','#1196 #2722');
INSERT INTO feature VALUES('postulated-univalence','identity','Univalence as an axiom',NULL,'declined','notable',NULL,'Univalence is computed by certificate replay per stratum, never postulated.',NULL,NULL,NULL,'#1683',NULL);
INSERT INTO feature VALUES('pr-closing-keywords','workflow','Closing keywords only on a body''s head lines',NULL,'implemented','ordinary',NULL,'`pr:open` refuses a closing keyword (close, fix or resolve, in any tense, before `#n` or `owner/name#n`) anywhere but the exact `Closes #n` lines at the head of a pull request body, quoted as code or not: GitHub closes the issue an unquoted one names on merge, and `pr:open` and the claim lifecycle take a quoted one as closed; the commit rules refuse one in a commit message anywhere but its own `Closes #n` line, and `issue:file` notes one in an issue body.',NULL,'.config/claims/opening.json .config/commits/cases.json',NULL,NULL,'#2996 #3003');
INSERT INTO feature VALUES('pr-holds','workflow','A held pull request, and the stack above it, never lands',NULL,'implemented','ordinary',NULL,'A pull request held on purpose is a draft with its reason commented (`pr:hold`); the owner''s hold is `pr:hold --owner`, or `pr:open --hold` from the opening, which also labels it `hold:owner`, and that label holds it even if the draft is taken back. `pr:release` ends either hold. The stacking rule leaves a held pull request out of every stack, and `pr:land`, `pr:watch` and the landing workflow refuse it, and every pull request stacked above it, with one line naming the hold, while the ones below it land.',NULL,'.config/pr-stack/cases.json',NULL,NULL,'#2972 #3261');
INSERT INTO feature VALUES('pr-refactoring','workflow','Every pull request answers whether a refactoring is justified',NULL,'implemented','ordinary',NULL,'A pull request body answers `## Refactoring` with `yes`, `maybe` or `no`, a `yes` or `maybe` with a table of kind, where and observation; `pr:open` refuses a body without it, and `check:refactoring` refuses a `Where` that names no item of the workspace''s rustdoc and no tracked path.',NULL,'.config/claims/opening.json .config/claims/refactoring.json',NULL,NULL,'#3031');
INSERT INTO feature VALUES('presentation-printer','printing','The presentation printer',NULL,'implemented','notable',NULL,'A checked type, a normal form or an elaborated body prints in its surface spelling, and every printed type reads back; a function definition is written whole, `def name(…) -> C { b }`, and a model type as the source writes it, `Model(T) with sort C = A`.','surface-pretty','crates/surface-pretty/tests/goldens.rs',NULL,'#403','#4 #1096 #1307 #1313 #1597 #2276');
INSERT INTO feature VALUES('presentation-rule-decision','rules','The kernel decides a presentation''s rules by replay','rule-coincidence','implemented','uncommon','dependent provers','A theory block''s rules reach the kernel in the Theory value with their orientation and every derived rule beside the peak it joins; at admission and readmission the kernel replays each orientation against the stated terminating order and each derived rule as the joining of its peak, and refuses a presentation that offers a rule it cannot replay, so no presentation is admitted on the producer''s word.','kernel-term kernel-core','crates/surface-corpus/src/kernel_export.rs::kernel_presentation_readmission corpus/model/data/rule-equation.gandr','corpus/model/data/rule-equation.gandr',NULL,'#1139 #1442');
INSERT INTO feature VALUES('presented-circle','identity','The circle as a presented type',NULL,'implemented','unique','dependent provers','`loop : Base <-> Base` declares a free invertible cell, and the paths at the point are the words over it modulo the two cancellations.','surface-lowering core-checker kernel-core','corpus/model/identity/circle.gandr','corpus/model/identity/circle.gandr',NULL,'#372');
INSERT INTO feature VALUES('presented-types','rules','Presented types',NULL,'implemented','notable',NULL,'A data block declares constructors, operations and rules, and conversion at the type compares normal forms under its rules. An indexed family presents no rule over its constructors: such a rule is declined where it is written (`OutOfFragment.Indexed`, #1314), while a rule over one of its operations is kept.','surface-lowering core-checker kernel-core kernel-term','corpus/model/data/arrows.gandr corpus/model/identity/loop-space.gandr corpus/pathological/data/indexed-family-rule-declined.gandr','corpus/model/data/arrows.gandr',NULL,'#349 #2946');
INSERT INTO feature VALUES('product-eta','conversion','Eta for products, records and pairs','normalization-by-evaluation','implemented','notable',NULL,'A tuple, a record or a dependent pair converts with a neutral of its type by the neutral''s projections, in the engine and the kernel alike.','core-nbe kernel-core','corpus/model/data/eta.gandr corpus/pathological/data/eta.gandr','corpus/model/data/eta.gandr',NULL,'#957');
INSERT INTO feature VALUES('products-and-sums','types','N-ary products and sums',NULL,'implemented','ordinary',NULL,'Tuples and tagged sums take any number of components, the unit and the empty sum their nullary cases.','core-term core-checker core-sequent','corpus/model/data/data-either.gandr','corpus/model/data/data-either.gandr','#134','#179');
INSERT INTO feature VALUES('project-manifest','modules','A package, its root and its manifest','packages','partial','ordinary',NULL,'A package is the sources beside its `lib.gandr`, found by walking up from any path in it and rooted above a `src` directory; `check`, `test` and `fmt` given a path in it, or none from inside it, work on the whole package, and `check` writes `gandr.toml` at the root from the library''s `Package` model, a model of `std.package`''s `Gandr.Package`, its `name`, `version`, `authors`, `licence`, `documentation` and `endpoint`, and the modules its sources make, each by its path, then a `[toolchain]` table of its `gandr`, `features` and `systems`, then, when its `spelling` names one, a `[presentation]` table, the table the user''s configuration file writes, rewrites it when the model changes and refuses a hand edit as drift; the line it prints for each manifest carries the package''s address, which the file does not. A language server opened on a package writes in the spelling its manifest''s `[presentation]` table names, over the user''s configuration and under the editor''s own setting. A source names a module of its package by its path, `import text.greet ;` reading the file `text/greet.gandr` beside the library and binding it qualified, `text.greet.greeting`, as a term and as a type; a source in no package is its own root module. A type reached through a module path of three names or more is read through an alias, `import a.b.c as m ;`, until #2874. A list after the address and its alias, `import text.greet (greeting) ;`, binds the names it lists by their own names as well; an unaliased quoted import with a list binds only those, and a listed name its module does not declare, or keeps private, refuses the importing source. A workspace is the packages its `workspace.gandr` names, found by walking up from any directory below it: not a package, it states what its members share as a model of `Gandr.Workspace`, which each member''s library imports, and names its members by a `pub def members : List(String)`, each a directory rooting a package; `check`, `test` and `fmt` given its directory, or none from it outside every package, work on its source and every member, and `check` writes each member''s `gandr.toml` from that member''s own model. `Gandr.Package` and `Gandr.Workspace` share their `version` and their toolchain constraints through the theory `Project` they include, which joins `Versioned` and `Toolchain` once.','surface-dispatcher surface-driver surface-lowering surface-grammar surface-format surface-lsp','corpus/model/projects/workspace.gandr corpus/model/projects/hello/src/lib.gandr corpus/model/projects/hello/src/text/greet.gandr corpus/model/projects/tools/lib.gandr crates/surface-dispatcher/tests/package.rs crates/surface-driver/tests/cli.rs crates/surface-lowering/tests/namespace.rs crates/surface-lsp/src/server.rs::server::tests::a_project_s_spelling_outranks_the_user_s_and_yields_to_the_editor_s_3135 corpus/ledger/features/project-manifest.gandr','corpus/ledger/features/project-manifest.gandr','#2874','#2938 #3069 #3175');
