INSERT INTO feature VALUES('prose-check','workflow','The parsed sentence rules',NULL,'implemented','ordinary',NULL,'`check:prose` parses the corpus comments, the crate READMEs and the rendered diagnostics with spaCy and refuses a passive outside the stated list, a past tense, a stack of four nouns, an `-ing` main verb, a glossary word in another part of speech, and a diagnostic without its what, where and imperative; the committed debt is a ledger keyed by sentence digest. The merge group runs it as a required lane.','workflow-prose','crates/workflow-prose/tests/cli.rs',NULL,'#2919','#3052 #3110');
INSERT INTO feature VALUES('quiet-while-typing','editor','Diagnostics quiet where the author is typing','language-server','implemented','notable',NULL,'Errors are published where the author is not typing, the cascade of a half-written form cut.','surface-lsp','crates/surface-lsp/src/quiet.rs',NULL,NULL,'#297');
INSERT INTO feature VALUES('re-verification','workflow','Re-verification obligations on a pull request','executable-specifications','implemented','notable',NULL,'A change owes re-verification by every specification naming a changed item: the pull request body carries the obligations as boxes the lane fails while unticked; a performance fix owes a lint assessment whose verdict is `could: yes — <lint>, <reference>` or `could: no — <one sentence>`.',NULL,'.config/obligations',NULL,NULL,'#1386');
INSERT INTO feature VALUES('record-depth-subtyping','types','Record depth subtyping','records','planned','ordinary',NULL,'A record whose fields are subtypes stands for the wider record, waiting on the graded thunk former.',NULL,NULL,NULL,'#1680',NULL);
INSERT INTO feature VALUES('record-field','types','Record fields','records','implemented','ordinary',NULL,'`e.l` reads the field `l` off the record `e` is, whether a type is written for the record or not; a field of a field runs the inner projection and reads the record it returns, and a label the record lacks or a value of another shape is refused at the projection.','surface-lowering core-checker','corpus/model/records/record-field.gandr corpus/model/records/nested-record-update.gandr corpus/ledger/syntax/projection-expression.gandr corpus/pathological/records/record-field-absent.gandr corpus/pathological/records/deep-record-update-cost.gandr corpus/pathological/modules/module-shadowed-builtin.gandr','corpus/model/records/record-field.gandr',NULL,'#2192');
INSERT INTO feature VALUES('record-plane','storage','The authenticated record plane',NULL,'implemented','notable',NULL,'Ordered records in content-defined Merkle trees, with membership, absence and range proofs checked against a root alone.','storage-records','crates/storage-records/tests/membership.rs crates/storage-records/tests/absence.rs crates/storage-records/tests/range.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('record-update','types','Record update','records','implemented','ordinary',NULL,'`#{b | l = a, …}` is the base''s record with each written field at its written type — a label the base lacks extends it, one at another type retypes it — and the base''s other fields kept, each read off the base; a computation written as the base runs first, and a base of another shape is refused at the base. Written in a type, an update stands for the record it builds, an update of an update keeping the inner record''s own fields, so the type prints as that record and reads back.','surface-lowering core-checker core-term','corpus/model/records/record-update.gandr corpus/model/records/record-extend.gandr corpus/model/records/record-update-field-retype.gandr corpus/model/records/record-update-of-a-call.gandr corpus/model/records/nested-record-update.gandr corpus/model/records/value-semantics-no-aliasing.gandr corpus/model/records/record-update-in-a-type.gandr corpus/pathological/records/record-update-non-record.gandr corpus/pathological/records/record-update-stale-type.gandr corpus/pathological/records/shared-then-updated.gandr corpus/pathological/records/wide-record-update.gandr corpus/pathological/records/deep-record-update-cost.gandr crates/surface-dispatcher/src/typed.rs','corpus/model/records/record-extend.gandr corpus/model/records/record-update-field-retype.gandr',NULL,'#2167 #2192 #2239');
INSERT INTO feature VALUES('record-width-subtyping','types','Record width subtyping','records','implemented','ordinary',NULL,'A record with more labels stands where one with fewer is expected, the empty record the top.','core-checker','crates/core-checker/tests/native_formers.rs','corpus/ledger/features/record-width-subtyping.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('records','types','Structural records',NULL,'implemented','ordinary',NULL,'Labelled records with projection, checked structurally and given a command-IL image.','core-checker core-sequent','corpus/model/data/data-record.gandr','corpus/model/data/data-record.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('recursive-data','recursion','Recursive data types',NULL,'implemented','ordinary',NULL,'A data declaration names its own family in strictly positive fields, with eliminators derived for it.','core-checker kernel-core','corpus/model/data/recursive-lists.gandr','corpus/model/data/recursive-lists.gandr',NULL,'#95');
INSERT INTO feature VALUES('refactor-issues','workflow','A merged refactoring verdict files its issue','pr-refactoring','implemented','ordinary',NULL,'When a pull request merges, its seat''s `pr:watch` runs `refactor:file`: a `yes` or `maybe` `## Refactoring` verdict with rows becomes a `kind:refactor` issue labelled `status:unsectioned` under the unit''s epic (the area and epic of the issue the pull request closes, else of the issue its branch names), its table under `## Observation` and a `from:` line, or, for a `maybe` whose `Where` an open refactor issue observes, joins that issue; the coordinator is paged, the seat that claims the issue writes its sections, and a second run files nothing.',NULL,'.config/claims/filing.json',NULL,NULL,'#3060 #3103 #3140');
INSERT INTO feature VALUES('referent-reverse-index','editor','The reverse referent index','definition','implemented','ordinary',NULL,'For each declared name or binder, every use referring to it, read off the type table''s referent index once per held text; serves highlight, references and a binder''s rename.','surface-dispatcher','crates/surface-dispatcher/src/typed/referent.rs',NULL,NULL,'#856');
INSERT INTO feature VALUES('reflected-site','identity','The reflected site','univalence-theorem','planned','unique','dependent provers','Shapes, degrees, corollas and the Segal condition as gandr data, the virtual double category formers at the surface.',NULL,NULL,NULL,'#312',NULL);
INSERT INTO feature VALUES('reflexivity','identity','Reflexivity (here)','identity-types','implemented','notable',NULL,'`here(a)` is the identification of an element with itself, two reflexivities converting by their points, under a presented type''s rules too. An endpoint that applies the function a pure call returns is the bind over that call applying what it binds, in the engine and the kernel alike.','core-checker core-nbe kernel-core','corpus/model/identity/here-congruence.gandr corpus/pathological/identity/here-congruence.gandr corpus/model/identity/nested-calls.gandr','corpus/model/identity/here-congruence.gandr',NULL,'#225 #1733 #2346');
INSERT INTO feature VALUES('refusal-classes','checking','Refusals classified by whose fact they are',NULL,'implemented','notable',NULL,'Every refusal is classed as a user absence, an unimplemented feature naming its tracking issue, malformed source or an engine fault, and names its rule; an unimplemented refusal carries its issue in every face — the terminal note, the JSON image and the editor diagnostic.','core-term core-checker surface-lowering surface-render-terminal','corpus/fragment/type-mismatch.gandr corpus/fragment/shape-refusal.gandr crates/surface-render-terminal/tests/golden/unimplemented.txt','corpus/fragment/type-mismatch.gandr',NULL,'b87a65d #1345 #1355');
INSERT INTO feature VALUES('region-indices','effects','Region indices (a value kept in a scope''s or a hold''s region)','temporary-access','implemented','uncommon','mainstream languages','A value kept in a region, `A at c` for a capability scope or `A at s` for a hold, lives as long as the scope or the hold rather than the access that lent it: a shared view kept there keeps its held value frozen until the region ends, a value kept in a region is bound again at the type that keeps it and never leaves the region, a fork whose protocol carries a value kept in a region is refused since no region bounds a forked peer, and a region is a static index ordered by outlives and erased before anything runs. A definition abstracts over a region, `def f @[r : Region] (k : A at r)`, each call placing `r` at the shortest region its arguments show; it cannot keep what it is lent past `r`, and a region binder named as a value is refused. Such a function commutes with the outlives widening: run at an outer region with its answer widened, it is one function with itself run at an inner region after its argument is widened, a path the conversion checks. A diagnostic spells a type kept at a scope, a hold or a binder by the name the source writes for it.','core-term core-checker core-incremental core-unify surface-lowering surface-pretty surface-diagnostics surface-dispatcher','corpus/model/control/kept-view.gandr corpus/pathological/control/kept-view.gandr corpus/pathological/completion/region-ended.gandr corpus/model/strings/views.gandr corpus/pathological/strings/views.gandr corpus/model/regions/lent.gandr corpus/model/regions/passed.gandr corpus/pathological/regions/stashed.gandr corpus/pathological/regions/named.gandr corpus/pathological/regions/outlived.gandr corpus/model/regions/held-within.gandr corpus/pathological/regions/held-within.gandr corpus/model/regions/natural.gandr corpus/pathological/regions/natural.gandr crates/surface-diagnostics/tests/diagnostics.rs::a_mismatch_between_two_region_binders_names_both_2138','corpus/model/control/kept-view.gandr','#2139','#1244 #1256 #1260 #1454 #1529 #2146 #2147');
INSERT INTO feature VALUES('relative-monads','effects','Monads relative to the shift',NULL,'partial','uncommon','mainstream languages','A monad relative to `-F`, a unit and an extension over a family of computation types, declared as a theory with its laws as rules: each model proves them where it is sealed, completion orients them for fusion, and the extension''s continuation is a host thunk. The host half checks today: the carrier declared as a theory''s sort into the computation types, `sort T(A : Type) : Type[-]`, which the option monad''s `-F Maybe(a)` models, the option monad''s operations and code polymorphic in the carrier; of the laws, the left and right unit check as rules, and associativity waits on critical pairs between second-order rules (#2116).','theory-levitation surface-lowering kernel-term','corpus/model/desc/relative-monad.gandr corpus/pathological/desc/relative-monad.gandr','corpus/ledger/features/relative-monads.gandr','#1951 #2116','#2321 #2722 #3150');
INSERT INTO feature VALUES('repl','tooling','The read-evaluate loop','interactive-session','implemented','notable',NULL,'`gandr repl` submits each complete form and answers in a transcript with types, goals and live match analysis.','surface-repl','crates/surface-repl/tests/repl_loop.rs crates/surface-repl/tests/live_match.rs',NULL,NULL,'53a4804');
INSERT INTO feature VALUES('rich-reports','diagnostics','Rich diagnostic reports','diagnostics-model','implemented','notable',NULL,'A report leads with a plain message, then names the judgements the refusal stood inside, the types it compares and every location it involves.','surface-diagnostics surface-render-terminal','crates/surface-render-terminal/tests/render.rs',NULL,'#115','#165');
INSERT INTO feature VALUES('ride','directed','Covariant transport (ride)','directed-paths','implemented','notable',NULL,'`ride(P, f, v)` moves a value forward along a flow through a covariant family, and a contravariant motive is refused by name.','core-checker core-term kernel-core','corpus/model/identity/flow-migration.gandr corpus/pathological/identity/flow-symmetry.gandr corpus/model/identity/flow-large.gandr','corpus/model/identity/flow-migration.gandr',NULL,'#301 #1852');
INSERT INTO feature VALUES('row-kind','types','Rows, one kind of labelled descriptions',NULL,'implemented','uncommon','mainstream languages','A row is a finite map from labels to entries, each label once and in no order of its own: a label written twice is refused, two rows defining one label apart do not join, and two rows listing the same entries in different orders are one row. The returner''s effect row is its first reading.','core-term surface-lowering','corpus/model/control/effect-rows.gandr corpus/pathological/control/effect-rows.gandr','corpus/model/control/effect-rows.gandr','#2273','#2305 #2329');
INSERT INTO feature VALUES('row-polymorphism','effects','Row-polymorphic effects','effect-rows','implemented','uncommon','mainstream languages','A returner''s row stays open through a row variable, an implicit of the kind `Row`, written `-F [I, … | r] A` or `-F [r] A`: an omitted `r` is solved at each call by the row equation, so one definition is used under every row holding its interfaces, and a handler takes `[I | r]` to `[r]`, forwarding the rest. A call whose row nothing reads, or two open rows each holding an interface the other lacks, is refused naming the slot `f[r = …]`.','core-term core-unify core-checker core-incremental surface-grammar surface-lowering surface-pretty','corpus/model/control/row-variable.gandr corpus/pathological/control/row-variable.gandr','corpus/model/control/row-variable.gandr','#2319','#2329');
INSERT INTO feature VALUES('rule-coincidence','rules','Rule coincidence at checks','presented-types','implemented','notable',NULL,'A block''s rules must join every critical pair under a terminating order, or the block is refused naming the diverging pair.','surface-dispatcher theory-coherent-resolutions surface-lowering theory-levitation','corpus/model/desc/rules-overlap-joinable.gandr corpus/pathological/desc/rules-diverge.gandr crates/surface-corpus/src/kernel_export.rs corpus/model/identity/group-laws.gandr corpus/model/desc/rules-completed.gandr corpus/pathological/desc/rules-uncompleted.gandr crates/kernel-core/src/ruled/tests.rs corpus/pathological/desc/second-order-rules.gandr','corpus/model/desc/rules-overlap-joinable.gandr',NULL,'#331 #1040 #1048 #1071 #1139 #1442 #1653 #1661 #1672 #1678 #1706');
INSERT INTO feature VALUES('rule-completion','rules','Rule completion','rule-coincidence','implemented','ordinary',NULL,'A block''s critical pair that parts at a non-value is completed by the rule it derives, oriented by the block''s path order and certified by the pair''s two paths; only a join of two values is refused. A `data` block''s derived rules reach the kernel with the written ones. A derived rule that embeds the rule derived from one of its pair''s cells, wrapping it at one point where no held rule rewrites a further wrapping, is refused `RulesNeverComplete` naming both rounds: every round would derive a longer rule.','surface-lowering theory-levitation theory-coherent-resolutions theory-computads','corpus/model/identity/group-laws.gandr corpus/model/desc/rules-completed.gandr corpus/pathological/desc/rules-uncompleted.gandr corpus/pathological/desc/rules-never-complete.gandr','corpus/model/identity/group-laws.gandr',NULL,'#1048 #1139 #1635 #1653 #1661 #1672 #1678 #1706');
INSERT INTO feature VALUES('rule-conditions','rules','Conditions on a rule','rule-coincidence','partial','notable',NULL,'A rule''s condition is read over its variables: where a port takes an atom, each variable is a hole over the atoms abstracted above it that it may name, a freshness condition `where a # t` or a right side standing outside the abstraction narrowing it, so two rules'' overlap is decided in the second-order reading under the condition it composes: the pair joins there, parts there and is refused `RulesOverlapCondition`, or has no instance the conditions admit and holds without a peak. A rule stated under a row of theories, `under [T, … | r]` open or `under [T, …]` closed, fires only in the rows it describes: two such rules'' overlap is decided in the rows both describe, the meet of their rows, by the rules firing in each of them, and two rows sharing none owe no join; a theory a row names that no block presents, or one named twice, is refused by name. A model of a theory owes a law under a row in every row (#2466).','kernel-term surface-lowering theory-levitation theory-computads surface-grammar','corpus/model/desc/atom-occurrence.gandr corpus/pathological/desc/atom-occurrence.gandr corpus/ledger/diagnostics/RulesOverlapCondition.gandr corpus/model/effects/rows.gandr corpus/pathological/effects/rows.gandr crates/kernel-term/src/theory_rules/tests.rs crates/surface-lowering/src/coincide/tests.rs crates/surface-lowering/src/description/theory/tests.rs','corpus/ledger/features/rule-conditions.gandr','#2466','#2481 #2497 #2722');
INSERT INTO feature VALUES('rule-equations','rules','Rules as equations (<=>)','presented-types','implemented','notable',NULL,'`rule l <=> r` states an equation and the path order chooses its direction, `==>` pinning one. An effect theory''s rule, as oriented, also rewrites the subject of a scope over the theory before it runs (`effect-theories`).','surface-lowering','corpus/model/data/rule-equation.gandr corpus/pathological/data/rule-equation-unoriented.gandr corpus/model/effects/state-laws.gandr','corpus/ledger/features/rule-equations.gandr',NULL,'#382 #2868');
INSERT INTO feature VALUES('rule-respect','rules','Case analysis respects rules','presented-types','implemented','notable',NULL,'A case over a presented type must give equal answers on both sides of every rule, the kernel re-deriving the check; a case at a structural fixpoint''s root, past any parameters after the one it recurses on, is read as the fixpoint, its own calls unfolded as deep as the rule''s sides hold constructors.','core-checker kernel-core','corpus/model/identity/set-fold.gandr corpus/pathological/data/nested-call-tells-apart.gandr corpus/model/identity/state-passing.gandr corpus/pathological/identity/state-passing.gandr','corpus/model/identity/state-passing.gandr','#357','#359 #2849');
INSERT INTO feature VALUES('run-entry','runtime','Program entry',NULL,'implemented','ordinary',NULL,'A source declaring a top-level `main` is a program: `gandr run` runs `main`, given the arguments after the path as a `List(String)` when it takes them, and exits with the integer it returns or passes to `Proc.exit`, or with 0 when it returns the unit; a `main` of any other type is refused by name. A source declaring no `main` runs nothing, its last declaration included: `gandr run` refuses it, naming `def main` and pointing at `gandr check` and `gandr test`, and an expression at its top level is refused `OutOfFragment.TopLevel`. A run that reaches a hole stops there and names it where the source writes it.','surface-lowering surface-dispatcher surface-driver core-sequent','corpus/model/programs/entry.gandr corpus/model/programs/draft.gandr corpus/model/control/program-exit.gandr corpus/model/effects/hello.gandr corpus/ledger/diagnostics/EntryType.gandr corpus/ledger/diagnostics/OutOfFragment.TopLevel.gandr crates/surface-driver/tests/cli.rs::a_script_with_no_program_is_refused','corpus/model/programs/entry.gandr',NULL,'#2069 #2080 #2297');
INSERT INTO feature VALUES('run-prefixes','sessions','Recorded prefixes (Prefix(S))','session-types','implemented','notable',NULL,'A record of the moves a protocol admits so far, open or complete, is a `Prefix(S)`, checked by the monitor that admits runs, a move the protocol refuses refused by name; `Run(S)` holds only complete runs, and no prefix converts to one. An open prefix rides forward along a session flow and stays open, by conversion and on the machine, a move the flow''s target refuses refused at that move.','core-term core-checker core-session surface-lowering','corpus/model/sessions/seat-prefix.gandr corpus/pathological/sessions/seat-prefix.gandr crates/core-checker/src/flow/tests.rs::a_prefix_admits_an_open_run_and_refuses_by_move corpus/model/sessions/seat-prefix-evolution.gandr corpus/pathological/sessions/seat-prefix-evolution.gandr crates/core-checker/src/flow/tests.rs::a_prefix_rides_forward_and_refuses_by_move','corpus/model/sessions/seat-prefix.gandr',NULL,'#1923 #1925');
INSERT INTO feature VALUES('run-targets','runtime','Run targets','running-programs','declined','ordinary',NULL,'Retired by #2572: a source''s final expression no longer runs. Every expression the parser did not repair is refused where it stands at a source''s top level, `OutOfFragment.TopLevel`, the last one too, and `gandr run` runs the `main` a source declares (run-entry), refusing a source that declares none.',NULL,NULL,NULL,'#2572 #2846',NULL);
INSERT INTO feature VALUES('running-programs','runtime','Running programs',NULL,'implemented','ordinary',NULL,'`gandr run` checks a source, focuses it into the command IL, runs the `main` it declares natively or on the portable executor and reads the answer back.','surface-dispatcher core-sequent runtime-emitter','corpus/model/modules/functor-pair.gandr','corpus/model/modules/functor-pair.gandr',NULL,'#3');
INSERT INTO feature VALUES('runs-beside-refusal','corpus','A source that runs while refused as total','corpus-expectations','implemented','ordinary',NULL,'An attribute block that states both runs("…") and refuses("…") settles only when both hold: the program runs to the stated value and the checker refuses it by the named refusal, so a loop with no inferable measure is witnessed running and refused as unbounded in one source.','surface-corpus surface-dispatcher','corpus/pathological/control/accessor-escape.gandr',NULL,NULL,'#1153');
INSERT INTO feature VALUES('runtime-lam','runtime','The runtime''s regions as a LAM','compiled-runtime','partial','notable',NULL,'A run''s values live in a heap region and its continuations in a frame region, each allocated at its bound once per thread, and a run that would pass a bound declines exhausted. The regions are a location-addressable memory in the sense of Rainey et al. (LoCalMem, ICFP 2026): a match reads a value where it stands, a copy is its address and one owner more, and an outcome leaves for the caller''s store each object once, sharing kept; the store it reaches appends, never changes a value at its address and never recycles one. The regions depart from it where a freed block is reused and where a block one owner holds is rebuilt in place, the rebuild the exclusivity conjecture says answers as the copy: an update through an exclusive view answers as its copy on both tiers, and a copy taken before it keeps its value. The update rebuilt in the held value''s own block, which takes a fresh block because the held cell keeps its owner while the view is out, is owed (#3205).','runtime-emitter core-sequent','corpus/ledger/features/runtime-lam.gandr corpus/model/runtime/exclusive-update.gandr crates/runtime-emitter/src/run.rs crates/runtime-stencils/tests/count.rs crates/runtime-stencils/tests/exits.rs','corpus/ledger/features/runtime-lam.gandr','#3205','#3397');
INSERT INTO feature VALUES('rust-default-layout','layouts','Rust''s default layout as a program',NULL,'partial','uncommon','mainstream languages','rustc''s layout of a `repr(Rust)` type is a gandr program over the type''s code, `std.layout`, after `rustc_abi`''s `univariant` and `layout_of_enum`: a struct''s fields sorted by alignment, its niche toward the start or, when that leaves the niche nearer the middle, the end; an enum''s niche-filled and tagged layouts, the tag widened to the smallest first-field alignment, the smaller kept, then the larger niche, then the tagged. Checked against `rustc -Zprint-type-sizes` on eleven structs and enums over unsigned and signed integer, `bool` and reference fields, it agrees on every size, alignment, offset and discriminant; rustc stays the authority on a Rust type''s layout. A field that is itself an aggregate waits for levitated codes (#2343), and a niche beyond `bool`''s and a reference''s needs a theory of the target.',NULL,'library/std/src/layout.gandr corpus/model/layouts/rust-default.gandr corpus/pathological/layouts/rust-default.gandr','corpus/ledger/features/rust-default-layout.gandr','#2343','#3009 #3099 #3118');
INSERT INTO feature VALUES('rust-semantics-thir','runtime','Rust semantics at THIR','foreign-calls','partial','uncommon','dependent provers','A Rust function''s THIR is data and its dynamics a weakest-precondition calculus over it (Farka et al., Corten, 2026): the calculus is the specification monad of THIR''s control effect, one postcondition for a value and one for a `return`, a function''s guard its handler. Corten''s `example`, an early `return` inside `identity`''s argument, meets its specification at every value and every postcondition given `identity`''s, a fold computing each precondition and the kernel replaying it. The axioms are also a theory''s second-order rules over THIR''s nodes, which the checker orients and joins and an inspected call fires: `example`''s guarded body at false normalizes to its postcondition at zero. Corten''s buddy allocator''s `pop` meets its free-list specification over a value forest: a read or a write through a place is a value with its equation to the place, the list''s links are equations on block reads, and the proof takes 204 lines against Corten''s 2800 for the whole allocator. THIR is written by hand: no `rustc` driver stages it yet.',NULL,'corpus/model/interop/thir/example.gandr corpus/pathological/interop/thir/example.gandr corpus/model/interop/thir/buddy-pop.gandr corpus/pathological/interop/thir/buddy-pop.gandr','corpus/ledger/features/rust-semantics-thir.gandr','#327','#2978 #2988 #3127');
INSERT INTO feature VALUES('schema-migration','storage','Schema migration by pullback','acset-store','implemented','uncommon','mainstream languages','A map between schemas pulls a store back along it, keys and counters kept.','storage-schema','crates/storage-schema/tests/migrate.rs',NULL,NULL,'#348');
INSERT INTO feature VALUES('sealed-types','kernel','Sealed abstract types',NULL,'implemented','notable',NULL,'An abstract type''s representation is visible inside its minting admission and hidden from every later declaration, replay re-deriving both.','kernel-core','corpus/model/modules/sealed-counter.gandr','corpus/model/modules/sealed-counter.gandr',NULL,'#245');
INSERT INTO feature VALUES('search-as-query','rewriting','Homomorphism search as a query',NULL,'planned','notable',NULL,'Pattern search over the store answered as conjunctive-query evaluation.',NULL,NULL,NULL,'#314',NULL);
INSERT INTO feature VALUES('second-order-rules','rules','Second-order rules','rule-coincidence','partial','notable',NULL,'A rule over a binding operation applies a bound variable to one argument per variable it binds (`t(u)`, read as its instantiation), abstracts the variables a port binds (`bind x . t`, named at a port of their sort) and, on a left side, applies a bound variable to the variables abstracted above it as a pattern its right side instantiates; the abstraction at a `pi+` port is the port''s binding field, kept in the Theory value as `Bind` and its variable as `Bvar`, apart from an atom''s abstraction, so a variable crossing it needs no freshness condition and a condition naming its variable is refused as naming no atom; a rule writes one binder per port, two at one port waiting on the grammar (#2347). It is sorted at its binders by check_desc and oriented by HORPO''s metavariable case read up to η, an instantiation at a value of a sort no operation returns needing no cover. Its critical pairs are found by pattern unification and joined in the second-order reading, where a rule''s variable stands for a term over the names its pattern applies it to and an instance substitutes for them; a pair that parts is refused, never completed (#2361), in the producer and the kernel alike. An inspected call of a block holding such a rule is normalized in the kernel''s second-order reading, each rule stated under no row fired by matching its pattern and substituting its instance, a call''s `bind x . t` at a binding port read as the port''s field; the model derivation states the binding operation (`signature-models`) but not yet a law relating a term at its port (#1324).','theory-levitation theory-computads surface-lowering kernel-term','corpus/model/desc/second-order-rules.gandr corpus/pathological/desc/second-order-rules.gandr corpus/model/desc/relative-monad.gandr corpus/pathological/desc/relative-monad.gandr corpus/model/effects/state.gandr corpus/pathological/effects/state.gandr corpus/model/desc/binding-field.gandr corpus/pathological/desc/binding-field.gandr','corpus/ledger/features/second-order-rules.gandr','#1324 #1326 #2328 #2347 #2361','#1442 #2321 #2324 #2350 #2367 #2722 #2988');
INSERT INTO feature VALUES('semantic-highlighting','editor','Semantic highlighting','language-server','implemented','ordinary',NULL,'Every mold of the grammar carries a highlight role, served as semantic tokens and used to colour hovers.','surface-grammar surface-lsp','crates/surface-grammar/tests/highlight.rs',NULL,NULL,'c9cd0a4 #1596');
INSERT INTO feature VALUES('sequent-machine','machine','The focused command IL and its machine',NULL,'implemented','notable',NULL,'A core program is focused into a command language of producers and consumers and run on the L machine the stencils define, natively or on the portable executor, with tail calls holding no frame.','core-sequent runtime-stencils runtime-emitter','crates/core-sequent/tests/differential.rs',NULL,NULL,'b87a65d');
INSERT INTO feature VALUES('session-identity','sessions','Session identity (Path_U and Flow_U at sessions)','session-types','partial','unique','dependent provers','A protocol''s evolution is a certified path or flow between session types, and a recorded run is transported along it. A recorded run carried along a path between its payload types moves each payload its protocol reads at the path and keeps every move, by conversion and on the machine, which runs the transport as a match on the run''s moves; the machine refuses a run of a recursive session by name. Two protocols whose payload types differ are one type once each differing payload pair is paid with a path, bisim(A, B, p), the paths elaborated to the native certificates the kernel checks; a closed univalence pays a pair as itself, its record checked at the native identity the pair owes, and one over a record a parameter binds is refused.','core-session core-checker core-nbe core-sequent kernel-core','corpus/model/sessions/seat-evolution.gandr corpus/model/sessions/run-transport.gandr corpus/model/sessions/payload-paths.gandr corpus/model/sessions/payload-univalence.gandr corpus/pathological/sessions/reserved.gandr corpus/pathological/sessions/session-payloads-unpaid.gandr corpus/pathological/sessions/payload-univalence.gandr crates/core-sequent/tests/run.rs','corpus/ledger/features/session-identity.gandr','#1734','#295 #1912 #2722');
INSERT INTO feature VALUES('session-machine','sessions','Sessions run on the run''s scheduler','session-types','implemented','notable',NULL,'A fork, a send, a receive, a selection, an offer and a close run on one cooperative, deterministic scheduler the run holds, on its own thread and on both tiers. A channel keeps one queue per direction: a send or a selection never waits, and a receive or an offer with nothing sent parks its task''s frames until its peer sends. A fork''s parent runs on and its child joins the back of the ready queue; the run answers once every task has ended, and a run whose tasks all wait is stuck as a deadlock naming each waiting action.','core-sequent runtime-emitter','corpus/model/sessions/seat-exchange.gandr corpus/model/sessions/dropped.gandr corpus/model/sessions/receive-payload.gandr corpus/model/moves/moved-through.gandr corpus/model/moves/moved-to-closer.gandr corpus/pathological/drop/cancelled-peer.gandr crates/runtime-emitter/tests/sessions.rs','corpus/model/sessions/seat-exchange.gandr',NULL,'#3324');
INSERT INTO feature VALUES('session-readmission','sessions','Sessions replayed by the kernel','session-types','implemented','notable',NULL,'Readmission erases the session discipline and the kernel replays what a session computes: a session type crosses as the kernel''s session code at the state it stands at, the protocol unfolded there when the state is past its root; a send crosses as its payload returned at the type it was checked at, a select and a close as the unit, a fork as its child and then its parent. A receive crosses as its body reading the received value from an assumption of the value''s type, and an offer as a case on an assumed choice among its arms, each assumption an axiom named in the audit of whatever reads it; an endpoint, sent or received, names no value and needs none.','core-checker','crates/core-checker/src/judgement/session/tests.rs crates/core-checker/src/bridge/tests.rs crates/surface-dispatcher/src/compose.rs corpus/model/sessions/seat-exchange.gandr corpus/model/sessions/receive-payload.gandr','corpus/model/sessions/seat-exchange.gandr',NULL,'#1987 #1319');
INSERT INTO feature VALUES('session-relations','sessions','Session equivalence, subtyping and duality','session-types','implemented','notable',NULL,'Contractive session types are compared by coinductive relation search, each relation exported as a checkable candidate.','core-session','crates/core-session/tests/relations.rs corpus/model/sessions/seat-evolution.gandr','corpus/model/sessions/seat-evolution.gandr',NULL,'#279');
INSERT INTO feature VALUES('session-types','sessions','Binary session types',NULL,'implemented','uncommon','mainstream languages','A channel''s protocol is a type of sends, receives, selections, offers and recursion, its endpoints used linearly. A session type stands as an argument through the type(T) quote; a receive binds its payload linearly, and a channel is delegated as a payload. An endpoint at `end` is closed or dropped, `drop(c)` being the end action `close(c)` writes, and a drop of a live endpoint is refused as the session mismatch it is. An endpoint moved into a call or a closer keeps its protocol under its new name and is spent at the old one, an action after the move refused by name. A forked task exercises the authority its parent hands it and outlives no region. A session program runs on the run''s scheduler (session-machine).','core-session core-checker','corpus/model/sessions/seat-exchange.gandr corpus/pathological/sessions/linearity.gandr corpus/model/sessions/dropped.gandr corpus/model/sessions/receive-payload.gandr corpus/pathological/sessions/protocol.gandr corpus/model/sessions/type-quote.gandr corpus/pathological/sessions/type-quote.gandr corpus/model/completion/buffer-moved.gandr corpus/model/completion/cancel-orders.gandr corpus/model/moves/moved-to-closer.gandr corpus/model/moves/moved-through.gandr corpus/pathological/moves/ corpus/model/tasks/authority.gandr corpus/pathological/tasks/outlived.gandr','corpus/model/sessions/seat-exchange.gandr',NULL,'#279 #1054 #1149 #1242 #1333 #1351 #3324');
