INSERT INTO feature VALUES('soundness-exemplars','workflow','Historic soundness holes refuted as exemplars','executable-specifications','partial','notable',NULL,'A soundness issue of another checker, named in plain text, is re-staged as a pair of corpus sources: the hole''s shape refused in `pathological/soundness/` with the refusal named, and the sound program kept in `model/soundness/`; each pair folds its lesson into the plan or issue it changes.','surface-corpus','corpus/pathological/soundness/rust-164250.gandr corpus/model/soundness/rust-164250.gandr',NULL,'#1492','#1496');
INSERT INTO feature VALUES('specification-combinators','workflow','Specification clause combinators','executable-specifications','implemented','ordinary',NULL,'Bounded checks a specification clause makes of accumulated state: what a sequence gained since a mark, one push, the order around an insertion point.','theory-spec-combinators','crates/theory-spec-combinators/src/lib.rs',NULL,NULL,'#195');
INSERT INTO feature VALUES('specification-cost','workflow','Bounded specification cost','executable-specifications','partial','ordinary',NULL,'Specifications ranked by what they cost the enforcing lane, the quadratic ones made linear.','workflow-spec-cost','crates/workflow-spec-cost/tests/ratio.rs crates/workflow-spec-cost/src/ledger.rs',NULL,'#104','#110');
INSERT INTO feature VALUES('specification-monads','effects','Specification monads','effect-theories','partial','notable',NULL,'A program over state is specified by the predicate transformer its weakest-precondition observation computes, from a postcondition on the answer and the final state, and an initial state, to the precondition there (Maillard et al., ICFP 2019). The observation is a handler of state whose carrier is the transformers, its scope checked as a model of put-get, put-put and get-get; written as a fold of the program''s tree, the normaliser computes a precondition and the kernel replays it, and the increment pairs, in a dependent record, with evidence that its transformer is below its specification at one postcondition and at every postcondition; the stopped program pairs with evidence below the return specification at every postcondition. A specification monad is a theory whose order is a sort indexed by two computations, reflexive, transitive and with a monotone extension. The order named as a definition waits on #2759, a precondition through the scope on #2754, the monad''s laws beside its order on #1510, and get-put on #1934.',NULL,'corpus/model/specification/state-wp.gandr corpus/pathological/specification/state-wp.gandr corpus/model/specification/tree-state-wp.gandr corpus/pathological/specification/tree-state-wp.gandr corpus/model/specification/specification-monad.gandr corpus/pathological/specification/specification-monad.gandr corpus/model/effects/state.gandr corpus/pathological/effects/state.gandr','corpus/ledger/features/specification-monads.gandr','#2759 #2754 #1510','#2757 #2768 #2777 #2814');
INSERT INTO feature VALUES('spinal-duplication','conversion','Spinal duplication in the conversion engine','engine-sharing','partial','uncommon','dependent provers','Duplicating a shared abstraction under the spinal stance copies its spine, the paths from its binder to the binder''s occurrences, and shares each rib, a maximal subterm of its body that does not read the binder, so a rib is evaluated once across every application, and the duplicate erases to the term the copying stance evaluates. The stance installs only bound to a sink that records the conversion trace, and no checker path installs it.','core-nbe','crates/core-nbe/tests/full_laziness.rs crates/core-nbe/tests/duplication.rs corpus/ledger/features/spinal-duplication.gandr','corpus/ledger/features/spinal-duplication.gandr','#2801','#2942');
INSERT INTO feature VALUES('stage-typing','recursion','Stage-typed descent','structural-recursion','implemented','notable',NULL,'A marked call checks where its argument stands below the stage of the parameter it descends on, in both checkers; the accessibility rule stages every placed occurrence of a stratified family.','core-checker kernel-core','corpus/fragment/stage-not-below.gandr corpus/model/data/stratified.gandr corpus/pathological/data/curry.gandr','corpus/model/data/stratified.gandr',NULL,'#458 #618');
INSERT INTO feature VALUES('stall-detector','workflow','Stalls paged by name and escalated to a decision',NULL,'implemented','ordinary',NULL,'`stall:watch` reads the open pull requests every five minutes for a green root left unqueued, an ejected, piled-up, red, conflicting or base-blocked pull request, or a merged pull request''s refactoring verdict no issue was filed for, and pages each finding to its lane''s seat and the coordinator at once, by name, the page script resolving the name at page time; a finding standing ten minutes after its page puts a stall comment and `status:stalled` on the pull request and pages the coordinator again every ten minutes until it clears, and a seat with no live block is paged to the coordinator. A pull request held on purpose is a draft with its reason (`pr:hold`), which no stall counts and no landing lands.',NULL,'.config/stall/cases.json',NULL,NULL,'#2981');
INSERT INTO feature VALUES('stated-laws','modules','Laws a model proves or admits','modules','implemented','uncommon','mainstream languages','A theory states a law as the path type it is, `law sym : (a : C, b : C) => Path(Bool, eq(a, b), eq(b, a));`, binders first and hypotheses after them, an equation no rule could orient. A model proves it by a definition at that type or, at a host primitive carrier, admits it, `law sym admitted ;`: the admission crosses as the axiom it is, settles `checks` and is listed in the report''s audit. A law neither proved nor admitted is refused `UnprovenLaw` by its name, and an admission at a carrier the source writes `UnprovenLaw.Admitted`.','surface-lowering surface-corpus','corpus/model/modules/model-laws.gandr corpus/pathological/modules/model-laws.gandr','corpus/model/modules/model-laws.gandr',NULL,'#2356');
INSERT INTO feature VALUES('std-module-map','modules','The standard library''s module map','packages','implemented','ordinary',NULL,'`library/std/README.md` maps each module of `std`: what it holds, the corpus sources it absorbs, the host seam it stands on with the `cap-std` type it mirrors, and whether it is landed, reserved or declined; host access is by capability, the ambient authority entering as `main`''s parameter.',NULL,'library/std/README.md','corpus/model/projects/hello/src/lib.gandr','#628','#2938 #3099');
INSERT INTO feature VALUES('std-package','modules','The standard library''s manifest theories','packages','partial','ordinary',NULL,'`std.package` states the theories a manifest is read from: `Versioned` and `Toolchain`, which `Project` joins, `Presentation`, `Gandr.Package`, including `Project` and `Presentation`, and `Gandr.Workspace`, including `Project`, which a library''s and a workspace''s models are of, and `Gandr.Module`, which no source models yet; and the types a library''s `dependencies` lists, `Dependency`, an alias and a `Coordinate`, and `Coordinate`, a `Path` from the package''s root; every field of `Gandr.Package` but what it asks of the toolchain, its `name`, `version`, `authors`, `licence`, `documentation`, `endpoint` and `spelling`, is inert, read only by the manifest step and another inert field, while `gandr`, `features` and `systems` are content; `authors`, `features` and `systems` are each one string, and `dependencies` a definition of the library''s own, until an operation''s port can be a list (#2993); a source imports it by the relative path to its source, from under any root, since an import reaches a source under the strict root from every root.','surface-dispatcher surface-lowering','corpus/model/projects/hello/src/lib.gandr corpus/model/projects/workspace.gandr corpus/model/projects/tools/lib.gandr crates/surface-lowering/tests/namespace.rs::the_standard_package_theory_is_read_by_its_path_2767 crates/surface-dispatcher/src/component.rs::component::tests::a_fixture_imports_a_strict_source_and_not_the_reverse_2767','corpus/ledger/features/std-package.gandr','#533 #2993','#2938 #3029 #3047 #3069 #3072 #3095 #3175');
INSERT INTO feature VALUES('store-facade','storage','One store over both planes and named roots',NULL,'implemented','ordinary',NULL,'One `Store` opens a directory holding the value plane''s chunks, the record plane''s nodes and a record tree of named roots, each object a file named by its digest. A value commits under the store''s profile and its own codec to a pointer, a digest and an offset, that reads back in any process opening the same directory; an object changed on disk is refused by the plane holding it against its digest; and a root one store sets is kept by another setting its own over the same directory. `gandr check` and `gandr lock` open it under the XDG data home, the lock records each dependency''s identity by a pointer into it, and `gandr check` commits each package whose sources settle as its export, every kernel artifact the walk admitted under its sources'' paths, named by `export/<package address>`. Once every export of the run is committed, a dependent''s check reads each path dependency''s export by that root and replays each of its artifacts alone through the kernel; a root naming nothing is noted, and an export the store cannot read back or the kernel refuses faults the run.','storage-store surface-dispatcher surface-driver','crates/storage-store/tests/store.rs crates/surface-dispatcher/tests/package.rs::a_pointer_the_store_cannot_answer_leaves_the_dependent_unaddressed_3157 crates/surface-driver/tests/cli.rs::a_package_s_lock_points_into_the_store_the_run_opens_3157 crates/surface-dispatcher/tests/package.rs::a_package_s_export_holds_what_its_check_admitted_3225 crates/surface-driver/tests/cli.rs::a_checked_package_s_export_is_named_by_its_address_3225 crates/surface-dispatcher/tests/package.rs::a_dependency_s_export_is_re_admitted_through_the_kernel_3285 crates/surface-driver/tests/cli.rs::a_dependent_re_admits_its_dependency_s_export_3285',NULL,'#2765 #2799 #3225 #3285','#3157 #3274 #3302');
INSERT INTO feature VALUES('strict-corpus-root','corpus','The strict and fixture roots','corpus-expectations','implemented','ordinary',NULL,'The strict root admits only `checks` and its refinements; the fixture root, a `fixture` or a `ledger` directory, admits stated refusals and obligations. A unit laid from sources under both roots settles each source''s declarations under its own root, whatever order the paths are given in.','surface-corpus surface-dispatcher','strict/values.gandr crates/surface-dispatcher/src/walk.rs::walk::tests::each_source_of_a_component_settles_under_its_own_root_3100','crates/surface-corpus/strict/values.gandr',NULL,'0dd5b3d #1749 #3141');
INSERT INTO feature VALUES('string-model','effects','A string written in the language','temporary-access','partial','uncommon','mainstream languages','A string written as a corpus subject in the language itself: its bytes inline up to a capacity or in a buffer with a holder count, UTF-8 encoding of code points, a trailing zero for a C reading refused at an interior zero, copy-on-write that copies a buffer only when another string holds it, the in-place write a one-holder string licenses, and views lent by an access or kept in the region of a scope around it. The builtin `String` is not yet replaced by it.','surface-corpus surface-dispatcher','corpus/model/strings/string-base.gandr corpus/model/strings/copy-on-write.gandr corpus/model/strings/views.gandr corpus/pathological/strings/views.gandr','corpus/ledger/features/string-model.gandr','#2971 #1219','#1260 #2722');
INSERT INTO feature VALUES('structural-recursion','recursion','Structural recursion with marked calls',NULL,'implemented','notable',NULL,'def rec f lowers to the core fixpoint staging the parameter its matches take apart, and a call written f[<] carries descent evidence the kernel replays.','core-checker kernel-core core-nbe','corpus/model/data/recursive-addition.gandr','corpus/ledger/features/structural-recursion.gandr',NULL,'#95 #1615');
INSERT INTO feature VALUES('sugared-spelling','printing','Sugared and explicit spellings','presentation-printer','implemented','ordinary',NULL,'Every printing face chooses the most-sugared form or the explicit one, sugared by default; the formatter is at token parity with the printer over whole declarations, bodies included, the declarations held out named by issue. A reduct the checker applies is written as its call in the explicit form, and a written call of one the checker would apply is left to it in the sugared form; so is a forgetting map the checker applies, written `forget[sort C = A](m) at Model(T)` with the carriers it solved, and a written call of a map is written as the map in the explicit form too. Either form writes a definition''s result `-F B` as `B`, the returner the lowering inserts, but a value at a world or a region, and a result `-F [E] B` as `[E] B`, the row before the type. The sugared form writes a tail''s `return f(x)` or `return x + y` as the call, which the checker elaborates alike. A thunk type written where a value is read, a transport''s family among them, takes the value-function alias over its domain list, `(y : A, P) => B`: the parser reads a group closing before `=>` as the alias''s domains.','surface-pretty surface-lsp surface-format surface-parser','crates/surface-pretty/src/former.rs crates/surface-pretty/tests/goldens.rs crates/surface-dispatcher/tests/parity.rs crates/surface-format/tests/rewrite.rs crates/surface-parser/tests/grammar.rs corpus/model/include/reduct.gandr corpus/model/identity/model-counter-manifest.gandr corpus/model/identity/transport-dependent.gandr corpus/model/control/effect-rows.gandr',NULL,NULL,'#347 #828 #1929 #1971 #2174 #2222 #2276 #2294 #2309 #2318 #2336 #2379 #2383 #2387 #2393');
INSERT INTO feature VALUES('syntax-ledger','workflow','The syntax ledger',NULL,'implemented','notable',NULL,'The language surface enumerated from the grammar itself — every rule and attribute, pinned by the grammar fingerprint, regenerated and compared by a gate; one verified exemplar per rule, the bijection and the mold check gated, every exemplar stating what the checker makes of its form, and every committed rule''s admission read off its exemplar''s lowering.','surface-grammar surface-dispatcher','ledger/syntax.md corpus/ledger/syntax',NULL,NULL,'#763 #770 #1749 #1761 #1762');
INSERT INTO feature VALUES('tactics-over-goals','metaprograms','Tactics over goals (~t)','typed-holes','partial','notable',NULL,'A splice `~t` written where a value is read is a hole the checker fills by running the tactic `t` at the goal the hole stands at, the binders in scope with their types and the type the value is checked against: `assumption` answers the innermost binder whose type converts with the goal, and `intro(t)` a function whose body is `t`''s answer under the binder it introduces, each new goal stated under the binders before it. The answer is judged against the goal again and written in the hole''s place, so the kernel replays the filled declaration and no tactic is trusted; a goal no binder answers, an introduction where no function is asked and a splice with no type to check it against are refused `TacticRefused`, and an operand that writes no tactic `UnknownTactic`. Tactics written in gandr, over codes of terms, wait on #2787.','core-term core-checker surface-grammar surface-lowering','corpus/model/metaprograms/tactics-over-goals.gandr corpus/pathological/metaprograms/tactics-over-goals.gandr crates/core-checker/src/tactic/tests.rs','corpus/ledger/features/tactics-over-goals.gandr','#2787','#2841');
INSERT INTO feature VALUES('tarski-universes','universes','User-written Tarski universes',NULL,'implemented','notable',NULL,'A datatype of codes with a recursive decoder checks, an open decode read as a type compared by its code; a constructor argument may be a universe or a function (W-shaped), the eliminator reaching the hypothesis through the function.','core-checker core-nbe','corpus/model/universe/closed.gandr corpus/model/universe/v-infinity.gandr corpus/model/data/w-tree.gandr corpus/pathological/universe/v-infinity.gandr corpus/model/universe/vacuous-pi.gandr corpus/pathological/universe/vacuous-pi.gandr corpus/model/universe/inductive-recursive.gandr','corpus/model/universe/closed.gandr','','#428 #580');
INSERT INTO feature VALUES('temporal-judgement','sessions','The temporal judgement (logical time as a web)','session-types','partial','uncommon','dependent provers','A session''s logical time is a two-colour causal web — each endpoint''s own order and every send before its receipt green, every other pair white — and a recorded dialogue is admitted exactly when its order linearizes the web; a receipt recorded before its send is refused by name. A source writes a binary session''s dialogue as `dialogue(left(…), right(…), …) : Dialogue(S)`, its left endpoint following `S` and its right the dual; two logs that commute independent moves are one dialogue, related by `refl`, and a receipt of another payload or label is refused as unmatched.','core-session theory-deep-inference core-term core-checker core-nbe surface-lowering','crates/core-session/tests/dialogue.rs crates/theory-deep-inference/src/causal_web.rs corpus/model/sessions/dialogue-web.gandr corpus/pathological/sessions/dialogue-web.gandr crates/core-checker/src/flow/tests.rs::a_dialogue_checks_by_its_web_and_refuses_by_move','corpus/ledger/features/temporal-judgement.gandr','#316','#1072 #2092 #2722');
INSERT INTO feature VALUES('temporary-access','effects','Temporary access (hold and access)',NULL,'implemented','uncommon','mainstream languages','A held value is lent to a view, shared or exclusive; an exclusive view must be ended exactly once, by a write-back `resume` or an `abort` that runs the unwind.','core-term core-checker','corpus/model/control/accessor-counter.gandr corpus/pathological/control/accessor-twice.gandr corpus/model/control/accessor-loop.gandr corpus/model/control/accessor-shared.gandr','corpus/model/control/accessor-counter.gandr',NULL,'#415 #1148 #1180');
INSERT INTO feature VALUES('terminal-face','tooling','The full-screen terminal face','repl','implemented','ordinary',NULL,'`gandr tui` paints the loop''s transcript, an input pane and a status line full-screen.','surface-tui','crates/surface-tui/tests/launch.rs',NULL,NULL,'1eba0d1');
INSERT INTO feature VALUES('termination-certificates','rules','Replayable termination certificates',NULL,'partial','notable',NULL,'One termination evidence form shared by rule blocks and fixpoints: a path order''s derivation over the precedence as data, each step naming the clause that orients it, which the kernel replays for an operation''s rules and a theory''s rules, the front end reads for a description''s faces and the cell layer reads to break its completion''s size ties; a size measure for a fixpoint is still to come.','theory-path-orders kernel-term theory-levitation theory-cell-complexes','crates/theory-path-orders/tests/lpo.rs corpus/model/data/rule-equation.gandr corpus/pathological/data/rule-equation-unoriented.gandr','corpus/ledger/features/termination-certificates.gandr','#314 #392','#2344 #2722');
INSERT INTO feature VALUES('termination-checker','recursion','A separate termination checker',NULL,'declined','notable',NULL,'Termination is evidence replayed by the kernel, never searched for by a checker; a fixpoint without evidence stays partial.',NULL,NULL,NULL,'#1685',NULL);
INSERT INTO feature VALUES('test-quality-map','workflow','A test-quality map','mutation-testing','planned','ordinary',NULL,'Coverage per crate beside the mutation survivors, the weakest crates first.',NULL,NULL,NULL,'#239',NULL);
INSERT INTO feature VALUES('text-primitives','types','Text, pattern and path primitives','native-primitives','partial','ordinary',NULL,'Text primitives on the machine: `string.append` writes the first string then the second, checked at its prelude signature and run on both executors, and an interpolated string `"…${ e }…"` lowers to its appends in written order and prints back as itself; `string.eq` compares two strings byte for byte, and `a == b` between strings resolves the prelude''s `EqString` model of `Eq` to it (#1832), two operands no model of `Eq` carries refused by name; `string.lt` orders two strings by their bytes, lexicographically, and `<`, `<=`, `>` and `>=` between strings resolve the prelude''s `OrdString` model of `Ord`, built on `EqString`, while between integers they resolve `OrdInteger`, the integer primitives (#2333); string escaping and scanning, regular-expression extraction and path primitives are still to come.','core-term runtime-emitter surface-lowering surface-pretty','corpus/model/builtins/simple-builtins.gandr corpus/model/builtins/strings.gandr corpus/model/modules/model-ord.gandr corpus/surface/string-interpolation.gandr crates/runtime-emitter/tests/forms.rs','corpus/ledger/features/text-primitives.gandr','#318 #1505','#1981 #2722');
INSERT INTO feature VALUES('theory-include','descriptions','Theory inclusion','signature-models','partial','notable',NULL,'A theory includes another as a function on Theory values with the morphism kept, its parts included or restricted by name; the union''s critical pairs are refused by name, and a member the including block refuses where the included one reads it is refused at the `include`, in the including block. An include names a theory its own source reads before it, or else the one a source it imports unqualified presents, two such sources refused by name; a block that gives two theories it reaches a second join among the theories it sees is refused, the pair and both joins named. A model type fixes a sort by `with sort x = A` (gandr #1306). A theory `T` takes a reduct `T.S` for each theory `S` it includes, directly or through another, the ways round a diamond one reduct: it restricts a model of `T` to the model of `S` the same module gives, by computation, and a model of `T` stands where a model of `S` is asked, the checker applying the reduct there. The explicit form writes the applied reduct as its call, `T.S(m)`; the sugared form leaves a written call to the checker where it would apply the reduct; the printer writing it and hover naming it are the next rungs.','theory-levitation surface-lowering surface-grammar core-checker core-term surface-format surface-dispatcher','corpus/model/include/monoid.gandr corpus/model/include/imported.gandr corpus/model/include/reduct.gandr corpus/model/include/reduct-explicit.gandr corpus/pathological/include/rules-join.gandr corpus/pathological/include/imported-rules.gandr corpus/pathological/include/two-joins.gandr corpus/pathological/specification/specification-monad.gandr crates/surface-lowering/tests/namespace.rs crates/surface-lowering/tests/modules/models.rs crates/core-checker/src/module/tests.rs crates/surface-dispatcher/src/format.rs','corpus/ledger/features/theory-include.gandr','#1092 #2714','#1094 #1237 #1247 #2041 #2059 #2722 #2768');
INSERT INTO feature VALUES('thunks-and-force','calculus','Thunks and forcing','call-by-push-value','implemented','notable',NULL,'A computation is suspended as a value by `thunk` and resumed by `force`, the type `+U` naming the suspension.','core-term core-nbe','corpus/model/identity/cong-thunk.gandr','corpus/model/identity/cong-thunk.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('top-level-type-members','modules','Type members at a source''s top level','modules','implemented','ordinary',NULL,'`type T = τ ;` at a source''s top level names `τ` for the declarations after it, and for every declaration of a source importing it unqualified, a synonym with parameters too, as a module''s type member does; a use before it is unresolved, a second member of the name refused, and a name two imports write refused at its use. A member whose definition is a computation type — a returner, a computation record or a function into one — stands where a computation type is read, a family too, and is refused where a value type is read, a seal''s or a functor parameter''s abstract type among them.','surface-lowering','corpus/model/modules/top-level-type.gandr corpus/model/modules/top-level-type-imported.gandr corpus/pathological/modules/top-level-type.gandr','corpus/model/modules/top-level-type.gandr',NULL,'#3108');
INSERT INTO feature VALUES('total-parsing','syntax','Total, error-tolerant parsing',NULL,'implemented','notable',NULL,'Every source parses to a molded tree, an unfinished form left open with the completion obligations that would close it. A `)` or a `]` the source left out is minted where it closes its form and the rest of its top-level form then parses — where the melder closed the form when the closer reads there, else at the nearest tile end after the form''s last written tile — and the repairs its misreading made fall away. Any other tile left out — a member''s `;`, an arm''s `=>`, a binder''s `:` or a `,` — is minted the same way for the deepest form missing one or the first, directly after the form''s last written tile when no hole comes between them, else at a later tile end outside the brackets opened since and never inside a word, where the rest parses with every tile before it read as written, every top-level form a declaration and the form nested no deeper. A top-level form whose declaration keyword is left out or misspelled, read as an expression, is read again with each keyword its first tile can follow written before it, and the first that makes it a declaration with no repair is the parse, the keyword minted at its head and owed alone. A form the parser closed at its end is refused where its written tiles first leave its rule''s shape — an operand after a tile no hole follows, or a second operand in a hole that holds one — naming the tile the rule writes there, not at the close; and a bracket written once too often or left out is refused where the declaration''s layout places it — a doubled opener at itself, a missing closer at the end of its line or before the line that comes back to its indentation, a missing opener at the end of the line its closer answers — when that comes first.','surface-parser surface-lowering','crates/surface-parser/tests/acceptance.rs crates/surface-parser/src/parse/place.rs crates/surface-lowering/src/lower.rs',NULL,NULL,'b1b373b #2241 #2251 #2265 #2316 #2472');
INSERT INTO feature VALUES('traces','sessions','A run''s channels traced as dialogues','session-machine','implemented','notable',NULL,'A `traces` beside a definition''s `runs` records the run''s plays, each channel the run forks a dialogue of its two endpoints'' moves named by the fork''s protocol binder, and states the web one channel''s play decomposes to, `traces(decomposes(c, series(…)))` or its prime count `traces(primes(c, n))`, written once per channel. The corpus settles a channel as `decomposes` settles a dialogue literal; a channel that plays another web or is never forked leaves the run outcome unsettled, both webs printed. A run without the attribute records nothing.','runtime-emitter core-sequent surface-lowering surface-pretty surface-dispatcher surface-corpus','corpus/model/tasks/forced.gandr corpus/model/tasks/spoken-first.gandr corpus/model/tasks/independent.gandr corpus/model/sessions/seat-exchange.gandr corpus/ledger/attributes/traces.gandr crates/runtime-emitter/tests/sessions.rs::a_traced_run_plays_each_channel_as_its_dialogue crates/surface-dispatcher/src/evaluate.rs::a_traced_run_names_each_channel_by_its_fork_3338 crates/surface-corpus/src/settle.rs::a_channel_settles_against_the_web_its_play_decomposes_to_3338 crates/surface-driver/tests/cli.rs::a_stated_web_the_run_does_not_produce_is_unsettled_3338','corpus/model/tasks/forced.gandr',NULL,'#3366');
INSERT INTO feature VALUES('trailing-delimiters','syntax','Trailing commas and leading arm bars',NULL,'implemented','ordinary',NULL,'A list may end in a comma and a match''s first arm may begin with a bar.','surface-grammar','strict/trailing-delimiters.gandr','crates/surface-corpus/strict/trailing-delimiters.gandr',NULL,'#141');
INSERT INTO feature VALUES('transport','identity','Transport','identity-types','implemented','notable',NULL,'`transport(P, p, v)` moves an element along an identification through a family; a record moves field by field under its labels, and a suspension whose run performs no effect runs, forced, and its result moves on. A value declared as a transport is computed the first time a run reads it, and every later read is that answer; a transport written where a value is read — a call''s argument, a tuple''s component, a constructor''s field, a case''s scrutinee — runs before what reads it.','core-checker core-nbe core-term kernel-core core-sequent runtime-emitter','corpus/model/identity/transport-path.gandr corpus/model/identity/transport-list.gandr corpus/model/identity/flow-large.gandr corpus/model/modules/model-manifest-type.gandr corpus/model/data/one-shape-families.gandr','corpus/ledger/features/transport.gandr',NULL,'#204 #1099 #1852 #1953 #1954 #2145 #2152');
INSERT INTO feature VALUES('two-layouts-one-code','layouts','Two layouts of one code',NULL,'partial','uncommon','mainstream languages','A data type''s memory layout is a second data type over the same code, admitted by an equivalence with it whose round trips are proved by recursion and replayed by the kernel (Baudon''s Ribbit, Example 3.4): a list of `i32` laid out pointer-tagged and packed two elements per pointer is each layout by `ua`, a value moves from one layout to the other along their composite, formed at the transport until a named one checks (#2995), and `length`, written once over the list, runs on both by transport. A layout that loses elements is refused at its round trip. The layouts are data, not bytes: no memory type is a value yet, code emitted from a layout stands outside the trust boundary, and `equiv` decides no round trip over a type that holds itself (#1316).',NULL,'corpus/model/layouts/ribbit-list.gandr corpus/pathological/layouts/ribbit-list.gandr','corpus/ledger/features/two-layouts-one-code.gandr','#1316 #2804 #2805 #2995','#3002');
INSERT INTO feature VALUES('type-codes','universes','Type codes and decoding',NULL,'implemented','uncommon','mainstream languages','A type is quoted as a code in a universe and decoded back, a function into a universe read as a type where one is expected; a call of a definition that runs to a variable''s call reads as that call, so the two convert. A type with no expression reading is written type(T) in expression position, the written quote beside the positional one. A quoted session type''s payloads read no variable bound around the quote, as the kernel forms them; a run''s protocol, which stays on the checker''s side, may.','core-term core-checker kernel-core','corpus/model/desc/generic-arity.gandr corpus/model/sessions/type-quote.gandr corpus/pathological/sessions/type-quote.gandr corpus/model/universe/family-at-call.gandr','corpus/model/desc/generic-arity.gandr',NULL,'b87a65d #1149 #1748 #2777');
INSERT INTO feature VALUES('typed-holes','checking','Typed holes and goals',NULL,'implemented','notable',NULL,'A hole stands for missing source, is typed where it stands, and is filled by name with the rest of the program still checking.','core-term core-checker','corpus/fragment/addressable-obligation.gandr','corpus/fragment/addressable-obligation.gandr',NULL,'#91');
INSERT INTO feature VALUES('unification','checking','Unification and index refinement',NULL,'planned','notable',NULL,'Unification at a scrutinee''s type refines the context by a match, a clash a refutation and a conversion failure a refusal.',NULL,NULL,NULL,'#391',NULL);
INSERT INTO feature VALUES('uniqueness-of-identity-proofs','identity','Uniqueness of identity proofs',NULL,'declined','notable',NULL,'Identity is untruncated by design, so no type is forced to be a set.',NULL,NULL,NULL,'#1686',NULL);
INSERT INTO feature VALUES('unit-readings','workflow','Readings considered on every axis',NULL,'implemented','ordinary',NULL,'Every unit answers the seven reading axes with its reason, the seventh, `zero-cost`, asking what the change adds at run time and what demands it. `unit:check` refuses an issue''s row that is not `yes — <what it gives>` or `no — <why it does not reach it>`; `pr:open` refuses a pull request''s row that is not `answered:`, `trivial:`, `not applicable:` with its clause or `deferred: #n`, and a selected axis answered otherwise without a `departed:` source; `claim:next` claims a unit whose readings hold the migration''s `unstated` placeholder and prints their questions first, and `pr:open` refuses its landing until the seat has restated them on the issue. Each refusal quotes the axis''s question, and the issue and pull request templates carry it.',NULL,'.config/claims/unit.json .config/claims/opening.json .config/claims/next.json',NULL,NULL,'#2975 #2981 #3252');
INSERT INTO feature VALUES('univalence-axiom','identity','Univalence on a record''s laws (ua)',NULL,'partial','uncommon','dependent provers','`ua(e)` makes a bi-invertible record `e : A ≃ B` a path `Path(Type, A, B)` at any two codes, admitted on its laws as typed evidence; transport along it applies the record''s map by conversion; `ua ∘ idtoequiv` and `idtoequiv ∘ ua` are owed until #520 proves them. Transport along ua(e) runs in the machine (#708): the path lowered to its two-map record, the motive by shape (identity, constant, product, sum, list); transport back along `ua(e)` applies the record''s left inverse, and along `p then ua(e)` moves along `p`, then the forward map, and a function moves along `ua(e)` by the record''s maps, its argument back by the left inverse and its result forward, in both checkers, and the machine runs each: the motive by shape (identity, constant, product, sum, list, a pure function, a path between types moving at an endpoint), a transport along `back` or `then` running the transport that computes it first.','kernel-term kernel-core core-term core-nbe core-checker core-sequent surface-lowering','corpus/model/identity/univalence.gandr corpus/pathological/identity/univalence.gandr corpus/model/identity/univalence-back.gandr corpus/model/identity/univalence-then.gandr corpus/model/identity/univalence-function.gandr corpus/model/identity/transport-path.gandr corpus/model/identity/univalence-transports.gandr corpus/model/identity/certificate-transport.gandr','corpus/ledger/features/univalence-axiom.gandr','#312 #520','#692 #958 #984 #990 #1103 #2722');
INSERT INTO feature VALUES('univalence-per-stratum','identity','Univalence by certified conversion (ua[n, k])',NULL,'implemented','unique','dependent provers','`ua[n, k]` turns an equivalence of presentations into a path in the universe at every stratum the site certifies, replayed by the kernel and never postulated.','core-checker kernel-core theory-sites','corpus/model/higher-cells/ua-corolla.gandr corpus/model/higher-cells/ua-corolla-strata.gandr corpus/model/higher-cells/ua-by-hand.gandr','corpus/model/higher-cells/ua-corolla.gandr',NULL,'#263');
INSERT INTO feature VALUES('univalence-theorem','identity','Univalence as a theorem over the reflected site',NULL,'planned','unique','dependent provers','`ua_n` proved in gandr by induction on degree over the reflected site, with the primitive checked against it at every stratum.',NULL,'corpus/model/higher-cells/ua-type.gandr corpus/model/identity/univalence-transports.gandr corpus/model/identity/funext-from-ua.gandr corpus/model/identity/arena-order.gandr corpus/pathological/identity/univalence-owed.gandr',NULL,'#312',NULL);
INSERT INTO feature VALUES('universe-families','universes','Value and computation universe families',NULL,'partial','notable',NULL,'Two universe families indexed by polarity and level over one level algebra, with an erased static core beneath the surface.','core-term core-checker','corpus/classifier/static-beta.gandr','corpus/ledger/features/universe-families.gandr','#315','#1083 #2722');
INSERT INTO feature VALUES('universe-lifts','universes','Universe lifts','universes','implemented','notable',NULL,'A type moves to a higher universe by a recorded lift whose strictness formation gates.','core-checker kernel-core','crates/core-checker/src/bridge/tests.rs','corpus/ledger/features/universe-lifts.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('universe-paths','identity','Paths between types (Path_U)','identity-types','implemented','uncommon','mainstream languages','An identification between two types is native kernel syntax built from reflexivity, equivalences and products of paths.','core-term kernel-core kernel-term','corpus/model/higher-cells/ua-by-hand.gandr','corpus/model/higher-cells/ua-by-hand.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('universes','universes','Universe hierarchy',NULL,'implemented','uncommon','mainstream languages','Types are classified by universes at levels built from zero, variables, successor and maximum, in a value and a computation tower.','core-term core-checker kernel-strata','corpus/classifier/universe-refusals.gandr','corpus/classifier/universe-refusals.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('value-crossing','runtime','A run''s values crossing worlds by content','runtime-lam','partial','notable',NULL,'A value a store binds commits to the content-addressed value plane and derefs into another store at addresses fresh there: a literal of every kind, and a tuple, record, list, injection, lift or datatype''s constructor over crossing fields, a family as its declaration''s index. A value shared twice crosses unfolded and derefs as a tree, a pair shared at twenty levels writing 7,340,029 records into 5 chunks; a thunk crosses as its body''s command and its captures, and the run it lands in lays it out at its own site for that body; a closure, stack, code, capability, opaque constant or session record is refused by name with nothing written, and a payload the codec does not write refuses its constructor. A migration''s captures and answer cross through it (world-migration), between processes too (migrate-wire); a family named by content across processes is owed (#3293).','runtime-emitter','crates/runtime-emitter/tests/crossing.rs','crate-tests','#3293','#3248 #3282 #3315');
INSERT INTO feature VALUES('value-plane','storage','The content-addressed value plane',NULL,'implemented','notable',NULL,'A value commits as a typed chunk DAG and dereferences from any content pointer, every chunk verified against its identity.','storage-values','crates/storage-values/tests/values.rs crates/storage-values/tests/laws.rs',NULL,NULL,'74a7618');
INSERT INTO feature VALUES('virtual-double-categories','identity','Virtual double categories and reflected judgements','univalence-theorem','implemented','notable',NULL,'Virtual double categories with directed laws over replayable rewriting evidence, awaiting the reflected site as their consumer.','theory-virtual-doctrines','crates/theory-virtual-doctrines/tests/lib.rs','crate-tests','#312','#72');
INSERT INTO feature VALUES('visibility','modules','Private by default, exported by `pub`','imports','implemented','ordinary',NULL,'A declaration is private to its source unless a `pub` mark stands before it: an importer reads only the exported names, constructors and members of an exported declaration among them, a private name neither resolves nor clashes there and is refused as private by name, and the editor offers to import only an exported name.','surface-lowering surface-grammar surface-format surface-lsp','corpus/ledger/syntax/pub-declaration.gandr crates/surface-lowering/tests/namespace.rs','corpus/ledger/syntax/pub-declaration.gandr',NULL,'#2781');
INSERT INTO feature VALUES('vscode-extension','editor','The VS Code extension',NULL,'implemented','ordinary',NULL,'An extension that starts `gandr lsp` for VS Code, with role colours for hover.','contrib/gandr-vscode','contrib/gandr-vscode',NULL,NULL,'#131');
INSERT INTO feature VALUES('web-decomposition','rewriting','The modular decomposition of a causal web','derivation-identity','implemented','notable',NULL,'A causal web''s precedence decomposes into its strong modules as a flat id-addressed tree (series, parallel and prime nodes, a prime''s factors carrying the quotient precedence); the tree reads every pair back, a series-parallel web has no prime, a cycle is refused by its first vertex. A program reads a dialogue''s web as data, `decompose(d) : Web`, printed `series(…)`, `parallel(…)` and `prime(…)` over the leaves `event(left, n)` and `event(right, n)`, alike on both executors; a corpus states the web a dialogue reads back as `@[ decomposes(series(…)) ]` on the dialogue itself, the tree unquoted, or its prime count alone as `@[ decomposes(primes = n) ]`. The checker''s normalizer evaluates the decomposition of a dialogue literal or of a definition naming one, so two logs of one dialogue have one web by reflexivity and two webs of different shapes are apart. A traced run is the second producer of a dialogue: each channel it forks plays one, decomposed alike and stated beside its `runs` as `traces(decomposes(c, …))` (traces).','theory-deep-inference core-session core-term runtime-emitter surface-lowering surface-pretty core-nbe surface-corpus surface-dispatcher','corpus/model/sessions/dialogue-web.gandr corpus/pathological/sessions/dialogue-web.gandr corpus/ledger/attributes/decomposes.gandr corpus/model/tasks/forced.gandr crates/runtime-emitter/tests/forms.rs::each_form_ends_alike_on_both_executors_as_its_program_states crates/core-nbe/src/identity/tests.rs::a_decomposition_converts_with_the_web_it_reads_back_as crates/core-nbe/src/identity/tests.rs::a_named_dialogue_decomposes_through_its_definition crates/surface-corpus/src/settle.rs::a_web_settles_against_the_dialogue_s_decomposition_2077 crates/surface-corpus/src/expectation.rs::a_counted_web_reads_its_prime_nodes_2077','corpus/model/sessions/dialogue-web.gandr',NULL,'#1197 #2092 #2117 #2142 #2156 #3366');
INSERT INTO feature VALUES('wildcards','checking','Wildcards: terms the equations force','implicit-arguments','implemented','ordinary',NULL,'`_` written where a value is read, in a call''s argument, an instantiation slot or an ascription''s type, stands for the term the equations force, the elaborator''s to answer where a hole is the author''s: it is a metavariable of the solver omitted implicits use, bound only where a comparison forces a most general solution, and the body is emitted with that term written, so the kernel never meets it. A wildcard an ascription''s type holds is forced by the term ascribed, through reflexivity''s endpoints or the value bridge. Its hole is named as a wildcard''s, apart from an omitted implicit''s, so a body printed before the checker fills it writes each wildcard back as `_`. A wildcard nothing forces is ImplicitUnsolved, and one where a computation or a type is read is a form of the wrong sort.','surface-grammar surface-lowering core-term core-checker surface-pretty surface-diagnostics','corpus/model/holes/wildcard.gandr corpus/pathological/holes/wildcard.gandr corpus/ledger/syntax/wildcard.expression.gandr crates/surface-lowering/src/lower/implicit/tests.rs::a_wildcard_emits_the_body_written_by_hand_528 crates/surface-pretty/tests/goldens.rs::a_call_writes_the_wildcards_it_holds_528 crates/core-checker/src/bridge/tests.rs::an_ascription_solves_the_wildcard_its_type_holds_1979','corpus/model/holes/wildcard.gandr',NULL,'#1992 #2065');
INSERT INTO feature VALUES('without-k','identity','The without-K discipline','identity-types','implemented','notable',NULL,'Axiom K is refused by name, so identifications of identifications stay proof-relevant.','core-checker','corpus/pathological/identity/k-derivation.gandr corpus/model/identity/circle-apart.gandr','corpus/model/identity/circle-apart.gandr',NULL,'b87a65d');
INSERT INTO feature VALUES('work-pool','tooling','The work pool',NULL,'partial','notable',NULL,'One driver-held rayon pool the walk, the staging and the formatter fork on, lazy, with the serial fork as the reference; the other consumers move onto it rung by rung, the pool''s start cost above the default width rung 4''s.','surface-dispatcher','crates/surface-driver/benches/hotpath.rs',NULL,'#1250','#1341 #1352');
INSERT INTO feature VALUES('world-migration','runtime','A migration running at its world in one process','located-judgements','implemented','unique','mainstream languages','`migrate [w] { t }` runs `t` on a thread and over a store of its own, closed over its captures, each crossed in by content through the one chunk store the process holds and the answer crossed back the same way, on both tiers; `hold v` runs to `v` and `leta x = h ; t` binds `x` to it, a handle in one process being its content. A thunk the checker lets cross by its image runs at the caller, laid out at the site the caller''s function keeps for its body. A field the caller projects from a record a migration answers reads as it does in place, since the caller''s selections table every record head the program builds. A capture or answer that does not cross declines the run at the migration. A host whose world bindings bind the world to another process ships the migration there (migrate-wire).','core-sequent runtime-emitter','corpus/ledger/features/world-migration.gandr corpus/model/worlds/twice.gandr corpus/model/worlds/open.gandr corpus/model/worlds/seat-and-operator.gandr corpus/model/worlds/closure-axes.gandr crates/runtime-emitter/tests/world.rs','corpus/ledger/features/world-migration.gandr',NULL,'#3268 #3282 #3298 #3315');
INSERT INTO feature VALUES('zero-drift','incremental','Zero-drift verdicts','incremental-checking','partial','notable',NULL,'An unchanged input yields a byte-identical verdict on every incremental surface.','surface-session surface-lsp core-incremental','crates/surface-session/tests/incremental.rs crates/surface-lsp/tests/session.rs',NULL,'#320','#1063');
